INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'partial-denture'), 'A removable denture that replaces several missing teeth and rests on the remaining teeth and gums', 'Pokretna proteza koja zamjenjuje nekoliko zuba koji nedostaju i naslanja se na preostale zube i sluznicu', 'Покретна протеза која замјењује неколико зуба који недостају и наслања се на преостале зубе и слузницу', 'Съёмный протез, замещающий несколько отсутствующих зубов и опирающийся на сохранившиеся зубы и слизистую', 'Eine herausnehmbare Prothese, die mehrere fehlende Zähne ersetzt und sich auf die restlichen Zähne und die Schleimhaut abstützt', 'Eksik olan birkaç dişi tamamlayan, kalan dişlere ve diş etine dayanan hareketli protez', 'Taking impressions, fabrication in a dental laboratory, try-in and fitting in the mouth; usually 3-4 visits over 2-3 weeks', 'Uzimanje otisaka, izrada u zubotehničkoj laboratoriji, proba i prilagođavanje u ustima; obično 3-4 posjete tokom 2-3 nedjelje', 'Узимање отисака, израда у зуботехничкој лабораторији, проба и прилагођавање у устима; обично 3-4 посјете током 2-3 недјеље', 'Снятие слепков, изготовление в зуботехнической лаборатории, примерка и припасовка в полости рта; обычно 3-4 визита в течение 2-3 недель', 'Abdrucknahme, Anfertigung im zahntechnischen Labor, Anprobe und Einpassen im Mund; in der Regel 3-4 Termine über 2-3 Wochen', 'Ölçü alınması, diş laboratuvarında üretim, prova ve ağızda uyumlama; genellikle 2-3 hafta içinde 3-4 seans', 'Several missing teeth, when implants or a fixed bridge are not suitable for medical or financial reasons', 'Nedostatak nekoliko zuba, kada implantacija ili fiksni most nisu odgovarajući iz medicinskih ili finansijskih razloga', 'Недостатак неколико зуба, када имплантација или фиксни мост нису одговарајући из медицинских или финансијских разлога', 'Отсутствие нескольких зубов, когда имплантация или мостовидный протез не подходят по медицинским или финансовым причинам', 'Mehrere fehlende Zähne, wenn Implantate oder eine festsitzende Brücke aus medizinischen oder finanziellen Gründen nicht in Frage kommen', 'Birkaç dişin eksik olması ve implant ya da sabit köprünün tıbbi veya maddi nedenlerle uygun olmaması', 'Oral health should be addressed first — treating cavities, removing non-restorable teeth, professional cleaning', 'Sanacija usne duplje prije početka — liječenje karijesa, vađenje zuba koji se ne mogu sačuvati, profesionalno čišćenje', 'Санација усне дупље прије почетка — лијечење каријеса, вађење зуба који се не могу сачувати, професионално чишћење', 'Санация полости рта до начала работы — лечение кариеса, удаление нежизнеспособных зубов, профессиональная чистка', 'Vorab Sanierung der Mundhöhle — Behandlung von Karies, Entfernung nicht erhaltungsfähiger Zähne, professionelle Zahnreinigung', 'Öncesinde ağız sağlığının düzenlenmesi — çürük tedavisi, kurtarılamayan dişlerin çekilmesi, profesyonel temizlik', 'Rubbing of the gums and increased salivation during the first days of adaptation are normal; persistent pain, sores under the denture, or loosening of the supporting teeth are reasons for an adjustment by the dentist', 'Žuljanje sluznice i pojačano stvaranje pljuvačke prvih dana privikavanja su uobičajeni; bol koja ne prolazi, ranice pod protezom ili klaćenje nosećih zuba razlog su za korekciju kod stomatologa', 'Жуљање слузнице и појачано стварање пљувачке првих дана привикавања су уобичајени; бол која не пролази, ранице под протезом или клаћење носећих зуба разлог су за корекцију код стоматолога', 'Натирание слизистой и повышенное слюноотделение в первые дни привыкания — обычное явление; сохраняющаяся боль, ранки под протезом или расшатывание опорных зубов — повод для коррекции у стоматолога', 'Reiben der Schleimhaut und verstärkter Speichelfluss in den ersten Tagen der Eingewöhnung sind normal; anhaltende Schmerzen, Druckstellen unter der Prothese oder eine Lockerung der Haltezähne sind ein Grund für eine Korrektur beim Zahnarzt', 'Alışma döneminin ilk günlerinde diş etinde tahriş ve tükürük artışı normaldir; geçmeyen ağrı, protez altında yaralar veya destek dişlerin sallanması diş hekiminde düzeltme gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'skeletal-partial-denture'), 'A partial removable denture built on a cast metal framework — thinner and stronger than an acrylic one', 'Parcijalna pokretna proteza na livenom metalnom skeletu — tanja je i čvršća od akrilatne', 'Парцијална покретна протеза на ливеном металном скелету — тања је и чвршћа од акрилатне', 'Частичный съёмный протез на литом металлическом каркасе (бюгельный) — тоньше и прочнее акрилового', 'Eine herausnehmbare Teilprothese auf einem gegossenen Metallgerüst (Modellgussprothese) — dünner und stabiler als eine Kunststoffprothese', 'Döküm metal iskelet üzerine yapılan bölümlü hareketli protez — akrilik protezden daha ince ve daha dayanıklıdır', 'Impressions, fabrication of the metal framework in the laboratory, try-ins with tooth set-up, and final fitting; usually 4-5 visits over 3-4 weeks', 'Otisci, izrada metalnog skeleta u laboratoriji, probe sa postavljanjem zuba i konačno prilagođavanje; obično 4-5 posjeta tokom 3-4 nedjelje', 'Отисци, израда металног скелета у лабораторији, пробе са постављањем зуба и коначно прилагођавање; обично 4-5 посјета током 3-4 недјеље', 'Слепки, изготовление металлического каркаса в лаборатории, примерки с постановкой зубов и окончательная припасовка; обычно 4-5 визитов в течение 3-4 недель', 'Abdrücke, Anfertigung des Metallgerüsts im Labor, Anproben mit Zahnaufstellung und endgültiges Einpassen; in der Regel 4-5 Termine über 3-4 Wochen', 'Ölçüler, laboratuvarda metal iskeletin üretimi, diş dizimiyle provalar ve son uyumlama; genellikle 3-4 hafta içinde 4-5 seans', 'Several missing teeth with healthy supporting teeth, when a stronger and less bulky design than an acrylic denture is needed', 'Nedostatak nekoliko zuba uz zdrave noseće zube, kada je potrebna čvršća i manje obimna konstrukcija od akrilatne proteze', 'Недостатак неколико зуба уз здраве носеће зубе, када је потребна чвршћа и мање обимна конструкција од акрилатне протезе', 'Отсутствие нескольких зубов при сохранных опорных зубах, когда нужна более прочная и менее объёмная конструкция, чем акриловый протез', 'Mehrere fehlende Zähne bei erhaltenen Haltezähnen, wenn eine stabilere und weniger voluminöse Konstruktion als eine Kunststoffprothese benötigt wird', 'Destek dişlerin sağlam olduğu birkaç diş eksikliği ve akrilik protezden daha dayanıklı, daha az hacimli bir yapı gerektiğinde', 'Oral health should be addressed first; supporting teeth are reinforced with crowns if necessary', 'Sanacija usne duplje; noseći zubi se po potrebi ojačavaju krunama', 'Санација усне дупље; носећи зуби се по потреби ојачавају крунама', 'Санация полости рта; опорные зубы при необходимости укрепляют коронками', 'Sanierung der Mundhöhle; Haltezähne werden bei Bedarf mit Kronen verstärkt', 'Ağız sağlığının düzenlenmesi; gerekirse destek dişler kronla güçlendirilir', 'Getting used to the clasps and a sense of a foreign body during the first 1-2 weeks is normal; pain under the framework, a change in the bite, or chipped facings are reasons to see the dentist', 'Privikavanje na kvačice i osjećaj stranog tijela prvih 1-2 nedjelje su uobičajeni; bol pod skeletom, promjena zagriza ili okrznuta faseta razlog su za posjetu stomatologu', 'Привикавање на квачице и осјећај страног тијела првих 1-2 недјеље су уобичајени; бол под скелетом, промјена загриза или окрзнута фасета разлог су за посјету стоматологу', 'Привыкание к кламмерам и ощущение инородного тела в первые 1-2 недели — обычное явление; боль под каркасом, изменение прикуса или сколы облицовки — повод обратиться к стоматологу', 'Die Eingewöhnung an die Klammern und ein Fremdkörpergefühl in den ersten 1-2 Wochen sind normal; Schmerzen unter dem Gerüst, eine Veränderung des Bisses oder abgeplatzte Verblendungen sind ein Grund, den Zahnarzt aufzusuchen', 'İlk 1-2 hafta kancalara alışma ve yabancı cisim hissi normaldir; iskelet altında ağrı, kapanışta değişiklik veya kaplamada kırılma diş hekimine başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'skeletal-denture'), 'A removable denture with a metal bar that distributes the load between the supporting teeth and the gums', 'Skeletirana proteza — pokretna konstrukcija sa metalnim lukom koji raspoređuje opterećenje između nosećih zuba i sluznice', 'Скелетирана протеза — покретна конструкција са металним луком који распоређује оптерећење између носећих зуба и слузнице', 'Бюгельный протез — съёмная конструкция с металлической дугой, распределяющей нагрузку между опорными зубами и слизистой', 'Eine herausnehmbare Prothese mit einem Metallbügel, der die Belastung zwischen Haltezähnen und Schleimhaut verteilt', 'Yükü destek dişler ile diş eti arasında paylaştıran metal bar içeren hareketli protez', 'Impressions, planning of the supports, fabrication of the bar and tooth set-up in the laboratory, fitting; usually 4-5 visits over 3-4 weeks', 'Otisci, planiranje nosača, izrada luka i postavljanje zuba u laboratoriji, prilagođavanje; obično 4-5 posjeta tokom 3-4 nedjelje', 'Отисци, планирање носача, израда лука и постављање зуба у лабораторији, прилагођавање; обично 4-5 посјета током 3-4 недјеље', 'Слепки, планирование опор, изготовление дуги и постановка зубов в лаборатории, припасовка; обычно 4-5 визитов в течение 3-4 недель', 'Abdrücke, Planung der Verankerung, Anfertigung des Bügels und Zahnaufstellung im Labor, Einpassen; in der Regel 4-5 Termine über 3-4 Wochen', 'Ölçüler, destek planlaması, laboratuvarda barın üretimi ve diş dizimi, uyumlama; genellikle 3-4 hafta içinde 4-5 seans', 'Partial tooth loss, especially when back teeth are missing on one or both sides', 'Djelimičan nedostatak zuba, posebno kada nema bočnih zuba sa jedne ili obje strane', 'Дјелимичан недостатак зуба, посебно када нема бочних зуба са једне или обје стране', 'Частичное отсутствие зубов, особенно при отсутствии боковых зубов с одной или обеих сторон', 'Teilweiser Zahnverlust, besonders wenn Seitenzähne auf einer oder beiden Seiten fehlen', 'Kısmi diş eksikliği, özellikle bir veya iki tarafta arka dişlerin bulunmaması', 'Treatment of cavities and gum disease, and crowns on the supporting teeth if needed', 'Liječenje karijesa i bolesti desni, po potrebi krune na nosećim zubima', 'Лијечење каријеса и болести десни, по потреби круне на носећим зубима', 'Лечение кариеса и заболеваний дёсен, при необходимости — коронки на опорных зубах', 'Behandlung von Karies und Zahnfleischerkrankungen, bei Bedarf Kronen auf den Haltezähnen', 'Çürük ve diş eti hastalıklarının tedavisi, gerekirse destek dişlere kron yapılması', 'Mild discomfort and slightly altered speech during the adaptation period are normal; constant pain, mobility of the supporting teeth, or cracks in the denture require a dental check-up', 'Blaga nelagodnost i izmijenjen izgovor tokom privikavanja su normalni; stalna bol, klaćenje nosećih zuba ili pukotine na protezi zahtijevaju pregled kod stomatologa', 'Блага нелагодност и измијењен изговор током привикавања су нормални; стална бол, клаћење носећих зуба или пукотине на протези захтијевају преглед код стоматолога', 'Лёгкий дискомфорт и нарушение дикции в период привыкания — норма; постоянная боль, подвижность опорных зубов или трещины на протезе требуют осмотра стоматолога', 'Leichtes Unbehagen und eine etwas veränderte Aussprache während der Eingewöhnung sind normal; dauerhafte Schmerzen, Lockerung der Haltezähne oder Risse in der Prothese erfordern eine zahnärztliche Kontrolle', 'Alışma sürecinde hafif rahatsızlık ve konuşmada küçük değişiklik normaldir; sürekli ağrı, destek dişlerin sallanması veya protezde çatlak diş hekimi kontrolü gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'complete-denture'), 'A full removable denture that replaces all teeth in one jaw and rests on the gums', 'Totalna pokretna proteza koja zamjenjuje sve zube jedne vilice i naslanja se na sluznicu', 'Тотална покретна протеза која замјењује све зубе једне вилице и наслања се на слузницу', 'Полный съёмный протез, замещающий все зубы одной челюсти и опирающийся на слизистую', 'Eine Vollprothese, die alle Zähne eines Kiefers ersetzt und sich auf die Schleimhaut abstützt', 'Bir çenedeki tüm dişleri tamamlayan ve diş etine dayanan tam hareketli protez', 'Impressions, bite registration, try-in of a wax model and fabrication of the finished denture, followed by adjustments; usually 4-5 visits over 3-4 weeks', 'Otisci, određivanje zagriza, proba voštanog modela i izrada gotove proteze, potom korekcije; obično 4-5 posjeta tokom 3-4 nedjelje', 'Отисци, одређивање загриза, проба воштаног модела и израда готове протезе, потом корекције; обично 4-5 посјета током 3-4 недјеље', 'Слепки, определение прикуса, примерка воскового шаблона и изготовление готового протеза, затем коррекции; обычно 4-5 визитов в течение 3-4 недель', 'Abdrücke, Bissregistrierung, Anprobe einer Wachsaufstellung und Anfertigung der fertigen Prothese, danach Korrekturen; in der Regel 4-5 Termine über 3-4 Wochen', 'Ölçüler, kapanış kaydı, mum prova ve bitmiş protezin üretimi, ardından düzeltmeler; genellikle 3-4 hafta içinde 4-5 seans', 'Complete tooth loss in a jaw, when implants are not planned or not possible', 'Potpuni nedostatak zuba u vilici, kada implantacija nije planirana ili nije moguća', 'Потпуни недостатак зуба у вилици, када имплантација није планирана или није могућа', 'Полное отсутствие зубов на челюсти, когда имплантация не планируется или невозможна', 'Vollständiger Zahnverlust in einem Kiefer, wenn Implantate nicht geplant oder nicht möglich sind', 'Bir çenede tüm dişlerin eksik olması ve implant planlanmaması ya da mümkün olmaması', 'Healing of the sockets after tooth extractions (usually 1-2 months) and assessment of the gums', 'Zarastanje alveola nakon vađenja zuba (obično 1-2 mjeseca) i pregled stanja sluznice', 'Зарастање алвеола након вађења зуба (обично 1-2 мјесеца) и преглед стања слузнице', 'Заживление лунок после удаления зубов (обычно 1-2 месяца), осмотр состояния слизистой', 'Abheilung der Alveolen nach Zahnentfernungen (in der Regel 1-2 Monate) und Beurteilung der Schleimhaut', 'Diş çekimlerinden sonra çekim boşluklarının iyileşmesi (genellikle 1-2 ay) ve diş etinin değerlendirilmesi', 'Sore spots, increased salivation, and difficulty speaking are possible in the first 2-3 weeks — this is the adaptation period; painful spots are resolved by adjustment, and a denture that no longer stays in place needs relining', 'Prvih 2-3 nedjelje mogući su žuljevi, pojačano stvaranje pljuvačke i otežan govor — to je period prilagođavanja; bolna mjesta se rješavaju korekcijom, a proteza koja se više ne drži dobro zahtijeva podlaganje', 'Првих 2-3 недјеље могући су жуљеви, појачано стварање пљувачке и отежан говор — то је период прилагођавања; болна мјеста се рјешавају корекцијом, а протеза која се више не држи добро захтијева подлагање', 'Первые 2-3 недели возможны натирания, повышенное слюноотделение и трудности с речью — это период адаптации; болезненные точки устраняются коррекцией, а протез, который стал плохо держаться, требует перебазировки', 'In den ersten 2-3 Wochen sind Druckstellen, verstärkter Speichelfluss und Sprechschwierigkeiten möglich — das ist die Eingewöhnungsphase; schmerzhafte Stellen werden durch eine Korrektur behoben, und eine Prothese, die nicht mehr hält, muss unterfüttert werden', 'İlk 2-3 hafta vurma yaraları, tükürük artışı ve konuşma güçlüğü olabilir — bu alışma dönemidir; ağrılı noktalar düzeltmeyle giderilir, tutuşu bozulan protez ise besleme (altının doldurulması) gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'complete-acrylic-denture'), 'A full removable denture made of acrylic resin for an entire jaw', 'Totalna pokretna proteza od akrilata za cijelu vilicu', 'Тотална покретна протеза од акрилата за цијелу вилицу', 'Полный съёмный протез из акриловой пластмассы на всю челюсть', 'Eine Vollprothese aus Kunststoff (Acrylat) für einen ganzen Kiefer', 'Tüm çene için akrilik reçineden yapılan tam hareketli protez', 'Impressions, bite registration, wax try-in, fabrication of the acrylic base with teeth, and fitting; usually 4-5 visits', 'Otisci, određivanje zagriza, proba u vosku, izrada akrilatne baze sa zubima i prilagođavanje; obično 4-5 posjeta', 'Отисци, одређивање загриза, проба у воску, израда акрилатне базе са зубима и прилагођавање; обично 4-5 посјета', 'Слепки, определение прикуса, примерка воскового шаблона, изготовление акриловой базы с зубами и припасовка; обычно 4-5 визитов', 'Abdrücke, Bissregistrierung, Wachsanprobe, Anfertigung der Kunststoffbasis mit Zähnen und Einpassen; in der Regel 4-5 Termine', 'Ölçüler, kapanış kaydı, mum prova, dişlerle birlikte akrilik kaidenin üretimi ve uyumlama; genellikle 4-5 seans', 'Complete tooth loss in a jaw; often as a first or temporary denture after extractions', 'Potpuni nedostatak zuba u vilici; često kao prva ili privremena proteza nakon vađenja zuba', 'Потпуни недостатак зуба у вилици; често као прва или привремена протеза након вађења зуба', 'Полное отсутствие зубов на челюсти; часто как первый или временный протез после удаления зубов', 'Vollständiger Zahnverlust in einem Kiefer; häufig als erste oder provisorische Prothese nach Zahnentfernungen', 'Bir çenede tüm dişlerin eksik olması; sıklıkla çekimlerden sonra ilk veya geçici protez olarak', 'Healing of the gums after extractions; report any known allergy to acrylic resins', 'Zarastanje sluznice nakon vađenja; napomenuti poznatu alergiju na akrilate', 'Зарастање слузнице након вађења; напоменути познату алергију на акрилате', 'Заживление слизистой после удалений; сообщить об аллергии на акриловые пластмассы, если она известна', 'Abheilung der Schleimhaut nach Extraktionen; eine bekannte Allergie gegen Kunststoffe mitteilen', 'Çekimlerden sonra diş etinin iyileşmesi; bilinen akrilik alerjisinin bildirilmesi', 'Sore spots and mild pain in the first weeks are resolved by adjustment; persistent redness of the gums under the denture or a bad odor is a reason to see the dentist', 'Žuljevi i blaga bol prvih nedjelja rješavaju se korekcijom; trajno crvenilo sluznice pod protezom ili neprijatan miris razlog su za pregled kod stomatologa', 'Жуљеви и блага бол првих недјеља рјешавају се корекцијом; трајно црвенило слузнице под протезом или непријатан мирис разлог су за преглед код стоматолога', 'Натирания и лёгкая боль в первые недели устраняются коррекцией; появление стойкого покраснения слизистой под протезом или неприятного запаха — повод показаться стоматологу', 'Druckstellen und leichte Schmerzen in den ersten Wochen werden durch Korrekturen behoben; anhaltende Rötung der Schleimhaut unter der Prothese oder unangenehmer Geruch sind ein Grund für einen Zahnarztbesuch', 'İlk haftalarda vurma yaraları ve hafif ağrı düzeltmeyle giderilir; protez altındaki diş etinde kalıcı kızarıklık veya kötü koku diş hekimine başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'partial-acrylic-denture'), 'A partial removable denture made of acrylic resin that replaces several teeth', 'Parcijalna pokretna proteza od akrilata koja zamjenjuje nekoliko zuba', 'Парцијална покретна протеза од акрилата која замјењује неколико зуба', 'Частичный съёмный протез из акриловой пластмассы, замещающий несколько зубов', 'Eine herausnehmbare Teilprothese aus Kunststoff, die mehrere Zähne ersetzt', 'Birkaç dişi tamamlayan, akrilik reçineden yapılan bölümlü hareketli protez', 'Impressions, fabrication of an acrylic base with artificial teeth and retaining clasps, and fitting; usually 2-3 visits over 1-2 weeks', 'Otisci, izrada akrilatne baze sa vještačkim zubima i kvačicama za držanje, prilagođavanje; obično 2-3 posjete tokom 1-2 nedjelje', 'Отисци, израда акрилатне базе са вјештачким зубима и квачицама за држање, прилагођавање; обично 2-3 посјете током 1-2 недјеље', 'Слепки, изготовление акриловой базы с искусственными зубами и удерживающими кламмерами, припасовка; обычно 2-3 визита в течение 1-2 недель', 'Abdrücke, Anfertigung einer Kunststoffbasis mit künstlichen Zähnen und Halteklammern, Einpassen; in der Regel 2-3 Termine über 1-2 Wochen', 'Ölçüler, yapay dişler ve tutucu kancalarla akrilik kaidenin üretimi, uyumlama; genellikle 1-2 hafta içinde 2-3 seans', 'Several missing teeth, including as a temporary solution while implants heal', 'Nedostatak nekoliko zuba, uključujući i privremeno rješenje tokom zarastanja nakon implantacije', 'Недостатак неколико зуба, укључујући и привремено рјешење током зарастања након имплантације', 'Отсутствие нескольких зубов, в том числе как временное решение на период заживления после имплантации', 'Mehrere fehlende Zähne, auch als Übergangslösung während der Einheilung von Implantaten', 'Birkaç dişin eksik olması; implantların iyileşmesi sırasında geçici çözüm olarak da kullanılır', 'Treatment of cavities in the supporting teeth; report any known acrylic allergy', 'Liječenje karijesa na nosećim zubima; napomenuti poznatu alergiju na akrilat', 'Лијечење каријеса на носећим зубима; напоменути познату алергију на акрилат', 'Лечение кариеса на опорных зубах; сообщить об аллергии на акрил, если она известна', 'Behandlung von Karies an den Haltezähnen; eine bekannte Kunststoffallergie mitteilen', 'Destek dişlerdeki çürüklerin tedavisi; bilinen akrilik alerjisinin bildirilmesi', 'Discomfort and rubbing in the first days are normal and resolved by adjustment; a crack in the base or a broken clasp needs repair — such a denture should not be worn', 'Nelagodnost i žuljanje prvih dana su uobičajeni i rješavaju se korekcijom; pukotina u bazi ili slomljena kvačica zahtijevaju popravku — takvu protezu ne treba nositi', 'Нелагодност и жуљање првих дана су уобичајени и рјешавају се корекцијом; пукотина у бази или сломљена квачица захтијевају поправку — такву протезу не треба носити', 'Дискомфорт и натирание в первые дни — обычное явление и устраняется коррекцией; трещина в базисе или сломанный кламмер требуют ремонта, носить такой протез не следует', 'Unbehagen und Reiben in den ersten Tagen sind normal und werden durch Korrekturen behoben; ein Riss in der Basis oder eine gebrochene Klammer muss repariert werden — eine solche Prothese sollte nicht getragen werden', 'İlk günlerde rahatsızlık ve tahriş normaldir, düzeltmeyle giderilir; kaidede çatlak veya kırık kanca onarım gerektirir, bu protez takılmamalıdır')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'flexible-denture'), 'A removable denture made of a flexible resin (nylon or similar) without metal clasps', 'Pokretna proteza od elastičnog materijala (najlon ili slično) bez metalnih kvačica', 'Покретна протеза од еластичног материјала (најлон или слично) без металних квачица', 'Съёмный протез из эластичной пластмассы (нейлон или подобный материал) без металлических кламмеров', 'Eine herausnehmbare Prothese aus einem flexiblen Kunststoff (Nylon oder ähnlich) ohne Metallklammern', 'Metal kanca içermeyen, esnek malzemeden (nylon veya benzeri) yapılan hareketli protez', 'Impressions, fabrication of the flexible base with teeth in the laboratory, and fitting; usually 2-3 visits over 1-2 weeks', 'Otisci, izrada elastične baze sa zubima u laboratoriji i prilagođavanje; obično 2-3 posjete tokom 1-2 nedjelje', 'Отисци, израда еластичне базе са зубима у лабораторији и прилагођавање; обично 2-3 посјете током 1-2 недјеље', 'Слепки, изготовление гибкого базиса с зубами в лаборатории и припасовка; обычно 2-3 визита в течение 1-2 недель', 'Abdrücke, Anfertigung der flexiblen Basis mit Zähnen im Labor und Einpassen; in der Regel 2-3 Termine über 1-2 Wochen', 'Ölçüler, laboratuvarda dişlerle birlikte esnek kaidenin üretimi ve uyumlama; genellikle 1-2 hafta içinde 2-3 seans', 'Missing teeth in patients allergic to acrylic or metal, and when the retaining elements need to be inconspicuous', 'Nedostatak zuba kod alergije na akrilat ili metal, kao i kada je važno da elementi za držanje budu neupadljivi', 'Недостатак зуба код алергије на акрилат или метал, као и када је важно да елементи за држање буду неупадљиви', 'Отсутствие зубов при аллергии на акрил или металл, а также когда важна незаметность фиксирующих элементов', 'Fehlende Zähne bei Allergie gegen Kunststoff oder Metall sowie wenn die Halteelemente unauffällig sein sollen', 'Akrilik veya metal alerjisi olan hastalarda diş eksikliği ve tutucu parçaların görünmemesinin önemli olduğu durumlar', 'Oral health should be addressed first; discuss with the dentist that a flexible denture is harder to repair and reline than an acrylic one', 'Sanacija usne duplje; sa stomatologom razmotriti da se elastična proteza teže popravlja i podlaže od akrilatne', 'Санација усне дупље; са стоматологом размотрити да се еластична протеза теже поправља и подлаже од акрилатне', 'Санация полости рта; обсудить со стоматологом, что гибкий протез хуже подлежит починке и перебазировке, чем акриловый', 'Sanierung der Mundhöhle; mit dem Zahnarzt besprechen, dass eine flexible Prothese schwerer zu reparieren und zu unterfüttern ist als eine Acrylprothese', 'Ağız sağlığının düzenlenmesi; esnek protezin akrilik proteze göre onarım ve beslemeye daha az uygun olduğunun hekimle konuşulması', 'Slight rubbing during the adaptation period is normal; discoloration of the material, a persistent odor, or worsening fit over time are reasons for a check-up and a decision on replacement', 'Blago žuljanje tokom privikavanja je uobičajeno; promjena boje materijala, trajan miris ili slabljenje držanja s vremenom razlog su za pregled i odluku o zamjeni', 'Благо жуљање током привикавања је уобичајено; промјена боје материјала, трајан мирис или слабљење држања с временом разлог су за преглед и одлуку о замјени', 'Небольшое натирание в период привыкания — обычное явление; изменение цвета материала, стойкий запах или ухудшение фиксации со временем — повод для осмотра и решения о замене', 'Leichtes Reiben während der Eingewöhnung ist normal; Verfärbung des Materials, anhaltender Geruch oder ein mit der Zeit schlechter werdender Halt sind ein Grund für eine Kontrolle und die Entscheidung über einen Austausch', 'Alışma döneminde hafif tahriş normaldir; malzemenin renk değiştirmesi, kalıcı koku veya zamanla tutuşun azalması kontrol ve değişim kararı için nedendir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'partial-flexible-denture'), 'A partial removable denture made of a flexible material that replaces several teeth without visible metal attachments', 'Parcijalna pokretna proteza od elastičnog materijala koja zamjenjuje nekoliko zuba bez vidljivih metalnih elemenata', 'Парцијална покретна протеза од еластичног материјала која замјењује неколико зуба без видљивих металних елемената', 'Частичный съёмный протез из эластичного материала, замещающий несколько зубов без видимых металлических креплений', 'Eine herausnehmbare Teilprothese aus flexiblem Material, die mehrere Zähne ohne sichtbare Metallelemente ersetzt', 'Görünür metal parça olmadan birkaç dişi tamamlayan, esnek malzemeden bölümlü hareketli protez', 'Impressions, fabrication of the flexible base with artificial teeth, and fitting; usually 2-3 visits over 1-2 weeks', 'Otisci, izrada elastične baze sa vještačkim zubima i prilagođavanje; obično 2-3 posjete tokom 1-2 nedjelje', 'Отисци, израда еластичне базе са вјештачким зубима и прилагођавање; обично 2-3 посјете током 1-2 недјеље', 'Слепки, изготовление гибкого базиса с искусственными зубами и припасовка; обычно 2-3 визита в течение 1-2 недель', 'Abdrücke, Anfertigung der flexiblen Basis mit künstlichen Zähnen und Einpassen; in der Regel 2-3 Termine über 1-2 Wochen', 'Ölçüler, yapay dişlerle esnek kaidenin üretimi ve uyumlama; genellikle 1-2 hafta içinde 2-3 seans', 'One or several missing teeth, when the appearance of the retention matters or there is a metal allergy', 'Nedostatak jednog ili više zuba, kada je važan estetski izgled držanja ili postoji alergija na metal', 'Недостатак једног или више зуба, када је важан естетски изглед држања или постоји алергија на метал', 'Отсутствие одного или нескольких зубов, когда важна эстетика фиксации или есть аллергия на металл', 'Ein oder mehrere fehlende Zähne, wenn das Aussehen der Verankerung wichtig ist oder eine Metallallergie besteht', 'Bir veya birkaç dişin eksik olması, tutuculuğun görünümünün önemli olduğu ya da metal alerjisi bulunan durumlar', 'Treatment of cavities and a professional cleaning before impressions are taken', 'Liječenje karijesa i profesionalno čišćenje prije uzimanja otisaka', 'Лијечење каријеса и професионално чишћење прије узимања отисака', 'Лечение кариеса и профессиональная чистка перед снятием слепков', 'Behandlung von Karies und professionelle Zahnreinigung vor der Abdrucknahme', 'Ölçü alınmadan önce çürük tedavisi ve profesyonel temizlik', 'Adaptation takes a few days; constant pain under the denture, redness of the gums, or a noticeable change in the bite are reasons to see the dentist', 'Privikavanje traje nekoliko dana; stalna bol pod protezom, crvenilo sluznice ili primjetna promjena zagriza razlog su za posjetu stomatologu', 'Привикавање траје неколико дана; стална бол под протезом, црвенило слузнице или примјетна промјена загриза разлог су за посјету стоматологу', 'Привыкание занимает несколько дней; постоянная боль под протезом, покраснение слизистой или заметное изменение прикуса — повод обратиться к стоматологу', 'Die Eingewöhnung dauert einige Tage; dauerhafte Schmerzen unter der Prothese, Rötung der Schleimhaut oder eine merkliche Bissveränderung sind ein Grund, den Zahnarzt aufzusuchen', 'Alışma birkaç gün sürer; protez altında sürekli ağrı, diş etinde kızarıklık veya kapanışta belirgin değişiklik diş hekimine başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'overdenture-on-mini-implants'), 'A removable denture retained by several mini implants, which makes it hold considerably better than a conventional one', 'Pokretna proteza koja se drži na nekoliko mini-implantata i zato ima znatno bolje držanje od obične', 'Покретна протеза која се држи на неколико мини-имплантата и зато има знатно боље држање од обичне', 'Съёмный протез, который фиксируется на нескольких мини-имплантатах и потому держится значительно надёжнее обычного', 'Eine herausnehmbare Prothese, die auf mehreren Mini-Implantaten verankert ist und dadurch deutlich besser hält als eine herkömmliche', 'Birkaç mini implant üzerine tutunan ve bu sayede sıradan protezden çok daha iyi tutan hareketli protez', 'Placement of the mini implants under local anesthesia, then fitting of attachment elements into the denture to connect it to the implants; the denture can usually be loaded within a short time, with the exact stages set by the dentist', 'Postavljanje mini-implantata u lokalnoj anesteziji, zatim ugradnja spojnih elemenata u protezu koji je povezuju sa implantatima; proteza se obično može opteretiti u kratkom roku, a tačne faze određuje ljekar', 'Постављање мини-имплантата у локалној анестезији, затим уградња спојних елемената у протезу који је повезују са имплантатима; протеза се обично може оптеретити у кратком року, а тачне фазе одређује љекар', 'Установка мини-имплантатов под местной анестезией, затем фиксация в протезе замковых элементов, соединяющих его с имплантатами; протез обычно можно нагружать в короткие сроки, точные этапы определяет врач', 'Einsetzen der Mini-Implantate unter Lokalanästhesie, danach Einarbeiten der Verbindungselemente in die Prothese, die sie mit den Implantaten verbinden; die Prothese kann in der Regel nach kurzer Zeit belastet werden, die genauen Schritte legt der Arzt fest', 'Mini implantların lokal anestezi altında yerleştirilmesi, ardından proteze implantlara bağlanan tutucu parçaların yerleştirilmesi; proteze genellikle kısa sürede yük verilebilir, aşamaları hekim belirler', 'Poor retention of a full removable denture, marked bone loss where conventional implants are difficult', 'Slabo držanje totalne pokretne proteze, izražen gubitak kosti kada je obična implantacija otežana', 'Слабо држање тоталне покретне протезе, изражен губитак кости када је обична имплантација отежана', 'Плохая фиксация полного съёмного протеза, выраженная атрофия костной ткани, когда обычная имплантация затруднена', 'Schlechter Halt einer Vollprothese, ausgeprägter Knochenabbau, bei dem herkömmliche Implantate schwierig sind', 'Tam hareketli protezin iyi tutmaması, sıradan implantı güçleştiren belirgin kemik erimesi', 'A panoramic X-ray or CT scan to assess the bone, treatment of any oral disease, and informing the dentist about medications and chronic conditions', 'Panoramski snimak ili CT za procjenu kosti, sanacija usne duplje, obavijestiti ljekara o lijekovima i hroničnim bolestima', 'Панорамски снимак или ЦТ за процјену кости, санација усне дупље, обавијестити љекара о лијековима и хроничним болестима', 'Панорамный снимок или КТ для оценки кости, санация полости рта, сообщить о принимаемых препаратах и хронических заболеваниях', 'Panoramaröntgen oder CT zur Beurteilung des Knochens, Sanierung der Mundhöhle, Information über Medikamente und chronische Erkrankungen', 'Kemiğin değerlendirilmesi için panoramik film veya BT, ağız sağlığının düzenlenmesi, kullanılan ilaçların ve kronik hastalıkların bildirilmesi', 'Mild swelling and tenderness in the first days after placement are a normal reaction; pain that increases over time, implant mobility, or inflammation around it require a dental examination', 'Blago oticanje i osjetljivost prvih dana nakon postavljanja su uobičajena reakcija; bol koja se s vremenom pojačava, klaćenje implantata ili upala oko njega zahtijevaju pregled kod ljekara', 'Благо отицање и осјетљивост првих дана након постављања су уобичајена реакција; бол која се с временом појачава, клаћење имплантата или упала око њега захтијевају преглед код љекара', 'Небольшой отёк и чувствительность в первые дни после установки — обычная реакция; боль, нарастающая со временем, подвижность имплантата или воспаление вокруг него требуют осмотра врача', 'Leichte Schwellung und Empfindlichkeit in den ersten Tagen nach dem Eingriff sind eine normale Reaktion; zunehmende Schmerzen, ein beweglich werdendes Implantat oder eine Entzündung darum herum erfordern eine ärztliche Untersuchung', 'Yerleştirmeden sonraki ilk günlerde hafif şişlik ve hassasiyet normal bir tepkidir; zamanla artan ağrı, implantın sallanması veya çevresinde iltihap hekim muayenesi gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'direct-denture-relining'), 'Renewal of the fitting surface of a removable denture with a material applied and cured directly in the mouth', 'Obnavljanje naslonske površine pokretne proteze materijalom koji se nanosi i stvrdnjava direktno u ustima', 'Обнављање наслонске површине покретне протезе материјалом који се наноси и стврдњава директно у устима', 'Обновление прилегающей поверхности съёмного протеза материалом, который вносится и затвердевает прямо в полости рта', 'Erneuerung der Auflagefläche einer herausnehmbaren Prothese mit einem Material, das direkt im Mund eingebracht und ausgehärtet wird', 'Hareketli protezin dokuya oturan yüzeyinin, doğrudan ağızda uygulanıp sertleşen bir malzemeyle yenilenmesi', 'The dentist applies a soft material to the denture base, seats the denture so it takes the shape of the gums, then trims and polishes it; done in a single visit', 'Ljekar nanosi plastični materijal na bazu proteze, postavlja protezu da preuzme oblik sluznice, zatim je obrađuje i polira; radi se u jednoj posjeti', 'Љекар наноси пластични материјал на базу протезе, поставља протезу да преузме облик слузнице, затим је обрађује и полира; ради се у једној посјети', 'Врач наносит на базис протеза пластичный материал, надевает протез, чтобы он принял форму слизистой, затем обрабатывает и полирует; выполняется за один визит', 'Der Zahnarzt bringt ein plastisches Material auf die Prothesenbasis auf, setzt die Prothese ein, damit sie die Form der Schleimhaut annimmt, und arbeitet sie danach aus und poliert sie; wird in einem Termin erledigt', 'Hekim protez kaidesine yumuşak malzeme uygular, protezi diş etinin şeklini alacak şekilde yerleştirir, ardından tesviye eder ve parlatır; tek seansta yapılır', 'The denture has lost retention due to natural bone shrinkage and a quick same-visit correction is needed', 'Proteza je izgubila držanje zbog prirodnog smanjenja kosti i potrebna je brza korekcija u istoj posjeti', 'Протеза је изгубила држање због природног смањења кости и потребна је брза корекција у истој посјети', 'Протез стал хуже держаться из-за естественной убыли костной ткани, требуется быстрая коррекция за одно посещение', 'Die Prothese hält durch den natürlichen Knochenabbau schlechter und eine schnelle Korrektur im selben Termin ist gewünscht', 'Kemiğin doğal olarak erimesi nedeniyle protezin tutuşunun azalması ve aynı seansta hızlı düzeltme gerekmesi', 'Bring the denture; the gums should be free of acute inflammation and fresh sores', 'Doći sa protezom; sluznica treba da bude bez akutne upale i svježih ranica', 'Доћи са протезом; слузница треба да буде без акутне упале и свјежих раница', 'Прийти с протезом; слизистая должна быть без острого воспаления и свежих ранок', 'Die Prothese mitbringen; die Schleimhaut sollte frei von akuten Entzündungen und frischen Wunden sein', 'Protezle gelmek; diş etinde akut iltihap ve yeni yara bulunmaması', 'A taste of the material is possible for the first few hours; if the denture presses at certain spots afterwards or retention has not improved, a further adjustment or a laboratory reline is needed', 'Prvih sati moguć je ukus materijala; ako proteza nakon podlaganja pritiska na pojedinim mjestima ili držanje nije poboljšano, potrebna je dodatna korekcija ili laboratorijsko podlaganje', 'Првих сати могућ је укус материјала; ако протеза након подлагања притиска на појединим мјестима или држање није побољшано, потребна је додатна корекција или лабораторијско подлагање', 'Первые часы возможен привкус материала; если после перебазировки протез давит в отдельных точках или фиксация не улучшилась, нужна повторная коррекция или лабораторная перебазировка', 'In den ersten Stunden ist ein Geschmack des Materials möglich; wenn die Prothese danach an einzelnen Stellen drückt oder der Halt sich nicht verbessert hat, ist eine weitere Korrektur oder eine Unterfütterung im Labor erforderlich', 'İlk saatlerde malzemenin tadı duyulabilir; işlemden sonra protez bazı noktalarda baskı yapıyorsa veya tutuş düzelmediyse ek düzeltme ya da laboratuvarda besleme gerekir')
