INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'indirect-denture-relining'), 'Renewal of the fitting surface of a removable denture in a dental laboratory, using an impression taken with the denture itself', 'Obnavljanje naslonske površine pokretne proteze u zubotehničkoj laboratoriji, po otisku uzetom samom protezom', 'Обнављање наслонске површине покретне протезе у зуботехничкој лабораторији, по отиску узетом самом протезом', 'Обновление прилегающей поверхности съёмного протеза в зуботехнической лаборатории по слепку, снятому самим протезом', 'Erneuerung der Auflagefläche einer herausnehmbaren Prothese im zahntechnischen Labor anhand eines mit der Prothese genommenen Abdrucks', 'Hareketli protezin dokuya oturan yüzeyinin, protezin kendisiyle alınan ölçü üzerinden diş laboratuvarında yenilenmesi', 'The dentist takes an impression using the denture, the work is done in the laboratory, and the denture is then fitted; usually 2 visits, with the denture staying in the lab in between', 'Ljekar uzima otisak pomoću proteze, rad se izvodi u laboratoriji, a zatim se proteza prilagođava; obično 2 posjete, proteza u međuvremenu ostaje u laboratoriji', 'Љекар узима отисак помоћу протезе, рад се изводи у лабораторији, а затим се протеза прилагођава; обично 2 посјете, протеза у међувремену остаје у лабораторији', 'Врач снимает слепок с использованием протеза, работа выполняется в лаборатории, затем протез припасовывается; обычно 2 визита, протез на время остаётся в лаборатории', 'Der Zahnarzt nimmt mit der Prothese einen Abdruck, die Arbeit erfolgt im Labor, danach wird die Prothese eingepasst; in der Regel 2 Termine, dazwischen bleibt die Prothese im Labor', 'Hekim protezle ölçü alır, işlem laboratuvarda yapılır, ardından protez uyumlanır; genellikle 2 seans, bu arada protez laboratuvarda kalır', 'Noticeable loss of denture retention after 1-3 years of wear, when a more precise and durable result than a direct reline is needed', 'Primjetan gubitak držanja proteze nakon 1-3 godine nošenja, kada je potreban precizniji i trajniji rezultat od direktnog podlaganja', 'Примјетан губитак држања протезе након 1-3 године ношења, када је потребан прецизнији и трајнији резултат од директног подлагања', 'Заметная потеря фиксации протеза через 1-3 года ношения, когда нужен более точный и долговечный результат, чем при прямой перебазировке', 'Deutlicher Halteverlust der Prothese nach 1-3 Jahren Tragezeit, wenn ein präziseres und haltbareres Ergebnis als bei einer direkten Unterfütterung gewünscht ist', '1-3 yıllık kullanımdan sonra protezin tutuşunun belirgin azalması ve doğrudan beslemeden daha hassas, daha kalıcı sonuç gerekmesi', 'Bring the denture and plan for several hours or a day without it; the gums should be free of acute inflammation', 'Doći sa protezom i računati na nekoliko sati ili dan bez nje; sluznica treba da bude bez akutne upale', 'Доћи са протезом и рачунати на неколико сати или дан без ње; слузница треба да буде без акутне упале', 'Прийти с протезом и учесть, что несколько часов или день его придётся быть без него; слизистая должна быть без острого воспаления', 'Die Prothese mitbringen und einige Stunden oder einen Tag ohne sie einplanen; die Schleimhaut sollte frei von akuten Entzündungen sein', 'Protezle gelmek ve birkaç saat ya da bir gün protezsiz kalmayı hesaba katmak; diş etinde akut iltihap bulunmaması', 'It may take a few days to get used to the changed fit; painful spots are resolved by adjustment, while continued poor retention may mean a new denture is needed', 'Nekoliko dana nakon podlaganja moguće je privikavanje na izmijenjeno naslanjanje; bolna mjesta se rješavaju korekcijom, a i dalje slabo držanje može značiti da je potrebna nova proteza', 'Неколико дана након подлагања могуће је привикавање на измијењено наслањање; болна мјеста се рјешавају корекцијом, а и даље слабо држање може значити да је потребна нова протеза', 'Несколько дней после перебазировки возможно привыкание к изменившемуся прилеганию; болезненные точки устраняются коррекцией, а сохраняющаяся плохая фиксация может означать, что нужен новый протез', 'Einige Tage nach der Unterfütterung ist eine Eingewöhnung an die veränderte Auflage möglich; schmerzhafte Stellen werden durch Korrekturen behoben, ein weiterhin schlechter Halt kann bedeuten, dass eine neue Prothese nötig ist', 'İşlemden sonra birkaç gün değişen oturuma alışma süreci olabilir; ağrılı noktalar düzeltmeyle giderilir, tutuşun hâlâ zayıf olması yeni protez gerektiğini gösterebilir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'pressed-ceramic-crown'), 'A metal-free crown made of pressed ceramic that transmits light similarly to a natural tooth', 'Bezmetalna krunica od presovane keramike koja propušta svjetlost slično prirodnom zubu', 'Безметална круница од пресоване керамике која пропушта свјетлост слично природном зубу', 'Безметалловая коронка из прессованной керамики, которая пропускает свет похоже на натуральный зуб', 'Eine metallfreie Krone aus Presskeramik, die Licht ähnlich wie ein natürlicher Zahn durchlässt', 'Işığı doğal dişe benzer şekilde geçiren, pres seramikten yapılmış metal desteksiz kron', 'Tooth preparation, an impression or digital scan, pressing of the crown in the laboratory, and cementation; usually 2 visits with a temporary crown in between', 'Brušenje zuba, otisak ili skeniranje, presovanje krunice u laboratoriji i cementiranje; obično 2 posjete sa privremenom krunicom između njih', 'Брушење зуба, отисак или скенирање, пресовање крунице у лабораторији и цементирање; обично 2 посјете са привременом круницом између њих', 'Обточка зуба, слепок или сканирование, прессование коронки в лаборатории и фиксация на цемент; обычно 2 визита с временной коронкой между ними', 'Beschleifen des Zahns, Abdruck oder digitaler Scan, Pressen der Krone im Labor und Zementieren; in der Regel 2 Termine mit einer provisorischen Krone dazwischen', 'Dişin aşındırılması, ölçü veya dijital tarama, kronun laboratuvarda preslenmesi ve simantasyon; genellikle arada geçici kronla 2 seans', 'Restoration of front and back teeth where natural translucency matters; replacement of a discolored old restoration', 'Obnova prednjih i bočnih zuba kada je važna prirodna prozirnost; zamjena potamnjele stare restauracije', 'Обнова предњих и бочних зуба када је важна природна прозирност; замјена потамњеле старе рестаурације', 'Восстановление передних и боковых зубов, когда важна естественная прозрачность; замена потемневшей старой реставрации', 'Versorgung von Front- und Seitenzähnen, wenn natürliche Transluzenz wichtig ist; Ersatz einer verfärbten alten Restauration', 'Doğal geçirgenliğin önemli olduğu ön ve arka diş restorasyonları; rengi kararmış eski restorasyonun değiştirilmesi', 'No special preparation is required; a badly damaged tooth is first root-canal treated or reinforced with a post and core', 'Posebna priprema nije potrebna; kod velikog oštećenja zub se prethodno liječi kanalno ili ojačava nadogradnjom', 'Посебна припрема није потребна; код великог оштећења зуб се претходно лијечи канално или ојачава надоградњом', 'Специальной подготовки не требуется; при глубоком разрушении зуб предварительно лечат по каналу или укрепляют вкладкой', 'Keine besondere Vorbereitung nötig; ein stark geschädigter Zahn wird vorab wurzelbehandelt oder mit einem Stiftaufbau verstärkt', 'Özel hazırlık gerekmez; ileri düzeyde harap dişe önce kanal tedavisi yapılır veya post-kor ile güçlendirilir', 'Sensitivity to cold and discomfort when biting in the first days are normal; chipped ceramic, pain under the crown, or inflammation at the gum margin are reasons to see the dentist', 'Osjetljivost na hladno i nelagodnost pri zagrizanju prvih dana su uobičajeni; okrznuta keramika, bol pod krunicom ili upala ivice desni razlog su za posjetu stomatologu', 'Осјетљивост на хладно и нелагодност при загризању првих дана су уобичајени; окрзнута керамика, бол под круницом или упала ивице десни разлог су за посјету стоматологу', 'Чувствительность к холодному и дискомфорт при накусывании в первые дни — обычное явление; скол керамики, боль под коронкой или воспаление края десны — повод обратиться к стоматологу', 'Kälteempfindlichkeit und Unbehagen beim Zubeißen in den ersten Tagen sind normal; abgeplatzte Keramik, Schmerzen unter der Krone oder eine Entzündung am Zahnfleischrand sind ein Grund für einen Zahnarztbesuch', 'İlk günlerde soğuk hassasiyeti ve ısırırken rahatsızlık normaldir; seramikte kırık, kron altında ağrı veya diş eti kenarında iltihap diş hekimine başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'metal-ceramic-crown-gold'), 'A metal-ceramic crown with a framework made of a gold-containing alloy, covered with ceramic', 'Metalokeramička krunica čiji je skelet izrađen od legure sa zlatom, preko koje je nanesena keramika', 'Металокерамичка круница чији је скелет израђен од легуре са златом, преко које је нанесена керамика', 'Металлокерамическая коронка, каркас которой изготовлен из золотосодержащего сплава, а поверх нанесена керамика', 'Eine Metallkeramikkrone mit einem Gerüst aus einer goldhaltigen Legierung, das mit Keramik verblendet ist', 'Alt yapısı altın içeren alaşımdan yapılan ve üzeri seramikle kaplanan metal destekli kron', 'Tooth preparation, an impression, casting of the alloy framework and application of ceramic in the laboratory, then cementation; usually 2-3 visits over 1-2 weeks', 'Brušenje zuba, otisak, livenje skeleta od legure i nanošenje keramike u laboratoriji, zatim cementiranje; obično 2-3 posjete tokom 1-2 nedjelje', 'Брушење зуба, отисак, ливење скелета од легуре и наношење керамике у лабораторији, затим цементирање; обично 2-3 посјете током 1-2 недјеље', 'Обточка зуба, слепок, отливка каркаса из сплава и нанесение керамики в лаборатории, затем фиксация; обычно 2-3 визита в течение 1-2 недель', 'Beschleifen des Zahns, Abdruck, Gießen des Legierungsgerüsts und Aufbrennen der Keramik im Labor, danach Zementieren; in der Regel 2-3 Termine über 1-2 Wochen', 'Dişin aşındırılması, ölçü, laboratuvarda alaşım alt yapının dökümü ve seramiğin işlenmesi, ardından simantasyon; genellikle 1-2 hafta içinde 2-3 seans', 'Restoration of a damaged tooth where a strong framework with good biocompatibility is needed; intolerance of ordinary alloys', 'Obnova oštećenog zuba kada je potrebna čvrsta konstrukcija i dobra biokompatibilnost skeleta; nepodnošenje običnih legura', 'Обнова оштећеног зуба када је потребна чврста конструкција и добра биокомпатибилност скелета; неподношење обичних легура', 'Восстановление разрушенного зуба, когда нужна прочная конструкция и хорошая биосовместимость каркаса; непереносимость обычных сплавов', 'Versorgung eines geschädigten Zahns, wenn ein stabiles Gerüst mit guter Biokompatibilität benötigt wird; Unverträglichkeit gewöhnlicher Legierungen', 'Dayanıklı alt yapı ve iyi doku uyumu gereken diş restorasyonları; sıradan alaşımların tolere edilemediği durumlar', 'No special preparation is required; the price depends on the weight of the alloy, which is worth clarifying beforehand', 'Posebna priprema nije potrebna; cijena zavisi od težine legure, što je dobro provjeriti prije početka rada', 'Посебна припрема није потребна; цијена зависи од тежине легуре, што је добро провјерити прије почетка рада', 'Специальной подготовки не требуется; стоимость зависит от веса сплава, это стоит уточнить до начала работы', 'Keine besondere Vorbereitung nötig; der Preis richtet sich nach dem Gewicht der Legierung, was vorab geklärt werden sollte', 'Özel hazırlık gerekmez; fiyat alaşımın ağırlığına bağlıdır, işleme başlamadan netleştirilmesi iyi olur', 'Mild sensitivity in the first days is normal; a dark line at the gum margin over time, chipped ceramic, or pain when biting are reasons to see the dentist', 'Blaga osjetljivost prvih dana je uobičajena; tamna linija uz ivicu desni s vremenom, okrznuta keramika ili bol pri zagrizanju razlog su za pregled kod stomatologa', 'Блага осјетљивост првих дана је уобичајена; тамна линија уз ивицу десни с временом, окрзнута керамика или бол при загризању разлог су за преглед код стоматолога', 'Лёгкая чувствительность в первые дни — обычное явление; тёмная полоска у края десны со временем, скол керамики или боль при накусывании — повод показаться стоматологу', 'Leichte Empfindlichkeit in den ersten Tagen ist normal; ein dunkler Rand am Zahnfleisch im Laufe der Zeit, abgeplatzte Keramik oder Schmerzen beim Zubeißen sind ein Grund für einen Zahnarztbesuch', 'İlk günlerde hafif hassasiyet normaldir; zamanla diş eti kenarında koyu çizgi, seramikte kırık veya ısırırken ağrı diş hekimine başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'metal-ceramic-crown-cocr'), 'A metal-ceramic crown with a cobalt-chromium (CoCr) framework and a ceramic veneer', 'Metalokeramička krunica sa skeletom od kobalt-hrom legure (CoCr) i keramičkom fasetom', 'Металокерамичка круница са скелетом од кобалт-хром легуре (CoCr) и керамичком фасетом', 'Металлокерамическая коронка с каркасом из кобальт-хромового сплава (CoCr) и керамической облицовкой', 'Eine Metallkeramikkrone mit einem Gerüst aus Kobalt-Chrom-Legierung (CoCr) und keramischer Verblendung', 'Kobalt-krom (CoCr) alaşımdan alt yapısı ve seramik kaplaması olan metal destekli kron', 'Tooth preparation, an impression, fabrication of the framework and application of ceramic in the laboratory, try-in and cementation; usually 2-3 visits over 1-2 weeks', 'Brušenje zuba, otisak, izrada skeleta i nanošenje keramike u laboratoriji, proba i cementiranje; obično 2-3 posjete tokom 1-2 nedjelje', 'Брушење зуба, отисак, израда скелета и наношење керамике у лабораторији, проба и цементирање; обично 2-3 посјете током 1-2 недјеље', 'Обточка зуба, слепок, изготовление каркаса и нанесение керамики в лаборатории, примерка и фиксация; обычно 2-3 визита в течение 1-2 недель', 'Beschleifen des Zahns, Abdruck, Herstellung des Gerüsts und Aufbrennen der Keramik im Labor, Anprobe und Zementieren; in der Regel 2-3 Termine über 1-2 Wochen', 'Dişin aşındırılması, ölçü, laboratuvarda alt yapının hazırlanması ve seramiğin işlenmesi, prova ve simantasyon; genellikle 1-2 hafta içinde 2-3 seans', 'Restoration of a damaged or root-canal-treated tooth, as a bridge support, or replacement of an old crown', 'Obnova oštećenog ili depulpiranog zuba, nosač mosta, zamjena stare krunice', 'Обнова оштећеног или депулпираног зуба, носач моста, замјена старе крунице', 'Восстановление разрушенного или депульпированного зуба, опора мостовидного протеза, замена старой коронки', 'Versorgung eines geschädigten oder wurzelbehandelten Zahns, als Brückenpfeiler oder Ersatz einer alten Krone', 'Harap veya kanal tedavisi görmüş dişin restorasyonu, köprü ayağı, eski kronun değiştirilmesi', 'No special preparation is required; report any known metal allergy', 'Posebna priprema nije potrebna; napomenuti poznatu alergiju na metale', 'Посебна припрема није потребна; напоменути познату алергију на метале', 'Специальной подготовки не требуется; сообщить об известной аллергии на металлы', 'Keine besondere Vorbereitung nötig; eine bekannte Metallallergie mitteilen', 'Özel hazırlık gerekmez; bilinen metal alerjisinin bildirilmesi', 'Sensitivity in the first days after cementation is normal; chipped ceramic, a metallic taste, or redness and swelling of the gum at the crown margin are reasons to see the dentist', 'Osjetljivost prvih dana nakon cementiranja je uobičajena; okrznuta keramika, metalni ukus, crvenilo ili oticanje desni uz ivicu krunice razlog su za posjetu stomatologu', 'Осјетљивост првих дана након цементирања је уобичајена; окрзнута керамика, метални укус, црвенило или отицање десни уз ивицу крунице разлог су за посјету стоматологу', 'Чувствительность в первые дни после фиксации — обычное явление; скол керамики, металлический вкус, покраснение или отёк десны у края коронки — повод обратиться к стоматологу', 'Empfindlichkeit in den ersten Tagen nach dem Zementieren ist normal; abgeplatzte Keramik, metallischer Geschmack oder Rötung und Schwellung des Zahnfleischs am Kronenrand sind ein Grund für einen Zahnarztbesuch', 'Simantasyondan sonraki ilk günlerde hassasiyet normaldir; seramikte kırık, metalik tat, kron kenarında diş etinde kızarıklık veya şişlik diş hekimine başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'ceramic-crown-on-gold'), 'A ceramic crown on a gold-alloy framework — combining the natural look of ceramic with the soft sheen of gold underneath', 'Keramička krunica na skeletu od legure sa zlatom — spaja prirodan izgled keramike i blagi sjaj zlata ispod nje', 'Керамичка круница на скелету од легуре са златом — спаја природан изглед керамике и благи сјај злата испод ње', 'Керамическая коронка на каркасе из золотосодержащего сплава — сочетание естественного вида керамики и мягкого блеска золота под ней', 'Eine Keramikkrone auf einem Gerüst aus goldhaltiger Legierung — natürliche Optik der Keramik und der weiche Schimmer des Goldes darunter', 'Altın içeren alaşım alt yapı üzerine yapılan seramik kron — seramiğin doğal görünümüyle altındaki altının yumuşak parlaklığını birleştirir', 'Tooth preparation, an impression, fabrication of the gold framework and layering of ceramic in the laboratory, try-in and cementation; usually 2-3 visits', 'Brušenje zuba, otisak, izrada zlatnog skeleta i slojevito nanošenje keramike u laboratoriji, proba i cementiranje; obično 2-3 posjete', 'Брушење зуба, отисак, израда златног скелета и слојевито наношење керамике у лабораторији, проба и цементирање; обично 2-3 посјете', 'Обточка зуба, слепок, изготовление золотого каркаса и послойное нанесение керамики в лаборатории, примерка и фиксация; обычно 2-3 визита', 'Beschleifen des Zahns, Abdruck, Anfertigung des Goldgerüsts und schichtweises Aufbrennen der Keramik im Labor, Anprobe und Zementieren; in der Regel 2-3 Termine', 'Dişin aşındırılması, ölçü, laboratuvarda altın alt yapının hazırlanması ve seramiğin katman katman işlenmesi, prova ve simantasyon; genellikle 2-3 seans', 'Restoration of a tooth where framework biocompatibility and precise fit matter; replacement of a restoration in patients who do not tolerate other alloys', 'Obnova zuba kada su važni biokompatibilnost skeleta i precizno naslanjanje; zamjena restauracije kod nepodnošenja drugih legura', 'Обнова зуба када су важни биокомпатибилност скелета и прецизно наслањање; замјена рестаурације код неподношења других легура', 'Восстановление зуба, когда важны биосовместимость каркаса и точность прилегания; замена реставрации при непереносимости других сплавов', 'Versorgung eines Zahns, wenn Biokompatibilität des Gerüsts und Passgenauigkeit wichtig sind; Ersatz einer Restauration bei Unverträglichkeit anderer Legierungen', 'Alt yapının doku uyumu ve hassas oturumun önemli olduğu diş restorasyonları; diğer alaşımların tolere edilmediği durumlarda restorasyon değişimi', 'No special preparation is required; check with the clinic whether the cost of the alloy is included in the price', 'Posebna priprema nije potrebna; provjeriti u klinici da li je cijena legure uključena u cijenu rada', 'Посебна припрема није потребна; провјерити у клиници да ли је цијена легуре укључена у цијену рада', 'Специальной подготовки не требуется; уточнить у клиники, входит ли стоимость сплава в цену работы', 'Keine besondere Vorbereitung nötig; in der Praxis nachfragen, ob die Legierungskosten im Preis enthalten sind', 'Özel hazırlık gerekmez; alaşım bedelinin fiyata dahil olup olmadığını klinikten teyit etmek', 'Slight sensitivity after cementation subsides within a few days; persistent pain, a loose crown, or gum inflammation require a dental examination', 'Blaga osjetljivost nakon cementiranja prolazi za nekoliko dana; bol koja ne prolazi, klaćenje krunice ili upala desni zahtijevaju pregled kod stomatologa', 'Блага осјетљивост након цементирања пролази за неколико дана; бол која не пролази, клаћење крунице или упала десни захтијевају преглед код стоматолога', 'Небольшая чувствительность после фиксации проходит за несколько дней; сохраняющаяся боль, подвижность коронки или воспаление десны требуют осмотра стоматолога', 'Leichte Empfindlichkeit nach dem Zementieren geht innerhalb weniger Tage zurück; anhaltende Schmerzen, eine gelockerte Krone oder eine Zahnfleischentzündung erfordern eine zahnärztliche Untersuchung', 'Simantasyon sonrası hafif hassasiyet birkaç günde geçer; geçmeyen ağrı, kronun oynaması veya diş eti iltihabı hekim muayenesi gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'zirconia-crown-with-veneer'), 'A crown with a zirconium dioxide framework and a ceramic veneer layered on top for a natural appearance', 'Krunica sa skeletom od cirkonijum-dioksida i keramičkom fasetom nanesenom preko njega za prirodan izgled', 'Круница са скелетом од цирконијум-диоксида и керамичком фасетом нанесеном преко њега за природан изглед', 'Коронка с каркасом из диоксида циркония и керамической облицовкой, нанесённой поверх для естественного вида', 'Eine Krone mit einem Gerüst aus Zirkoniumdioxid und einer darauf aufgebrachten keramischen Verblendung für ein natürliches Aussehen', 'Zirkonyum dioksit alt yapısı ve doğal görünüm için üzerine işlenmiş seramik kaplaması olan kron', 'Tooth preparation, digital scan or impression, milling of the zirconia framework and ceramic layering in the laboratory, cementation; usually 2 visits', 'Brušenje zuba, digitalno skeniranje ili otisak, frezovanje cirkonijumskog skeleta i oblaganje keramikom u laboratoriji, cementiranje; obično 2 posjete', 'Брушење зуба, дигитално скенирање или отисак, фрезовање цирконијумског скелета и облагање керамиком у лабораторији, цементирање; обично 2 посјете', 'Обточка зуба, цифровое сканирование или слепок, фрезерование циркониевого каркаса и облицовка керамикой в лаборатории, фиксация; обычно 2 визита', 'Beschleifen des Zahns, digitaler Scan oder Abdruck, Fräsen des Zirkongerüsts und keramische Verblendung im Labor, Zementieren; in der Regel 2 Termine', 'Dişin aşındırılması, dijital tarama veya ölçü, laboratuvarda zirkonyum alt yapının kazınması ve seramikle kaplanması, simantasyon; genellikle 2 seans', 'Restoration of front teeth and bridge supports where both strength and natural aesthetics are needed; replacing metal-ceramic with a metal-free design', 'Obnova prednjih zuba i nosača mostova kada su potrebni i čvrstina i prirodna estetika; zamjena metalokeramike konstrukcijom bez metala', 'Обнова предњих зуба и носача мостова када су потребни и чврстина и природна естетика; замјена металокерамике конструкцијом без метала', 'Восстановление передних зубов и опор мостов, когда нужны и прочность, и естественная эстетика; замена металлокерамики без металла в конструкции', 'Versorgung von Frontzähnen und Brückenpfeilern, wenn Stabilität und natürliche Ästhetik gefragt sind; Ersatz von Metallkeramik durch eine metallfreie Konstruktion', 'Hem dayanıklılık hem doğal estetik gereken ön diş ve köprü ayağı restorasyonları; metal destekli kronun metalsiz yapıyla değiştirilmesi', 'No special preparation is required; a badly damaged tooth first receives root canal treatment or a post and core', 'Posebna priprema nije potrebna; kod jako oštećenog zuba prvo se radi kanalno liječenje ili nadogradnja', 'Посебна припрема није потребна; код јако оштећеног зуба прво се ради канално лијечење или надоградња', 'Специальной подготовки не требуется; при разрушенном зубе сначала выполняют лечение каналов или культевую вкладку', 'Keine besondere Vorbereitung nötig; ein stark geschädigter Zahn erhält zunächst eine Wurzelbehandlung oder einen Stiftaufbau', 'Özel hazırlık gerekmez; ileri harap dişe önce kanal tedavisi veya post-kor yapılır', 'Discomfort when biting in the first days is resolved by adjusting the bite; a chipped veneer or pain under the crown is a reason to see the dentist', 'Nelagodnost pri zagrizanju prvih dana rješava se korekcijom zagriza; okrznuta faseta ili bol pod krunicom razlog su za posjetu stomatologu', 'Нелагодност при загризању првих дана рјешава се корекцијом загриза; окрзнута фасета или бол под круницом разлог су за посјету стоматологу', 'Дискомфорт при накусывании в первые дни устраняется коррекцией по прикусу; скол облицовки или боль под коронкой — повод обратиться к стоматологу', 'Unbehagen beim Zubeißen in den ersten Tagen wird durch eine Bisskorrektur behoben; eine abgeplatzte Verblendung oder Schmerzen unter der Krone sind ein Grund für einen Zahnarztbesuch', 'İlk günlerde ısırırken rahatsızlık kapanış düzeltmesiyle giderilir; kaplamada kırık veya kron altında ağrı diş hekimine başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'zirconia-multilayer-crown'), 'A crown milled entirely from a multilayer zirconia blank, with a smooth color transition from the neck to the incisal edge', 'Krunica izrađena u cijelosti od višeslojnog cirkonijumskog bloka, sa blagim prelazom boje od vrata do sječivne ivice', 'Круница израђена у цијелости од вишеслојног цирконијумског блока, са благим прелазом боје од врата до сјечивне ивице', 'Коронка, целиком выточенная из многослойной циркониевой заготовки с плавным переходом цвета от шейки к режущему краю', 'Eine Krone, die vollständig aus einem mehrschichtigen Zirkonrohling gefräst wird, mit sanftem Farbverlauf vom Zahnhals zur Schneidekante', 'Diş etinden kesici kenara doğru yumuşak renk geçişi olan, tamamen çok katmanlı zirkonyum bloktan kazınan kron', 'Tooth preparation, digital scan, milling of the crown from a solid block, and cementation; often completed in 1-2 visits, as no ceramic layering is needed', 'Brušenje zuba, digitalno skeniranje, frezovanje krunice iz monolitnog bloka i cementiranje; često se završava u 1-2 posjete jer oblaganje keramikom nije potrebno', 'Брушење зуба, дигитално скенирање, фрезовање крунице из монолитног блока и цементирање; често се завршава у 1-2 посјете јер облагање керамиком није потребно', 'Обточка зуба, цифровое сканирование, фрезерование коронки из монолитного блока и фиксация; часто выполняется за 1-2 визита, так как облицовка керамикой не нужна', 'Beschleifen des Zahns, digitaler Scan, Fräsen der Krone aus einem massiven Block und Zementieren; oft in 1-2 Terminen abgeschlossen, da keine keramische Verblendung nötig ist', 'Dişin aşındırılması, dijital tarama, kronun tek parça bloktan kazınması ve simantasyon; seramik kaplama gerekmediği için sıklıkla 1-2 seansta tamamlanır', 'Restoration of back and front teeth where the strength of a monolithic design without the risk of veneer chipping matters', 'Obnova bočnih i prednjih zuba kada je važna čvrstina jedinstvene konstrukcije bez rizika od okrzavanja fasete', 'Обнова бочних и предњих зуба када је важна чврстина јединствене конструкције без ризика од окрзавања фасете', 'Восстановление боковых и передних зубов, когда важна прочность цельной конструкции без риска скола облицовки', 'Versorgung von Seiten- und Frontzähnen, wenn die Stabilität einer monolithischen Konstruktion ohne Risiko von Verblendabplatzungen wichtig ist', 'Kaplamanın kırılma riski olmayan tek parça yapının dayanıklılığının önemli olduğu arka ve ön diş restorasyonları', 'No special preparation is required; cavities and gum inflammation are treated beforehand', 'Posebna priprema nije potrebna; prethodno se liječe karijes i upala desni', 'Посебна припрема није потребна; претходно се лијече каријес и упала десни', 'Специальной подготовки не требуется; предварительно лечат кариес и воспаление дёсен', 'Keine besondere Vorbereitung nötig; Karies und Zahnfleischentzündungen werden vorab behandelt', 'Özel hazırlık gerekmez; öncesinde çürük ve diş eti iltihabı tedavi edilir', 'Slight sensitivity after cementation passes within a few days; if the crown feels "high" when the jaws close, have it adjusted without waiting for pain in the tooth or joint', 'Blaga osjetljivost nakon cementiranja prolazi za nekoliko dana; osjećaj da je krunica „visoka“ pri zagrizu treba korigovati kod stomatologa, ne čekajući bol u zubu ili zglobu', 'Блага осјетљивост након цементирања пролази за неколико дана; осјећај да је круница „висока“ при загризу треба кориговати код стоматолога, не чекајући бол у зубу или зглобу', 'Небольшая чувствительность после фиксации проходит за несколько дней; ощущение «высокой» коронки при смыкании челюстей нужно скорректировать у стоматолога, не дожидаясь боли в зубе или суставе', 'Leichte Empfindlichkeit nach dem Zementieren vergeht in wenigen Tagen; fühlt sich die Krone beim Zubeißen "zu hoch" an, sollte sie angepasst werden, ohne auf Schmerzen im Zahn oder Kiefergelenk zu warten', 'Simantasyon sonrası hafif hassasiyet birkaç günde geçer; çeneler kapanırken kron "yüksek" geliyorsa, dişte veya çene ekleminde ağrı beklenmeden düzeltilmesi gerekir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'cadcam-e-max-layered-crown'), 'A metal-free crown made of lithium disilicate (E-max), produced with digital CAD/CAM technology and finished with an additional ceramic layer', 'Bezmetalna krunica od litijum-disilikata (E-max), izrađena digitalnom CAD/CAM tehnologijom sa dodatnom keramičkom fasetom', 'Безметална круница од литијум-дисиликата (E-max), израђена дигиталном CAD/CAM технологијом са додатном керамичком фасетом', 'Безметалловая коронка из литиевого дисиликата (E-max), изготовленная по цифровой технологии CAD/CAM с дополнительной керамической облицовкой', 'Eine metallfreie Krone aus Lithiumdisilikat (E-max), digital mit CAD/CAM gefertigt und zusätzlich keramisch verblendet', 'Dijital CAD/CAM teknolojisiyle üretilen ve ek seramik kaplamayla bitirilen lityum disilikat (E-max) metal desteksiz kron', 'Scanning the prepared tooth, computer design, milling of the crown and layered ceramic finishing in the laboratory, then adhesive bonding; usually 2 visits', 'Skeniranje izbrušenog zuba, kompjutersko modelovanje, frezovanje krunice i slojevito keramičko oblaganje u laboratoriji, zatim adhezivno cementiranje; obično 2 posjete', 'Скенирање избрушеног зуба, компјутерско моделовање, фрезовање крунице и слојевито керамичко облагање у лабораторији, затим адхезивно цементирање; обично 2 посјете', 'Сканирование обточенного зуба, компьютерное моделирование, фрезерование коронки и послойная керамическая облицовка в лаборатории, затем адгезивная фиксация; обычно 2 визита', 'Scannen des beschliffenen Zahns, computergestützte Konstruktion, Fräsen der Krone und schichtweise keramische Verblendung im Labor, danach adhäsives Einsetzen; in der Regel 2 Termine', 'Aşındırılmış dişin taranması, bilgisayarda tasarım, kronun kazınması ve laboratuvarda katmanlı seramik kaplama, ardından adeziv yapıştırma; genellikle 2 seans', 'Aesthetic restoration of front teeth and smaller back-tooth restorations, when the most natural color rendition is needed', 'Estetska obnova prednjih zuba i manjih bočnih restauracija, kada je potrebno što prirodnije prenošenje boje', 'Естетска обнова предњих зуба и мањих бочних рестаурација, када је потребно што природније преношење боје', 'Эстетическое восстановление передних зубов и небольших боковых реставраций, когда нужна максимально естественная передача цвета', 'Ästhetische Versorgung der Frontzähne und kleinerer Seitenzahnrestaurationen, wenn eine möglichst natürliche Farbwiedergabe gefragt ist', 'En doğal renk geçişinin gerektiği ön diş estetik restorasyonları ve küçük arka diş restorasyonları', 'No special preparation is required; the desired shade is best agreed with the dentist before the tooth is prepared', 'Posebna priprema nije potrebna; željenu nijansu je najbolje odrediti sa ljekarom prije brušenja', 'Посебна припрема није потребна; жељену нијансу је најбоље одредити са љекаром прије брушења', 'Специальной подготовки не требуется; желательно определить желаемый оттенок вместе с врачом до обточки', 'Keine besondere Vorbereitung nötig; der gewünschte Farbton sollte vor dem Beschleifen gemeinsam mit dem Zahnarzt festgelegt werden', 'Özel hazırlık gerekmez; istenen renk tonunu aşındırma öncesinde hekimle birlikte belirlemek iyi olur', 'Temperature sensitivity in the first days is normal; chipped ceramic, a rough margin, or discomfort when biting are reasons to see the dentist', 'Osjetljivost na temperaturu prvih dana je uobičajena; okrznuta keramika, hrapava ivica ili nelagodnost pri zagrizanju razlog su za posjetu stomatologu', 'Осјетљивост на температуру првих дана је уобичајена; окрзнута керамика, храпава ивица или нелагодност при загризању разлог су за посјету стоматологу', 'Чувствительность к температуре в первые дни — обычное явление; скол керамики, шероховатость края или дискомфорт при накусывании — повод обратиться к стоматологу', 'Temperaturempfindlichkeit in den ersten Tagen ist normal; abgeplatzte Keramik, ein rauer Rand oder Unbehagen beim Zubeißen sind ein Grund für einen Zahnarztbesuch', 'İlk günlerde sıcaklık hassasiyeti normaldir; seramikte kırık, pürüzlü kenar veya ısırırken rahatsızlık diş hekimine başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'maryland-bridge'), 'A small bridge bonded to the adjacent teeth with thin wings on their inner surface, without preparing them for crowns', 'Mali most koji se lijepi na susjedne zube tankim krilcima sa unutrašnje strane, bez njihovog brušenja za krunice', 'Мали мост који се лијепи на сусједне зубе танким крилцима са унутрашње стране, без њиховог брушења за крунице', 'Небольшой мостовидный протез, который приклеивается к соседним зубам тонкими крылышками с внутренней стороны, без их обточки под коронки', 'Eine kleine Brücke, die mit dünnen Flügeln an der Innenseite der Nachbarzähne verklebt wird, ohne diese für Kronen zu beschleifen', 'Komşu dişleri kron için aşındırmadan, iç yüzeylerine ince kanatlarla yapıştırılan küçük köprü', 'An impression or scan, fabrication of the framework in the laboratory, and bonding of the wings to the enamel of the neighboring teeth with adhesive cement; usually 2 visits', 'Otisak ili skeniranje, izrada konstrukcije u laboratoriji i lijepljenje krilaca na gleđ susjednih zuba adhezivnim cementom; obično 2 posjete', 'Отисак или скенирање, израда конструкције у лабораторији и лијепљење крилаца на глеђ сусједних зуба адхезивним цементом; обично 2 посјете', 'Слепок или сканирование, изготовление конструкции в лаборатории и приклеивание крылышек к эмали соседних зубов адгезивным цементом; обычно 2 визита', 'Abdruck oder Scan, Anfertigung der Konstruktion im Labor und Verkleben der Flügel mit dem Zahnschmelz der Nachbarzähne mittels Adhäsivzement; in der Regel 2 Termine', 'Ölçü veya tarama, yapının laboratuvarda üretimi ve kanatların komşu dişlerin minesine adeziv simanla yapıştırılması; genellikle 2 seans', 'A single missing tooth, most often a front one, with healthy neighboring teeth; a temporary or minimally invasive solution before implants', 'Nedostatak jednog zuba, najčešće prednjeg, uz zdrave susjedne zube; privremeno ili štedljivo rješenje do implantacije', 'Недостатак једног зуба, најчешће предњег, уз здраве сусједне зубе; привремено или штедљиво рјешење до имплантације', 'Отсутствие одного зуба, чаще переднего, при здоровых соседних зубах; временное или щадящее решение до имплантации', 'Ein einzelner fehlender Zahn, meist im Frontbereich, bei gesunden Nachbarzähnen; provisorische oder besonders zahnschonende Lösung vor einem Implantat', 'Komşu dişlerin sağlam olduğu tek diş eksikliği, çoğunlukla ön bölgede; implanta kadar geçici veya dişleri koruyan çözüm', 'The adjacent teeth should be free of large fillings and cavities; a professional cleaning before bonding improves adhesion', 'Susjedni zubi treba da budu bez velikih plombi i karijesa; profesionalno čišćenje prije lijepljenja poboljšava vezu', 'Сусједни зуби треба да буду без великих пломби и каријеса; професионално чишћење прије лијепљења побољшава везу', 'Соседние зубы должны быть без крупных пломб и кариеса; профессиональная чистка перед фиксацией улучшает приклеивание', 'Die Nachbarzähne sollten frei von großen Füllungen und Karies sein; eine professionelle Reinigung vor dem Kleben verbessert den Verbund', 'Komşu dişlerde büyük dolgu ve çürük bulunmaması; yapıştırma öncesi profesyonel temizlik bağlanmayı iyileştirir', 'A period of getting used to the new tooth is possible; if a wing debonds, the bridge should be shown to a dentist as soon as possible — decay can develop underneath', 'Moguć je period privikavanja na novi zub; ako se krilce odlijepi, konstrukciju treba što prije pokazati stomatologu — ispod nje se može razviti karijes', 'Могућ је период привикавања на нови зуб; ако се крилце одлијепи, конструкцију треба што прије показати стоматологу — испод ње се може развити каријес', 'Возможен период привыкания к новому зубу; при отклеивании крылышка конструкцию нужно как можно быстрее показать стоматологу — под ней может развиться кариес', 'Eine Eingewöhnungszeit an den neuen Zahn ist möglich; löst sich ein Flügel, sollte die Brücke möglichst schnell einem Zahnarzt gezeigt werden — darunter kann Karies entstehen', 'Yeni dişe alışma dönemi olabilir; bir kanat yerinden çıkarsa köprü en kısa sürede hekime gösterilmelidir — altında çürük gelişebilir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'dental-bridge-abutment'), 'The supporting unit of a dental bridge — a crown on a natural tooth or implant that carries the bridge', 'Noseći element mosta — krunica na sopstvenom zubu ili implantatu koja drži most', 'Носећи елемент моста — круница на сопственом зубу или имплантату која држи мост', 'Опорный элемент мостовидного протеза — коронка на собственном зубе или имплантате, на которой держится мост', 'Das Trägerelement einer Brücke — eine Krone auf einem eigenen Zahn oder Implantat, die die Brücke hält', 'Köprüyü taşıyan destek birimi — kendi diş veya implant üzerine yapılan kron', 'Preparation of the supporting tooth or of the implant abutment, an impression, laboratory fabrication and cementation together with the rest of the bridge; most often 2-3 visits', 'Brušenje nosećeg zuba ili priprema abatmenta implantata, otisak, izrada u laboratoriji i cementiranje zajedno sa ostalim dijelovima mosta; najčešće 2-3 posjete', 'Брушење носећег зуба или припрема абатмента имплантата, отисак, израда у лабораторији и цементирање заједно са осталим дијеловима моста; најчешће 2-3 посјете', 'Обточка опорного зуба или подготовка абатмента имплантата, слепок, изготовление в лаборатории и фиксация вместе с остальными частями моста; чаще всего 2-3 визита', 'Beschleifen des Pfeilerzahns oder Vorbereitung des Implantataufbaus, Abdruck, Anfertigung im Labor und Zementieren zusammen mit den übrigen Brückenteilen; meist 2-3 Termine', 'Destek dişin aşındırılması veya implant abutmentının hazırlanması, ölçü, laboratuvarda üretim ve köprünün diğer parçalarıyla birlikte simantasyon; çoğunlukla 2-3 seans', 'Fabrication of a dental bridge — the price is usually counted per abutment and per replaced tooth separately', 'Izrada mosta — cijena se obično računa po svakom nosaču i po svakom zubu koji se zamjenjuje', 'Израда моста — цијена се обично рачуна по сваком носачу и по сваком зубу који се замјењује', 'Изготовление мостовидного протеза — цена обычно считается за каждую опору и за каждый замещаемый зуб отдельно', 'Anfertigung einer Brücke — der Preis wird üblicherweise je Pfeiler und je ersetzten Zahn separat berechnet', 'Köprü yapımı — fiyat genellikle her destek ve tamamlanan her diş için ayrı hesaplanır', 'Assessment of the supporting teeth and root canal treatment if needed; check with the clinic how many abutments and pontics are included in the final price', 'Procjena stanja nosećih zuba, po potrebi kanalno liječenje; provjeriti u klinici koliko nosača i međučlanova ulazi u konačnu cijenu', 'Процјена стања носећих зуба, по потреби канално лијечење; провјерити у клиници колико носача и међучланова улази у коначну цијену', 'Оценка состояния опорных зубов, при необходимости лечение каналов; уточнить у клиники, сколько опор и промежуточных зубов входит в итоговую стоимость', 'Beurteilung der Pfeilerzähne, bei Bedarf Wurzelbehandlung; in der Praxis nachfragen, wie viele Pfeiler und Zwischenglieder im Endpreis enthalten sind', 'Destek dişlerin değerlendirilmesi, gerekirse kanal tedavisi; kaç destek ve ara dişin toplam fiyata dahil olduğunu klinikten teyit etmek', 'Sensitivity of the supporting teeth in the first days is normal; a bridge that comes loose, pain, or gum inflammation at an abutment require a dental examination', 'Osjetljivost nosećih zuba prvih dana je uobičajena; most koji se odcementira, bol ili upala desni kod nosača zahtijevaju pregled kod stomatologa', 'Осјетљивост носећих зуба првих дана је уобичајена; мост који се одцементира, бол или упала десни код носача захтијевају преглед код стоматолога', 'Чувствительность опорных зубов в первые дни — обычное явление; расцементировка моста, боль или воспаление десны у опоры требуют осмотра стоматолога', 'Empfindlichkeit der Pfeilerzähne in den ersten Tagen ist normal; eine sich lösende Brücke, Schmerzen oder eine Zahnfleischentzündung am Pfeiler erfordern eine zahnärztliche Untersuchung', 'İlk günlerde destek dişlerde hassasiyet normaldir; köprünün yerinden çıkması, ağrı veya destek çevresinde diş eti iltihabı hekim muayenesi gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'metal-free-implant-crown-with-original-abutment'), 'A metal-free crown on an implant, placed on the original abutment made by the implant system manufacturer', 'Bezmetalna krunica na implantatu, postavljena na originalni abatment proizvođača implantnog sistema', 'Безметална круница на имплантату, постављена на оригинални абатмент произвођача имплантног система', 'Безметалловая коронка на имплантате, установленная на оригинальный абатмент производителя имплантационной системы', 'Eine metallfreie Krone auf einem Implantat, die auf dem Originalaufbau des Implantatherstellers befestigt wird', 'İmplant sisteminin üreticisine ait orijinal abutment üzerine yapılan metal desteksiz implant kronu', 'Once the implant has healed, an impression or scan is taken, the crown is made on the original abutment in the laboratory, and then fitted in the mouth; usually 2-3 visits', 'Nakon zarastanja implantata uzima se otisak ili skan, u laboratoriji se izrađuje krunica na originalnom abatmentu, a zatim se postavlja u ustima; obično 2-3 posjete', 'Након зарастања имплантата узима се отисак или скан, у лабораторији се израђује круница на оригиналном абатменту, а затим се поставља у устима; обично 2-3 посјете', 'После заживления имплантата снимают слепок или скан, в лаборатории изготавливают коронку на оригинальном абатменте, затем фиксируют её в полости рта; обычно 2-3 визита', 'Nach der Einheilung des Implantats werden Abdruck oder Scan genommen, die Krone wird im Labor auf dem Originalaufbau angefertigt und dann im Mund eingesetzt; in der Regel 2-3 Termine', 'İmplant iyileştikten sonra ölçü veya tarama alınır, laboratuvarda orijinal abutment üzerine kron hazırlanır, ardından ağızda takılır; genellikle 2-3 seans', 'The final stage of implant treatment in an area where aesthetics matter; replacement of a crown on an existing implant', 'Završna faza implantacije u zoni gdje je estetika važna; zamjena krunice na već postavljenom implantatu', 'Завршна фаза имплантације у зони гдје је естетика важна; замјена крунице на већ постављеном имплантату', 'Завершающий этап имплантации в зоне, где важна эстетика; замена коронки на уже установленном имплантате', 'Abschluss der Implantatbehandlung in einem Bereich, in dem die Ästhetik wichtig ist; Ersatz einer Krone auf einem bereits vorhandenen Implantat', 'Estetiğin önemli olduğu bölgede implant tedavisinin son aşaması; mevcut implant üzerindeki kronun değiştirilmesi', 'The implant must be fully integrated (the timing is set by the dentist); healthy gums around the implant and good hygiene are needed', 'Implantat treba da bude potpuno srastao (rokove određuje ljekar); potrebne su zdrave desni oko implantata i dobra higijena', 'Имплантат треба да буде потпуно срастао (рокове одређује љекар); потребне су здраве десни око имплантата и добра хигијена', 'Имплантат должен полностью прижиться (сроки определяет врач); нужны здоровые дёсны вокруг имплантата и хорошая гигиена', 'Das Implantat muss vollständig eingeheilt sein (Zeitpunkt legt der Arzt fest); gesundes Zahnfleisch um das Implantat und gute Hygiene sind erforderlich', 'İmplantın tam kaynaşmış olması (süreyi hekim belirler); implant çevresinde sağlıklı diş eti ve iyi hijyen', 'Mild discomfort when biting in the first days is normal; bleeding or swelling of the gum around the crown, or mobility of the restoration, require a dental examination', 'Blaga nelagodnost pri zagrizanju prvih dana je uobičajena; krvarenje ili oticanje desni oko krunice, kao i klaćenje konstrukcije, zahtijevaju pregled kod ljekara', 'Блага нелагодност при загризању првих дана је уобичајена; крварење или отицање десни око крунице, као и клаћење конструкције, захтијевају преглед код љекара', 'Небольшой дискомфорт при накусывании в первые дни — обычное явление; кровоточивость или отёк десны вокруг коронки, а также подвижность конструкции требуют осмотра врача', 'Leichtes Unbehagen beim Zubeißen in den ersten Tagen ist normal; Blutung oder Schwellung des Zahnfleischs um die Krone sowie eine Beweglichkeit der Konstruktion erfordern eine ärztliche Untersuchung', 'İlk günlerde ısırırken hafif rahatsızlık normaldir; kron çevresinde diş eti kanaması veya şişlik ile yapının oynaması hekim muayenesi gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'screw-retained-implant-crown-zirconia'), 'A zirconia implant crown retained by a screw rather than cement — it can be removed and refitted if needed', 'Cirkonijumska krunica na implantatu koja se pričvršćuje vijkom, a ne cementom — po potrebi se može skinuti i ponovo postaviti', 'Цирконијумска круница на имплантату која се причвршћује вијком, а не цементом — по потреби се може скинути и поново поставити', 'Циркониевая коронка на имплантате, которая крепится винтом, а не цементом — при необходимости её можно снять и поставить обратно', 'Eine Zirkonkrone auf einem Implantat, die mit einer Schraube statt mit Zement befestigt wird — sie kann bei Bedarf abgenommen und wieder eingesetzt werden', 'Siman yerine vidayla tutturulan zirkonyum implant kronu — gerektiğinde sökülüp yeniden takılabilir', 'An impression or scan after the implant has healed, fabrication of the crown with a screw channel, screwing it onto the implant and sealing the channel with a filling; usually 2 visits', 'Otisak ili skan nakon zarastanja implantata, izrada krunice sa kanalom za vijak, pričvršćivanje na implantat i zatvaranje kanala plombom; obično 2 posjete', 'Отисак или скан након зарастања имплантата, израда крунице са каналом за вијак, причвршћивање на имплантат и затварање канала пломбом; обично 2 посјете', 'Слепок или скан после заживления имплантата, изготовление коронки с винтовым каналом, прикручивание к имплантату и закрытие канала пломбой; обычно 2 визита', 'Abdruck oder Scan nach der Einheilung des Implantats, Anfertigung der Krone mit Schraubkanal, Verschrauben auf dem Implantat und Verschließen des Kanals mit einer Füllung; in der Regel 2 Termine', 'İmplant iyileştikten sonra ölçü veya tarama, vida kanallı kronun üretimi, implanta vidalanması ve kanalın dolguyla kapatılması; genellikle 2 seans', 'Restoring an implant when the option to remove the crown for maintenance or adjustment matters', 'Protetika na implantatu kada je važna mogućnost skidanja krunice radi održavanja ili korekcije', 'Протетика на имплантату када је важна могућност скидања крунице ради одржавања или корекције', 'Протезирование имплантата, когда важна возможность снять коронку для обслуживания или коррекции', 'Implantatversorgung, wenn die Möglichkeit wichtig ist, die Krone zur Pflege oder Korrektur abzunehmen', 'Kronun bakım veya düzeltme için sökülebilmesinin önemli olduğu implant protezleri', 'Full integration of the implant, no inflammation around it, and good hygiene', 'Potpuno srastanje implantata, bez upale oko njega, dobra higijena', 'Потпуно срастање имплантата, без упале око њега, добра хигијена', 'Полное приживление имплантата, отсутствие воспаления вокруг него, хорошая гигиена', 'Vollständige Einheilung des Implantats, keine Entzündung darum herum, gute Hygiene', 'İmplantın tam kaynaşması, çevresinde iltihap olmaması, iyi hijyen', 'Slight gum sensitivity is possible in the first days; a crown that feels loose may mean the screw has loosened — this is handled by the dentist and needs no action at home', 'Prvih dana moguća je blaga osjetljivost desni; osjećaj da se krunica klati može značiti da je vijak popustio — to rješava ljekar, ne treba ništa raditi samostalno', 'Првих дана могућа је блага осјетљивост десни; осјећај да се круница клати може значити да је вијак попустио — то рјешава љекар, не треба ништа радити самостално', 'Первые дни возможна лёгкая чувствительность десны; ощущение подвижности коронки может означать ослабление винта — это устраняет врач, самостоятельно ничего делать не нужно', 'In den ersten Tagen ist eine leichte Empfindlichkeit des Zahnfleischs möglich; fühlt sich die Krone beweglich an, kann sich die Schraube gelöst haben — das behebt der Zahnarzt, eigene Maßnahmen sind nicht nötig', 'İlk günlerde diş etinde hafif hassasiyet olabilir; kronun oynadığı hissi vidanın gevşediğini gösterebilir — bunu hekim çözer, evde bir şey yapmak gerekmez')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'screw-retained-implant-crown-cocr'), 'An implant crown with a cobalt-chromium (CoCr) framework and ceramic veneer, retained by a screw', 'Krunica na implantatu sa skeletom od kobalt-hrom legure (CoCr) i keramičkom fasetom, pričvršćena vijkom', 'Круница на имплантату са скелетом од кобалт-хром легуре (CoCr) и керамичком фасетом, причвршћена вијком', 'Коронка на имплантате с каркасом из кобальт-хромового сплава (CoCr) и керамической облицовкой, фиксируемая винтом', 'Eine Implantatkrone mit Gerüst aus Kobalt-Chrom-Legierung (CoCr) und keramischer Verblendung, verschraubt befestigt', 'Kobalt-krom (CoCr) alt yapılı, seramik kaplamalı, vidayla tutturulan implant kronu', 'An impression or scan of the implant, fabrication of the framework and veneer in the laboratory, screwing it onto the implant and sealing the screw channel; usually 2-3 visits', 'Otisak ili skan implantata, izrada skeleta i fasete u laboratoriji, pričvršćivanje na implantat i zatvaranje kanala za vijak; obično 2-3 posjete', 'Отисак или скан имплантата, израда скелета и фасете у лабораторији, причвршћивање на имплантат и затварање канала за вијак; обично 2-3 посјете', 'Слепок или скан имплантата, изготовление каркаса и облицовки в лаборатории, прикручивание к имплантату и закрытие винтового канала; обычно 2-3 визита', 'Abdruck oder Scan des Implantats, Anfertigung von Gerüst und Verblendung im Labor, Verschrauben auf dem Implantat und Verschließen des Schraubkanals; in der Regel 2-3 Termine', 'İmplantın ölçüsü veya taraması, laboratuvarda alt yapı ve kaplamanın üretimi, implanta vidalanması ve vida kanalının kapatılması; genellikle 2-3 seans', 'Restoring implants in the back of the mouth, where strength and a reasonable cost matter', 'Protetika na implantatima u bočnoj regiji, gdje su važni čvrstina i prihvatljiva cijena konstrukcije', 'Протетика на имплантатима у бочној регији, гдје су важни чврстина и прихватљива цијена конструкције', 'Протезирование имплантата в боковых отделах, где важна прочность и приемлемая стоимость конструкции', 'Implantatversorgung im Seitenzahnbereich, wo Stabilität und ein vertretbarer Preis wichtig sind', 'Dayanıklılık ve makul maliyetin önemli olduğu arka bölge implant protezleri', 'A healed implant, healthy gums, and reporting any known metal allergy', 'Zarastao implantat, zdrave desni, napomenuti poznatu alergiju na metale', 'Зарастао имплантат, здраве десни, напоменути познату алергију на метале', 'Заживший имплантат, здоровые дёсны, сообщить об известной аллергии на металлы', 'Eingeheiltes Implantat, gesundes Zahnfleisch und Mitteilung einer bekannten Metallallergie', 'İyileşmiş implant, sağlıklı diş eti, bilinen metal alerjisinin bildirilmesi', 'Mild sensitivity around the crown in the first days passes; gum bleeding when brushing, a bad odor, or a feeling of looseness are reasons for a dental examination', 'Blaga osjetljivost oko krunice prvih dana prolazi; krvarenje desni pri čišćenju, neprijatan miris ili osjećaj klaćenja razlog su za pregled kod ljekara', 'Блага осјетљивост око крунице првих дана пролази; крварење десни при чишћењу, непријатан мирис или осјећај клаћења разлог су за преглед код љекара', 'Лёгкая чувствительность вокруг коронки в первые дни проходит; кровоточивость десны при чистке, неприятный запах или ощущение расшатывания — повод для осмотра врача', 'Leichte Empfindlichkeit um die Krone in den ersten Tagen vergeht; Zahnfleischblutung beim Putzen, unangenehmer Geruch oder ein Gefühl von Lockerung sind ein Grund für eine ärztliche Untersuchung', 'İlk günlerde kron çevresinde hafif hassasiyet geçer; fırçalarken diş eti kanaması, kötü koku veya oynama hissi hekim muayenesi gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'implant-suprastructure'), 'The part that connects the implant to the crown or denture — the abutment or framework to which the visible part is then attached', 'Dio konstrukcije koji povezuje implantat sa krunicom ili protezom — abatment ili skelet na koji se potom pričvršćuje vidljivi dio', 'Дио конструкције који повезује имплантат са круницом или протезом — абатмент или скелет на који се потом причвршћује видљиви дио', 'Часть конструкции, соединяющая имплантат с коронкой или протезом — абатмент или каркас, на который затем крепится видимая часть', 'Das Bauteil, das das Implantat mit der Krone oder Prothese verbindet — der Aufbau (Abutment) oder das Gerüst, auf dem der sichtbare Teil befestigt wird', 'İmplantı kron veya protezle birleştiren parça — görünen bölümün üzerine tutturulduğu abutment ya da alt yapı', 'Selected or custom-made after the implant has healed: it is placed on the implant, and the crown or denture is then fixed to it; usually combined with the prosthetic visits', 'Bira se ili izrađuje individualno nakon zarastanja implantata: postavlja se na implantat, a zatim se na njega fiksira krunica ili proteza; obično se spaja sa posjetama za protetiku', 'Бира се или израђује индивидуално након зарастања имплантата: поставља се на имплантат, а затим се на њега фиксира круница или протеза; обично се спаја са посјетама за протетику', 'Подбирается или изготавливается индивидуально после заживления имплантата: устанавливается на имплантат, затем на неё фиксируется коронка или протез; обычно совмещается с визитами по протезированию', 'Wird nach der Einheilung des Implantats ausgewählt oder individuell angefertigt: es wird auf das Implantat gesetzt, danach wird die Krone oder Prothese daran befestigt; meist mit den prothetischen Terminen kombiniert', 'İmplant iyileştikten sonra seçilir veya kişiye özel üretilir: implanta yerleştirilir, ardından üzerine kron veya protez sabitlenir; genellikle protez seanslarıyla birleştirilir', 'Any implant-supported restoration — this component is charged separately from the implant itself and from the crown', 'Svaka protetika na implantatima — ovaj element se plaća odvojeno od samog implantata i od krunice', 'Свака протетика на имплантатима — овај елемент се плаћа одвојено од самог имплантата и од крунице', 'Любое протезирование на имплантатах — этот элемент оплачивается отдельно от самого имплантата и от коронки', 'Jede implantatgetragene Versorgung — dieses Bauteil wird getrennt vom Implantat und von der Krone berechnet', 'Tüm implant üstü protez uygulamaları — bu parça implantın ve kronun bedelinden ayrı ücretlendirilir', 'The implant must be integrated; check with the clinic in advance whether the suprastructure is included in the quoted implant price', 'Implantat treba da bude srastao; unaprijed provjeriti u klinici da li je suprastruktura uključena u navedenu cijenu implantacije', 'Имплантат треба да буде срастао; унапријед провјерити у клиници да ли је супраструктура укључена у наведену цијену имплантације', 'Имплантат должен прижиться; заранее уточнить у клиники, входит ли супраструктура в озвученную цену имплантации', 'Das Implantat muss eingeheilt sein; vorab in der Praxis klären, ob die Suprastruktur im genannten Implantatpreis enthalten ist', 'İmplantın kaynaşmış olması; suprastrüktürün belirtilen implant fiyatına dahil olup olmadığını klinikten önceden teyit etmek', 'Discomfort when biting or a feeling that the restoration moves is a reason to see the dentist to check the fit and the tightness of the connection', 'Nelagodnost pri zagrizanju ili osjećaj da se konstrukcija pomjera razlog su za posjetu ljekaru radi provjere naslanjanja i zatezanja spoja', 'Нелагодност при загризању или осјећај да се конструкција помјера разлог су за посјету љекару ради провјере наслањања и затезања споја', 'Дискомфорт при накусывании или ощущение движения конструкции — повод обратиться к врачу для проверки посадки и затяжки соединения', 'Unbehagen beim Zubeißen oder das Gefühl, dass sich die Konstruktion bewegt, ist ein Grund, den Zahnarzt Passung und Festigkeit der Verbindung prüfen zu lassen', 'Isırırken rahatsızlık veya yapının oynadığı hissi, oturumun ve bağlantı sıkılığının kontrolü için hekime başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'dental-implant-nobel-biocare'), 'Placement of a titanium dental implant from the Nobel Biocare system — an artificial root to which a crown is attached later', 'Postavljanje titanijumskog zubnog implantata sistema Nobel Biocare — vještačkog korijena na koji se kasnije pričvršćuje krunica', 'Постављање титанијумског зубног имплантата система Nobel Biocare — вјештачког коријена на који се касније причвршћује круница', 'Установка титанового зубного имплантата системы Nobel Biocare — искусственного корня, на который позже крепится коронка', 'Einsetzen eines Titan-Zahnimplantats des Systems Nobel Biocare — einer künstlichen Wurzel, auf der später eine Krone befestigt wird', 'Nobel Biocare sistemine ait titanyum diş implantının yerleştirilmesi — üzerine daha sonra kron takılan yapay kök', 'Under local anesthesia the surgeon prepares a site in the bone and inserts the implant, suturing if needed; the surgery itself takes 30-60 minutes, and the crown is made after integration (usually a few months later, as determined by the dentist)', 'U lokalnoj anesteziji ljekar priprema ležište u kosti i uvodi implantat, po potrebi postavlja šavove; sama operacija traje 30-60 minuta, a krunica se izrađuje nakon srastanja (obično poslije nekoliko mjeseci, rok određuje ljekar)', 'У локалној анестезији љекар припрема лежиште у кости и уводи имплантат, по потреби поставља шавове; сама операција траје 30-60 минута, а круница се израђује након срастања (обично послије неколико мјесеци, рок одређује љекар)', 'Под местной анестезией врач формирует ложе в кости и вводит имплантат, при необходимости накладывает швы; сама операция занимает 30-60 минут, коронку изготавливают после приживления (обычно через несколько месяцев, срок определяет врач)', 'Unter Lokalanästhesie bereitet der Arzt das Implantatbett im Knochen vor und setzt das Implantat ein, bei Bedarf mit Nähten; der Eingriff selbst dauert 30-60 Minuten, die Krone wird nach der Einheilung angefertigt (in der Regel nach einigen Monaten, den Zeitpunkt legt der Arzt fest)', 'Lokal anestezi altında hekim kemikte yuva hazırlar ve implantı yerleştirir, gerekirse dikiş atar; ameliyat 30-60 dakika sürer, kron kaynaşmadan sonra yapılır (genellikle birkaç ay sonra, süreyi hekim belirler)', 'One or several missing teeth with sufficient bone volume; an alternative to a bridge or a removable denture', 'Nedostatak jednog ili više zuba uz dovoljan obim kosti; alternativa mostu i pokretnoj protezi', 'Недостатак једног или више зуба уз довољан обим кости; алтернатива мосту и покретној протези', 'Отсутствие одного или нескольких зубов при достаточном объёме костной ткани; альтернатива мосту и съёмному протезу', 'Ein oder mehrere fehlende Zähne bei ausreichendem Knochenangebot; Alternative zu Brücke und herausnehmbarer Prothese', 'Kemik hacminin yeterli olduğu bir veya birkaç diş eksikliği; köprü ve hareketli proteze alternatif', 'A panoramic X-ray or CT scan, treatment of any oral disease, and informing the dentist about chronic conditions and medications (especially blood thinners and bone medications)', 'Panoramski snimak ili CT, sanacija usne duplje, obavijestiti ljekara o hroničnim bolestima i lijekovima (naročito onim za razrjeđivanje krvi i lijekovima za kosti)', 'Панорамски снимак или ЦТ, санација усне дупље, обавијестити љекара о хроничним болестима и лијековима (нарочито оним за разрјеђивање крви и лијековима за кости)', 'Панорамный снимок или КТ, санация полости рта, сообщить о хронических заболеваниях и препаратах (особенно разжижающих кровь и препаратах для лечения костей)', 'Panoramaröntgen oder CT, Sanierung der Mundhöhle, Information über chronische Erkrankungen und Medikamente (insbesondere Blutverdünner und Knochenmedikamente)', 'Panoramik film veya BT, ağız sağlığının düzenlenmesi, kronik hastalıkların ve ilaçların (özellikle kan sulandırıcılar ve kemik ilaçları) bildirilmesi', 'Swelling, bruising, and moderate soreness in the first 2-3 days are a normal reaction; increasing pain, pus, fever, or a mobile implant require an urgent examination', 'Oticanje, modrica i umjerena bol prvih 2-3 dana su uobičajena reakcija; bol koja se pojačava, gnojni iscjedak, povišena temperatura ili klaćenje implantata zahtijevaju hitan pregled', 'Отицање, модрица и умјерена бол првих 2-3 дана су уобичајена реакција; бол која се појачава, гнојни исцједак, повишена температура или клаћење имплантата захтијевају хитан преглед', 'Отёк, синяк и умеренная болезненность в первые 2-3 дня — обычная реакция; нарастающая боль, гнойные выделения, температура или подвижность имплантата требуют срочного осмотра', 'Schwellung, Bluterguss und moderate Schmerzen in den ersten 2-3 Tagen sind eine normale Reaktion; zunehmende Schmerzen, Eiterausfluss, Fieber oder ein bewegliches Implantat erfordern eine sofortige Untersuchung', 'İlk 2-3 gün şişlik, morluk ve orta düzeyde ağrı normal tepkidir; artan ağrı, iltihaplı akıntı, ateş veya implantın oynaması acil muayene gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'dental-implant-straumann'), 'Placement of a Straumann dental implant — a titanium or titanium-zirconium artificial root for subsequent prosthetic restoration', 'Postavljanje zubnog implantata sistema Straumann — titanijumskog ili titanijum-cirkonijumskog vještačkog korijena za kasniju protetiku', 'Постављање зубног имплантата система Straumann — титанијумског или титанијум-цирконијумског вјештачког коријена за каснију протетику', 'Установка зубного имплантата системы Straumann — титанового или титан-циркониевого искусственного корня для последующего протезирования', 'Einsetzen eines Zahnimplantats des Systems Straumann — einer künstlichen Wurzel aus Titan oder Titan-Zirkonium für die spätere prothetische Versorgung', 'Straumann sistemine ait diş implantının yerleştirilmesi — sonraki protez için titanyum veya titanyum-zirkonyum yapay kök', 'Surgery under local anesthesia: preparation of the bone site, insertion of the implant, sutures if needed; 30-60 minutes, with the restoration made after integration at a time set by the dentist', 'Operacija u lokalnoj anesteziji: priprema ležišta u kosti, uvođenje implantata, po potrebi šavovi; 30-60 minuta, protetika slijedi nakon srastanja u roku koji određuje ljekar', 'Операција у локалној анестезији: припрема лежишта у кости, увођење имплантата, по потреби шавови; 30-60 минута, протетика слиједи након срастања у року који одређује љекар', 'Операция под местной анестезией: подготовка костного ложа, введение имплантата, при необходимости швы; 30-60 минут, протезирование — после приживления в срок, который определяет врач', 'Eingriff unter Lokalanästhesie: Vorbereitung des Knochenbetts, Einsetzen des Implantats, bei Bedarf Nähte; 30-60 Minuten, die prothetische Versorgung folgt nach der Einheilung zu einem vom Arzt festgelegten Zeitpunkt', 'Lokal anestezi altında ameliyat: kemikte yuvanın hazırlanması, implantın yerleştirilmesi, gerekirse dikiş; 30-60 dakika, protez kaynaşmadan sonra hekimin belirlediği sürede yapılır', 'Replacement of one or several missing teeth, support for a bridge or a removable denture', 'Zamjena jednog ili više zuba koji nedostaju, nosač za most ili pokretnu protezu', 'Замјена једног или више зуба који недостају, носач за мост или покретну протезу', 'Замещение одного или нескольких отсутствующих зубов, опора для моста или съёмного протеза', 'Ersatz eines oder mehrerer fehlender Zähne, Verankerung für eine Brücke oder eine herausnehmbare Prothese', 'Bir veya birkaç eksik dişin tamamlanması, köprü ya da hareketli protez için destek', 'A CT or panoramic X-ray to assess the bone, treatment of cavities and gum inflammation; stopping smoking during healing markedly improves the outlook', 'CT ili panoramski snimak za procjenu kosti, liječenje karijesa i upale desni; prestanak pušenja tokom zarastanja znatno poboljšava ishod', 'ЦТ или панорамски снимак за процјену кости, лијечење каријеса и упале десни; престанак пушења током зарастања знатно побољшава исход', 'КТ или панорамный снимок для оценки кости, лечение кариеса и воспаления дёсен, отказ от курения в период заживления заметно улучшает прогноз', 'CT oder Panoramaröntgen zur Beurteilung des Knochens, Behandlung von Karies und Zahnfleischentzündungen; ein Rauchstopp während der Heilung verbessert die Prognose deutlich', 'Kemiğin değerlendirilmesi için BT veya panoramik film, çürük ve diş eti iltihabı tedavisi; iyileşme döneminde sigaranın bırakılması sonucu belirgin iyileştirir', 'Moderate swelling and soreness in the first days are normal; ongoing bleeding, increasing pain, or a bad odor from the surgical area is a reason to contact the dentist urgently', 'Umjereno oticanje i bol prvih dana su normalni; krvarenje koje ne prestaje, bol koja se pojačava ili neprijatan miris iz operisanog područja razlog su za hitno obraćanje ljekaru', 'Умјерено отицање и бол првих дана су нормални; крварење које не престаје, бол која се појачава или непријатан мирис из оперисаног подручја разлог су за хитно обраћање љекару', 'Умеренный отёк и болезненность первые дни — норма; сохраняющееся кровотечение, усиливающаяся боль или неприятный запах из области операции — повод срочно обратиться к врачу', 'Moderate Schwellung und Schmerzen in den ersten Tagen sind normal; anhaltende Blutung, zunehmende Schmerzen oder unangenehmer Geruch aus dem Operationsgebiet sind ein Grund, sofort den Arzt aufzusuchen', 'İlk günlerde orta düzeyde şişlik ve ağrı normaldir; durmayan kanama, artan ağrı veya ameliyat bölgesinden kötü koku acilen hekime başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'dental-implant-bredent'), 'Placement of a Bredent (Germany) dental implant — a titanium artificial root for a future crown or denture', 'Postavljanje zubnog implantata sistema Bredent (Njemačka) — titanijumskog vještačkog korijena za buduću krunicu ili protezu', 'Постављање зубног имплантата система Bredent (Њемачка) — титанијумског вјештачког коријена за будућу круницу или протезу', 'Установка зубного имплантата системы Bredent (Германия) — титанового искусственного корня под будущую коронку или протез', 'Einsetzen eines Zahnimplantats des Systems Bredent (Deutschland) — einer künstlichen Titanwurzel für eine künftige Krone oder Prothese', 'Bredent (Almanya) sistemine ait diş implantının yerleştirilmesi — ileride yapılacak kron veya protez için titanyum yapay kök', 'Under local anesthesia a site is prepared in the bone and the implant is placed; 30-60 minutes, followed by the healing period and a separate prosthetic stage', 'U lokalnoj anesteziji priprema se ležište u kosti i postavlja implantat; 30-60 minuta, zatim slijedi period srastanja i posebna faza protetike', 'У локалној анестезији припрема се лежиште у кости и поставља имплантат; 30-60 минута, затим слиједи период срастања и посебна фаза протетике', 'Под местной анестезией формируется ложе в кости и устанавливается имплантат; 30-60 минут, далее период приживления и отдельный этап протезирования', 'Unter Lokalanästhesie wird das Implantatbett im Knochen vorbereitet und das Implantat eingesetzt; 30-60 Minuten, danach folgen die Einheilphase und ein separater prothetischer Abschnitt', 'Lokal anestezi altında kemikte yuva hazırlanır ve implant yerleştirilir; 30-60 dakika, ardından iyileşme dönemi ve ayrı bir protez aşaması', 'Missing teeth with sufficient bone volume; support for a single crown, a bridge, or a denture', 'Nedostatak zuba uz dovoljan obim kosti; nosač pojedinačne krunice, mosta ili proteze', 'Недостатак зуба уз довољан обим кости; носач појединачне крунице, моста или протезе', 'Отсутствие зубов при достаточном объёме кости; опора одиночной коронки, моста или протеза', 'Fehlende Zähne bei ausreichendem Knochenangebot; Verankerung einer Einzelkrone, Brücke oder Prothese', 'Kemik hacminin yeterli olduğu diş eksiklikleri; tek kron, köprü veya protez için destek', 'A panoramic X-ray or CT scan, treatment of cavities and gum disease, and a discussion of current medications with the dentist', 'Panoramski snimak ili CT, liječenje karijesa i bolesti desni, razgovor sa ljekarom o lijekovima koje uzimate', 'Панорамски снимак или ЦТ, лијечење каријеса и болести десни, разговор са љекаром о лијековима које узимате', 'Панорамный снимок или КТ, лечение кариеса и заболеваний дёсен, обсуждение с врачом принимаемых препаратов', 'Panoramaröntgen oder CT, Behandlung von Karies und Zahnfleischerkrankungen, Besprechung der eingenommenen Medikamente mit dem Arzt', 'Panoramik film veya BT, çürük ve diş eti hastalıklarının tedavisi, kullanılan ilaçların hekimle görüşülmesi', 'Swelling and discomfort in the first days are normal; pain that increases after the third day, fever, or opened sutures require a dental examination', 'Oticanje i nelagodnost prvih dana su uobičajeni; bol koja se pojačava poslije trećeg dana, povišena temperatura ili razdvojeni šavovi zahtijevaju pregled kod ljekara', 'Отицање и нелагодност првих дана су уобичајени; бол која се појачава послије трећег дана, повишена температура или раздвојени шавови захтијевају преглед код љекара', 'Отёк и дискомфорт первые дни — обычное явление; боль, которая усиливается после третьего дня, температура или расхождение швов требуют осмотра врача', 'Schwellung und Unbehagen in den ersten Tagen sind normal; Schmerzen, die nach dem dritten Tag zunehmen, Fieber oder aufgegangene Nähte erfordern eine ärztliche Untersuchung', 'İlk günlerde şişlik ve rahatsızlık normaldir; üçüncü günden sonra artan ağrı, ateş veya dikişlerin açılması hekim muayenesi gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = '3d-implant-planning'), 'Implant planning based on a three-dimensional scan: the dentist determines the position, length, and angulation of the implant in advance using dedicated software', 'Planiranje postavljanja implantata na osnovu trodimenzionalnog snimka: ljekar unaprijed određuje položaj, dužinu i nagib implantata u posebnom programu', 'Планирање постављања имплантата на основу тродимензионалног снимка: љекар унапријед одређује положај, дужину и нагиб имплантата у посебном програму', 'Планирование установки имплантатов по трёхмерному снимку: врач заранее определяет положение, длину и наклон имплантата в специальной программе', 'Implantatplanung anhand einer dreidimensionalen Aufnahme: der Arzt legt Position, Länge und Neigung des Implantats vorab in einer speziellen Software fest', 'Üç boyutlu görüntü üzerinden implant planlaması: hekim özel bir programda implantın konumunu, uzunluğunu ve eğimini önceden belirler', 'A CT scan is taken (or an existing one is used), the data is loaded into planning software, the dentist simulates the placement and agrees the plan; takes one visit plus calculation time', 'Radi se CT (ili se koristi postojeći snimak), podaci se učitavaju u program za planiranje, ljekar simulira postavljanje i usaglašava plan; traje jednu posjetu plus vrijeme za obradu', 'Ради се ЦТ (или се користи постојећи снимак), подаци се учитавају у програм за планирање, љекар симулира постављање и усаглашава план; траје једну посјету плус вријеме за обраду', 'Выполняется КТ (или используется уже имеющийся снимок), данные загружаются в программу планирования, врач моделирует установку и согласовывает план; занимает один визит плюс время на расчёт', 'Es wird ein CT angefertigt (oder eine vorhandene Aufnahme genutzt), die Daten werden in die Planungssoftware geladen, der Arzt simuliert das Einsetzen und stimmt den Plan ab; ein Termin plus Auswertungszeit', 'BT çekilir (veya mevcut görüntü kullanılır), veriler planlama programına aktarılır, hekim yerleşimi simüle eder ve planı onaylar; bir seans artı hesaplama süresi', 'Before implant surgery, especially with limited bone volume, proximity to nerves and sinuses, or when several implants are planned at once', 'Prije implantacije, posebno kod malog obima kosti, blizine nerava i sinusa, kao i kada se planira više implantata odjednom', 'Прије имплантације, посебно код малог обима кости, близине нерава и синуса, као и када се планира више имплантата одједном', 'Перед имплантацией, особенно при небольшом объёме кости, близости нервов и пазух, а также при планировании нескольких имплантатов сразу', 'Vor einer Implantation, besonders bei geringem Knochenangebot, Nähe zu Nerven und Kieferhöhlen oder wenn mehrere Implantate gleichzeitig geplant werden', 'İmplant öncesinde, özellikle kemik hacmi az olduğunda, sinir ve sinüslere yakınlıkta veya birkaç implantın birlikte planlandığı durumlarda', 'A current CT scan is required; check with the clinic whether the cost of the scan itself is included in the planning fee', 'Potreban je aktuelan CT snimak; provjeriti u klinici da li je cijena samog snimka uključena u cijenu planiranja', 'Потребан је актуелан ЦТ снимак; провјерити у клиници да ли је цијена самог снимка укључена у цијену планирања', 'Нужен актуальный КТ-снимок; уточнить в клинике, входит ли стоимость самого снимка в цену планирования', 'Eine aktuelle CT-Aufnahme ist erforderlich; in der Praxis klären, ob die Kosten der Aufnahme selbst im Planungspreis enthalten sind', 'Güncel BT görüntüsü gerekir; görüntünün bedelinin planlama fiyatına dahil olup olmadığını klinikten teyit etmek', 'The planning itself is painless and safe; based on its results the dentist may report that there is not enough bone and that grafting is needed — this is part of the treatment plan, not a complication', 'Samo planiranje je bezbolno i bezopasno; na osnovu rezultata ljekar može reći da kosti nema dovoljno i da je potrebna augmentacija — to je dio plana liječenja, a ne komplikacija', 'Само планирање је безболно и безопасно; на основу резултата љекар може рећи да кости нема довољно и да је потребна аугментација — то је дио плана лијечења, а не компликација', 'Само планирование безболезненно и безопасно; по его результатам врач может сообщить, что кости недостаточно и потребуется её наращивание — это часть плана лечения, а не осложнение', 'Die Planung selbst ist schmerzfrei und ungefährlich; aufgrund der Ergebnisse kann der Arzt mitteilen, dass zu wenig Knochen vorhanden ist und ein Knochenaufbau nötig wird — das ist Teil des Behandlungsplans, keine Komplikation', 'Planlamanın kendisi ağrısız ve zararsızdır; sonucuna göre hekim kemiğin yetersiz olduğunu ve greft gerektiğini söyleyebilir — bu tedavi planının parçasıdır, komplikasyon değildir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'surgical-guide-per-implant'), 'A custom guide that is placed over the teeth or bone during surgery and sets the exact drilling direction for the implant', 'Individualni šablon koji se tokom operacije postavlja preko zuba ili kosti i određuje tačan smjer bušenja za implantat', 'Индивидуални шаблон који се током операције поставља преко зуба или кости и одређује тачан смјер бушења за имплантат', 'Индивидуальный шаблон, который надевается на зубы или кость во время операции и задаёт точное направление сверления под имплантат', 'Eine individuelle Schablone, die während der Operation über Zähne oder Knochen gesetzt wird und die exakte Bohrrichtung für das Implantat vorgibt', 'Ameliyat sırasında dişlerin veya kemiğin üzerine yerleştirilen ve implant için delme yönünü tam olarak belirleyen kişiye özel şablon', 'It is fabricated from CT and digital scan data before surgery; during the procedure the guide is seated in the mouth and the surgeon prepares the site through its guiding sleeves', 'Izrađuje se na osnovu CT-a i digitalnog skeniranja prije operacije; tokom implantacije šablon se postavlja u usta, a ljekar priprema ležište kroz njegove vodiče', 'Израђује се на основу ЦТ-а и дигиталног скенирања прије операције; током имплантације шаблон се поставља у уста, а љекар припрема лежиште кроз његове водиче', 'Изготавливается по данным КТ и цифрового сканирования до операции; во время имплантации шаблон устанавливается в полости рта, и врач формирует ложе через его направляющие втулки', 'Sie wird vor dem Eingriff aus CT- und Scandaten hergestellt; während der Implantation wird die Schablone im Mund platziert und der Arzt bereitet das Implantatbett durch ihre Führungshülsen vor', 'Ameliyat öncesinde BT ve dijital tarama verilerinden üretilir; işlem sırasında şablon ağza yerleştirilir ve hekim yuvayı şablonun kılavuz yuvalarından hazırlar', 'Implant placement in difficult anatomy, placement of several implants, and cases where maximum positional accuracy matters', 'Implantacija u složenim uslovima, postavljanje više implantata i slučajevi gdje je važna maksimalna tačnost položaja', 'Имплантација у сложеним условима, постављање више имплантата и случајеви гдје је важна максимална тачност положаја', 'Имплантация в сложных условиях, установка нескольких имплантатов, случаи, где важна максимальная точность положения', 'Implantation bei schwierigen anatomischen Verhältnissen, Einsetzen mehrerer Implantate und Fälle, in denen maximale Positionsgenauigkeit wichtig ist', 'Zorlu anatomide implant uygulaması, birden fazla implant yerleştirilmesi ve konum hassasiyetinin çok önemli olduğu durumlar', 'A CT scan and an impression or scan of the jaw are needed in advance; the price is usually quoted per implant, so the total is worth clarifying', 'Potrebni su CT i otisak ili skan vilice unaprijed; cijena se obično navodi po implantatu, pa je dobro provjeriti ukupan iznos', 'Потребни су ЦТ и отисак или скан вилице унапријед; цијена се обично наводи по имплантату, па је добро провјерити укупан износ', 'Требуются КТ и слепок или скан челюсти заранее; цена обычно указывается за каждый имплантат, стоит уточнить общую сумму', 'CT sowie Abdruck oder Scan des Kiefers sind vorab erforderlich; der Preis wird meist je Implantat angegeben, die Gesamtsumme sollte geklärt werden', 'Önceden BT ve çenenin ölçüsü veya taraması gerekir; fiyat genellikle implant başına verilir, toplam tutarı teyit etmek iyi olur', 'The guide itself carries no complications — it is only an instrument; the dentist reports separately on the course of surgery and healing', 'Sam šablon nema svoje komplikacije — on je samo alat; o toku operacije i zarastanja ljekar obavještava posebno', 'Сам шаблон нема своје компликације — он је само алат; о току операције и зарастања љекар обавјештава посебно', 'Шаблон не имеет собственных осложнений — он лишь инструмент; о нюансах хода операции и заживления врач сообщает отдельно', 'Die Schablone selbst hat keine eigenen Komplikationen — sie ist nur ein Hilfsmittel; über Verlauf der Operation und Heilung informiert der Arzt separat', 'Şablonun kendine ait komplikasyonu yoktur — yalnızca bir araçtır; ameliyatın ve iyileşmenin seyri hakkında hekim ayrıca bilgi verir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'all-on-4-implant-prosthesis-nobel'), 'A full-jaw prosthesis fixed on four Nobel Biocare implants placed at an angle to make use of the available bone', 'Totalna proteza vilice pričvršćena na četiri implantata Nobel Biocare, postavljena pod uglom radi oslonca u raspoloživoj kosti', 'Тотална протеза вилице причвршћена на четири имплантата Nobel Biocare, постављена под углом ради ослонца у расположивој кости', 'Полный протез челюсти, закреплённый на четырёх имплантатах Nobel Biocare, установленных под углом для опоры в доступной кости', 'Eine Vollprothese für einen Kiefer, die auf vier Nobel-Biocare-Implantaten befestigt ist, die geneigt eingesetzt werden, um den vorhandenen Knochen zu nutzen', 'Mevcut kemikten yararlanmak için açılı yerleştirilen dört Nobel Biocare implantı üzerine sabitlenen tam çene protezi', 'A surgical stage (usually local anesthesia with sedation) — placement of four implants and fitting of a temporary prosthesis, often the same day or within a few days; the final prosthesis is made a few months later', 'Hirurška faza (obično lokalna anestezija sa sedacijom) — postavljanje četiri implantata i fiksiranje privremene proteze, često istog ili u prvim danima; trajna proteza se izrađuje nakon nekoliko mjeseci', 'Хируршка фаза (обично локална анестезија са седацијом) — постављање четири имплантата и фиксирање привремене протезе, често истог или у првим данима; трајна протеза се израђује након неколико мјесеци', 'Хирургический этап (обычно под местной анестезией с седацией) — установка четырёх имплантатов и фиксация временного протеза, часто в тот же или ближайшие дни; постоянный протез изготавливают через несколько месяцев', 'Chirurgischer Abschnitt (meist Lokalanästhesie mit Sedierung) — Einsetzen von vier Implantaten und Befestigung einer provisorischen Prothese, oft am selben oder in den nächsten Tagen; die endgültige Prothese wird nach einigen Monaten angefertigt', 'Cerrahi aşama (genellikle sedasyonla birlikte lokal anestezi) — dört implantın yerleştirilmesi ve geçici protezin takılması, sıklıkla aynı gün veya ilk günlerde; kalıcı protez birkaç ay sonra yapılır', 'Complete tooth loss in a jaw, or the need to remove the remaining non-restorable teeth, when a removable denture is not acceptable', 'Potpuni nedostatak zuba u vilici ili potreba da se izvade preostali zubi koji se ne mogu sačuvati, kada pokretna proteza ne zadovoljava', 'Потпуни недостатак зуба у вилици или потреба да се изваде преостали зуби који се не могу сачувати, када покретна протеза не задовољава', 'Полное отсутствие зубов на челюсти или необходимость удалить оставшиеся нежизнеспособные зубы, когда съёмный протез не устраивает', 'Vollständiger Zahnverlust in einem Kiefer oder die Notwendigkeit, die restlichen nicht erhaltungsfähigen Zähne zu entfernen, wenn eine herausnehmbare Prothese nicht in Frage kommt', 'Bir çenede tüm dişlerin eksik olması ya da kurtarılamayan dişlerin çekilmesi gerekmesi ve hareketli protezin tercih edilmemesi', 'A CT scan, assessment of general health and medications, treatment of any oral disease; a soft diet is needed for the first weeks after surgery', 'CT, procjena opšteg stanja i lijekova, sanacija usne duplje; prvih nedjelja nakon operacije potrebna je mekana ishrana', 'ЦТ, процјена општег стања и лијекова, санација усне дупље; првих недјеља након операције потребна је мекана исхрана', 'КТ, оценка общего состояния и препаратов, санация полости рта; после операции первые недели нужна щадящая диета', 'CT, Beurteilung des Allgemeinzustands und der Medikamente, Sanierung der Mundhöhle; in den ersten Wochen nach der Operation ist weiche Kost nötig', 'BT, genel durumun ve ilaçların değerlendirilmesi, ağız sağlığının düzenlenmesi; ameliyattan sonraki ilk haftalarda yumuşak beslenme', 'Facial swelling and bruising during the first week are a normal reaction; increasing pain, fever, mobility of the prosthesis, or marked gum inflammation require an urgent examination', 'Oticanje i modrice na licu prve nedjelje su uobičajena reakcija; bol koja se pojačava, povišena temperatura, klaćenje konstrukcije ili izražena upala desni zahtijevaju hitan pregled', 'Отицање и модрице на лицу прве недјеље су уобичајена реакција; бол која се појачава, повишена температура, клаћење конструкције или изражена упала десни захтијевају хитан преглед', 'Отёк и синяки лица в первую неделю — обычная реакция; усиливающаяся боль, температура, подвижность конструкции или выраженное воспаление дёсен требуют срочного осмотра', 'Schwellung und Blutergüsse im Gesicht in der ersten Woche sind eine normale Reaktion; zunehmende Schmerzen, Fieber, eine beweglich werdende Konstruktion oder eine ausgeprägte Zahnfleischentzündung erfordern eine sofortige Untersuchung', 'İlk hafta yüzde şişlik ve morluk normal tepkidir; artan ağrı, ateş, protezin oynaması veya belirgin diş eti iltihabı acil muayene gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'all-on-6-implant-prosthesis-nobel'), 'A full-jaw prosthesis on six Nobel Biocare implants — a version with more support than the four-implant option', 'Totalna proteza vilice na šest implantata Nobel Biocare — varijanta sa više oslonca nego na četiri', 'Тотална протеза вилице на шест имплантата Nobel Biocare — варијанта са више ослонца него на четири', 'Полный протез челюсти на шести имплантатах Nobel Biocare — вариант с большей опорой, чем на четырёх', 'Eine Vollprothese für einen Kiefer auf sechs Nobel-Biocare-Implantaten — eine Variante mit mehr Abstützung als mit vier', 'Altı Nobel Biocare implantı üzerine yapılan tam çene protezi — dört implantlı seçeneğe göre daha fazla destek sağlar', 'Placement of six implants in one surgery, fitting of a temporary prosthesis, then fabrication of the final restoration after integration; overall treatment usually takes a few months', 'Postavljanje šest implantata u jednoj operaciji, fiksiranje privremene proteze, zatim izrada trajne konstrukcije nakon srastanja; ukupno liječenje obično traje nekoliko mjeseci', 'Постављање шест имплантата у једној операцији, фиксирање привремене протезе, затим израда трајне конструкције након срастања; укупно лијечење обично траје неколико мјесеци', 'Установка шести имплантатов за одну операцию, фиксация временного протеза, затем изготовление постоянной конструкции после приживления; общий срок лечения обычно несколько месяцев', 'Einsetzen von sechs Implantaten in einer Operation, Befestigung einer provisorischen Prothese, danach Anfertigung der endgültigen Konstruktion nach der Einheilung; die Gesamtbehandlung dauert meist einige Monate', 'Tek ameliyatta altı implantın yerleştirilmesi, geçici protezin takılması, kaynaşmadan sonra kalıcı yapının üretimi; tedavi genellikle birkaç ay sürer', 'Complete tooth loss with sufficient bone volume, when distributing the load over more implants is preferable', 'Potpuni nedostatak zuba uz dovoljan obim kosti, kada je bolje rasporediti opterećenje na više implantata', 'Потпуни недостатак зуба уз довољан обим кости, када је боље распоредити оптерећење на више имплантата', 'Полное отсутствие зубов при достаточном объёме кости, когда предпочтительнее распределить нагрузку на большее число имплантатов', 'Vollständiger Zahnverlust bei ausreichendem Knochenangebot, wenn eine Verteilung der Belastung auf mehr Implantate vorzuziehen ist', 'Kemik hacminin yeterli olduğu tam diş eksikliği ve yükün daha fazla implanta dağıtılmasının tercih edildiği durumlar', 'A CT scan, pre-surgical work-up, and a discussion of anesthesia; plan 1-2 days of rest after the surgical stage', 'CT, pregledi prije operacije, razgovor o anesteziji; planirati 1-2 dana odmora nakon hirurške faze', 'ЦТ, прегледи прије операције, разговор о анестезији; планирати 1-2 дана одмора након хируршке фазе', 'КТ, обследование перед операцией, обсуждение анестезии; спланировать 1-2 дня отдыха после хирургического этапа', 'CT, Voruntersuchungen, Besprechung der Anästhesie; 1-2 Ruhetage nach dem chirurgischen Abschnitt einplanen', 'BT, ameliyat öncesi tetkikler, anestezinin görüşülmesi; cerrahi aşamadan sonra 1-2 gün dinlenme planlamak', 'Swelling, bruising, and difficulty chewing in the first days are expected; increasing pain, pus, fever, or a feeling that the prosthesis moves are reasons to contact the clinic urgently', 'Oticanje, modrice i otežano žvakanje prvih dana su očekivani; bol koja se pojačava, gnoj, povišena temperatura ili osjećaj da se proteza klati razlog su za hitan kontakt sa klinikom', 'Отицање, модрице и отежано жвакање првих дана су очекивани; бол која се појачава, гној, повишена температура или осјећај да се протеза клати разлог су за хитан контакт са клиником', 'Отёк, синяки и трудности с жеванием в первые дни ожидаемы; нарастающая боль, гной, температура или ощущение подвижности протеза — повод срочно связаться с клиникой', 'Schwellung, Blutergüsse und Kauschwierigkeiten in den ersten Tagen sind zu erwarten; zunehmende Schmerzen, Eiter, Fieber oder das Gefühl, dass sich die Prothese bewegt, sind ein Grund, die Praxis sofort zu kontaktieren', 'İlk günlerde şişlik, morluk ve çiğnemede güçlük beklenir; artan ağrı, iltihap akıntısı, ateş veya protezin oynadığı hissi kliniğe acilen başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'all-on-4-implant-prosthesis-straumann'), 'A full-jaw prosthesis on four Straumann implants', 'Totalna proteza vilice na četiri implantata Straumann', 'Тотална протеза вилице на четири имплантата Straumann', 'Полный протез челюсти на четырёх имплантатах Straumann', 'Eine Vollprothese für einen Kiefer auf vier Straumann-Implantaten', 'Dört Straumann implantı üzerine yapılan tam çene protezi', 'A surgical stage with placement of four implants and a temporary prosthesis, then the final restoration after integration; the timing of the stages is set by the dentist based on implant stability', 'Hirurška faza sa postavljanjem četiri implantata i privremenom protezom, zatim trajna konstrukcija nakon srastanja; rokove faza određuje ljekar prema stabilnosti implantata', 'Хируршка фаза са постављањем четири имплантата и привременом протезом, затим трајна конструкција након срастања; рокове фаза одређује љекар према стабилности имплантата', 'Хирургический этап с установкой четырёх имплантатов и временным протезом, затем постоянная конструкция после приживления; сроки этапов определяет врач по стабильности имплантатов', 'Chirurgischer Abschnitt mit Einsetzen von vier Implantaten und einer provisorischen Prothese, danach die endgültige Konstruktion nach der Einheilung; die Zeitpunkte legt der Arzt anhand der Implantatstabilität fest', 'Dört implantın yerleştirildiği ve geçici protezin takıldığı cerrahi aşama, ardından kaynaşmadan sonra kalıcı yapı; aşamaların zamanlamasını hekim implant stabilitesine göre belirler', 'Complete tooth loss in a jaw and a wish for a fixed solution instead of a removable denture', 'Potpuni nedostatak zuba u vilici i želja za fiksnim rješenjem umjesto pokretne proteze', 'Потпуни недостатак зуба у вилици и жеља за фиксним рјешењем умјесто покретне протезе', 'Полное отсутствие зубов на челюсти, желание получить несъёмное решение вместо съёмного протеза', 'Vollständiger Zahnverlust in einem Kiefer und der Wunsch nach einer festsitzenden Lösung anstelle einer herausnehmbaren Prothese', 'Bir çenede tüm dişlerin eksik olması ve hareketli protez yerine sabit çözüm istenmesi', 'A CT scan, assessment of health status and medications, treatment of any oral disease; a soft diet and no smoking after surgery', 'CT, procjena zdravstvenog stanja i lijekova, sanacija usne duplje; nakon operacije mekana ishrana i prestanak pušenja', 'ЦТ, процјена здравственог стања и лијекова, санација усне дупље; након операције мекана исхрана и престанак пушења', 'КТ, оценка состояния здоровья и принимаемых препаратов, санация полости рта; после операции — щадящая диета и отказ от курения', 'CT, Beurteilung des Gesundheitszustands und der Medikamente, Sanierung der Mundhöhle; nach der Operation weiche Kost und Rauchverzicht', 'BT, sağlık durumunun ve ilaçların değerlendirilmesi, ağız sağlığının düzenlenmesi; ameliyattan sonra yumuşak beslenme ve sigaranın bırakılması', 'Swelling and soreness are expected in the first days; ongoing bleeding, increasing pain, or fever is a reason to contact the dentist urgently', 'Prvih dana su očekivani oticanje i bol; krvarenje koje ne prestaje, bol koja se pojačava ili povišena temperatura razlog su za hitno obraćanje ljekaru', 'Првих дана су очекивани отицање и бол; крварење које не престаје, бол која се појачава или повишена температура разлог су за хитно обраћање љекару', 'Первые дни ожидаемы отёк и болезненность; сохраняющееся кровотечение, нарастающая боль или температура — повод срочно обратиться к врачу', 'In den ersten Tagen sind Schwellung und Schmerzen zu erwarten; anhaltende Blutung, zunehmende Schmerzen oder Fieber sind ein Grund, sofort den Arzt aufzusuchen', 'İlk günlerde şişlik ve ağrı beklenir; durmayan kanama, artan ağrı veya ateş acilen hekime başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'all-on-4-metal-ceramic-titanium'), 'A definitive prosthesis on four implants with a titanium framework and ceramic veneering', 'Trajna proteza na četiri implantata sa titanijumskim skeletom i keramičkom fasetom', 'Трајна протеза на четири имплантата са титанијумским скелетом и керамичком фасетом', 'Постоянный протез на четырёх имплантатах с титановым каркасом и керамической облицовкой', 'Eine definitive Prothese auf vier Implantaten mit Titangerüst und keramischer Verblendung', 'Titanyum alt yapılı ve seramik kaplamalı, dört implant üzerine kalıcı protez', 'Made after the implants have integrated: impressions or scans, milling of the titanium bar, ceramic layering, try-ins, and screwing onto the implants; usually several visits over 3-6 weeks', 'Izrađuje se nakon srastanja implantata: otisci ili skeniranje, frezovanje titanijumske grede, nanošenje keramike, probe i pričvršćivanje na implantate; obično nekoliko posjeta tokom 3-6 nedjelja', 'Израђује се након срастања имплантата: отисци или скенирање, фрезовање титанијумске греде, наношење керамике, пробе и причвршћивање на имплантате; обично неколико посјета током 3-6 недјеља', 'Изготавливается после приживления имплантатов: слепки или сканирование, фрезерование титановой балки, нанесение керамики, примерки и прикручивание к имплантатам; обычно несколько визитов в течение 3-6 недель', 'Wird nach der Einheilung der Implantate angefertigt: Abdrücke oder Scans, Fräsen des Titanstegs, keramische Verblendung, Anproben und Verschrauben auf den Implantaten; in der Regel mehrere Termine über 3-6 Wochen', 'İmplantlar kaynaştıktan sonra yapılır: ölçü veya tarama, titanyum barın kazınması, seramiğin işlenmesi, provalar ve implantlara vidalanması; genellikle 3-6 hafta içinde birkaç seans', 'The final stage of All on 4 treatment, when a strong fixed full-jaw restoration is needed', 'Završna faza liječenja po protokolu All on 4, kada je potrebna čvrsta fiksna konstrukcija za cijelu vilicu', 'Завршна фаза лијечења по протоколу All on 4, када је потребна чврста фиксна конструкција за цијелу вилицу', 'Завершающий этап лечения по протоколу All on 4, когда нужна прочная несъёмная конструкция на всю челюсть', 'Abschluss der Behandlung nach dem All-on-4-Protokoll, wenn eine stabile festsitzende Versorgung des gesamten Kiefers gewünscht ist', 'All on 4 protokolünün son aşaması; tüm çene için dayanıklı sabit yapı gerektiğinde', 'The implants must be stable; allow enough time for the try-in appointments — the bite and appearance depend on them', 'Implantati treba da budu stabilni; za probe treba doći bez žurbe — od njih zavise zagriz i izgled', 'Имплантати треба да буду стабилни; за пробе треба доћи без журбе — од њих зависе загриз и изглед', 'Имплантаты должны быть стабильны; на примерки нужно приходить без спешки — от них зависят прикус и внешний вид', 'Die Implantate müssen stabil sein; für die Anproben ausreichend Zeit einplanen — davon hängen Biss und Aussehen ab', 'İmplantların stabil olması; prova seanslarına acele etmeden gelmek — kapanış ve görünüm bunlara bağlıdır', 'Getting used to the new bite takes 1-2 weeks; pain around an implant, gum inflammation, or a feeling that the prosthesis moves require a dental examination', 'Privikavanje na novi zagriz traje 1-2 nedjelje; bol u području implantata, upala desni ili osjećaj da je konstrukcija „pokretna“ zahtijevaju pregled kod ljekara', 'Привикавање на нови загриз траје 1-2 недјеље; бол у подручју имплантата, упала десни или осјећај да је конструкција „покретна“ захтијевају преглед код љекара', 'Привыкание к новому прикусу занимает 1-2 недели; боль в области имплантата, воспаление дёсен или ощущение, что конструкция «подвижна», требуют осмотра врача', 'Die Eingewöhnung an den neuen Biss dauert 1-2 Wochen; Schmerzen im Implantatbereich, eine Zahnfleischentzündung oder das Gefühl, dass die Konstruktion beweglich ist, erfordern eine ärztliche Untersuchung', 'Yeni kapanışa alışma 1-2 hafta sürer; implant bölgesinde ağrı, diş eti iltihabı veya yapının "oynadığı" hissi hekim muayenesi gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'all-on-4-zirconia'), 'A definitive zirconia prosthesis on four implants — a one-piece design with no metal in the framework', 'Trajna cirkonijumska proteza na četiri implantata — jedinstvena konstrukcija bez metala u skeletu', 'Трајна цирконијумска протеза на четири имплантата — јединствена конструкција без метала у скелету', 'Постоянный циркониевый протез на четырёх имплантатах — цельная конструкция без металла в каркасе', 'Eine definitive Zirkonprothese auf vier Implantaten — eine einteilige Konstruktion ohne Metall im Gerüst', 'Dört implant üzerine kalıcı zirkonyum protez — alt yapısında metal bulunmayan tek parça yapı', 'After the implants have integrated: digital scanning, milling of the zirconia structure, try-ins, and screwing onto the implants; usually several visits over 3-6 weeks', 'Nakon srastanja implantata: digitalno skeniranje, frezovanje cirkonijumske konstrukcije, probe i pričvršćivanje na implantate; obično nekoliko posjeta tokom 3-6 nedjelja', 'Након срастања имплантата: дигитално скенирање, фрезовање цирконијумске конструкције, пробе и причвршћивање на имплантате; обично неколико посјета током 3-6 недјеља', 'После приживления имплантатов: цифровое сканирование, фрезерование циркониевой конструкции, примерки и прикручивание к имплантатам; обычно несколько визитов в течение 3-6 недель', 'Nach der Einheilung der Implantate: digitales Scannen, Fräsen der Zirkonkonstruktion, Anproben und Verschrauben auf den Implantaten; in der Regel mehrere Termine über 3-6 Wochen', 'İmplantlar kaynaştıktan sonra: dijital tarama, zirkonyum yapının kazınması, provalar ve implantlara vidalanması; genellikle 3-6 hafta içinde birkaç seans', 'Completion of All on 4 treatment when aesthetics and a metal-free design matter; replacement of a temporary prosthesis with the final one', 'Završetak liječenja All on 4 kada su važni estetika i odsustvo metala; zamjena privremene proteze trajnom', 'Завршетак лијечења All on 4 када су важни естетика и одсуство метала; замјена привремене протезе трајном', 'Завершение лечения All on 4, когда важны эстетика и отсутствие металла; замена временного протеза на постоянный', 'Abschluss der All-on-4-Behandlung, wenn Ästhetik und Metallfreiheit wichtig sind; Ersatz der provisorischen durch die endgültige Prothese', 'Estetiğin ve metalsiz yapının önemli olduğu All on 4 tedavisinin tamamlanması; geçici protezin kalıcı protezle değiştirilmesi', 'Stable implants and healthy gums; discuss the shape and color of the teeth with the dentist in advance', 'Stabilni implantati i zdrave desni; unaprijed sa ljekarom razgovarati o obliku i boji zuba', 'Стабилни имплантати и здраве десни; унапријед са љекаром разговарати о облику и боји зуба', 'Стабильные имплантаты и здоровые дёсны; заранее обсудить с врачом форму и цвет зубов', 'Stabile Implantate und gesundes Zahnfleisch; Form und Farbe der Zähne vorab mit dem Arzt besprechen', 'Stabil implantlar ve sağlıklı diş eti; dişlerin şekli ve renginin hekimle önceden görüşülmesi', 'Mild discomfort during adaptation is normal; chipping of zirconia is rare but needs examination, as do pain or inflammation around the implants', 'Blaga nelagodnost tokom privikavanja je normalna; okrzavanje cirkonijuma je rijetko, ali zahtijeva pregled, kao i bol ili upala oko implantata', 'Блага нелагодност током привикавања је нормална; окрзавање цирконијума је ријетко, али захтијева преглед, као и бол или упала око имплантата', 'Небольшой дискомфорт при привыкании — норма; сколы циркония редки, но требуют осмотра, как и боль или воспаление вокруг имплантатов', 'Leichtes Unbehagen während der Eingewöhnung ist normal; Abplatzungen am Zirkon sind selten, erfordern aber eine Kontrolle, ebenso Schmerzen oder Entzündungen um die Implantate', 'Alışma sürecinde hafif rahatsızlık normaldir; zirkonyumda kırılma seyrektir ancak muayene gerektirir, implant çevresinde ağrı veya iltihap da öyle')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'all-on-6-zirconia'), 'A definitive zirconia prosthesis on six implants for full restoration of a jaw', 'Trajna cirkonijumska proteza na šest implantata za potpunu obnovu zuba jedne vilice', 'Трајна цирконијумска протеза на шест имплантата за потпуну обнову зуба једне вилице', 'Постоянный циркониевый протез на шести имплантатах для полного восстановления зубов челюсти', 'Eine definitive Zirkonprothese auf sechs Implantaten zur vollständigen Versorgung eines Kiefers', 'Bir çenenin tamamının restorasyonu için altı implant üzerine kalıcı zirkonyum protez', 'After the six implants have integrated: scanning, milling of the zirconia structure, try-ins, and fixation with screws; usually several visits over 3-6 weeks', 'Nakon srastanja šest implantata radi se skeniranje, frezovanje cirkonijumske konstrukcije, probe i pričvršćivanje vijcima; obično nekoliko posjeta tokom 3-6 nedjelja', 'Након срастања шест имплантата ради се скенирање, фрезовање цирконијумске конструкције, пробе и причвршћивање вијцима; обично неколико посјета током 3-6 недјеља', 'После приживления шести имплантатов выполняется сканирование, фрезерование циркониевой конструкции, примерки и фиксация винтами; обычно несколько визитов в течение 3-6 недель', 'Nach der Einheilung der sechs Implantate: Scannen, Fräsen der Zirkonkonstruktion, Anproben und Verschrauben; in der Regel mehrere Termine über 3-6 Wochen', 'Altı implant kaynaştıktan sonra tarama, zirkonyum yapının kazınması, provalar ve vidalarla sabitleme; genellikle 3-6 hafta içinde birkaç seans', 'Complete tooth loss when a six-implant protocol has been chosen for better load distribution', 'Potpuni nedostatak zuba kada je izabran protokol sa šest implantata radi boljeg raspoređivanja opterećenja', 'Потпуни недостатак зуба када је изабран протокол са шест имплантата ради бољег распоређивања оптерећења', 'Полное отсутствие зубов, когда выбран протокол с шестью имплантатами для лучшего распределения нагрузки', 'Vollständiger Zahnverlust, wenn ein Protokoll mit sechs Implantaten zur besseren Lastverteilung gewählt wurde', 'Yükün daha iyi dağıtılması için altı implantlı protokolün seçildiği tam diş eksikliği', 'Confirmed implant stability and healthy gums; the bite and appearance are checked at the try-in appointments', 'Potvrđena stabilnost implantata i zdrave desni; na probama se provjeravaju zagriz i izgled', 'Потврђена стабилност имплантата и здраве десни; на пробама се провјеравају загриз и изглед', 'Подтверждённая стабильность имплантатов, санированные дёсны; на примерках проверяются прикус и внешний вид', 'Bestätigte Implantatstabilität und gesundes Zahnfleisch; bei den Anproben werden Biss und Aussehen überprüft', 'İmplant stabilitesinin doğrulanmış olması ve diş etlerinin sağlıklı olması; provalarda kapanış ve görünüm kontrol edilir', 'Unfamiliar sensations when chewing and speaking are possible in the first 1-2 weeks; pain, bleeding gums, or a feeling that the prosthesis moves are reasons for an examination', 'Prvih 1-2 nedjelje mogući su neobični osjećaji pri žvakanju i govoru; bol, krvarenje desni ili osjećaj da se konstrukcija klati razlog su za pregled', 'Првих 1-2 недјеље могући су необични осјећаји при жвакању и говору; бол, крварење десни или осјећај да се конструкција клати разлог су за преглед', 'Первые 1-2 недели возможны непривычные ощущения при жевании и речи; боль, кровоточивость дёсен или ощущение подвижности конструкции — повод для осмотра', 'In den ersten 1-2 Wochen sind ungewohnte Empfindungen beim Kauen und Sprechen möglich; Schmerzen, Zahnfleischblutungen oder das Gefühl, dass sich die Konstruktion bewegt, sind ein Grund für eine Kontrolle', 'İlk 1-2 hafta çiğneme ve konuşmada alışılmadık hisler olabilir; ağrı, diş eti kanaması veya yapının oynadığı hissi muayene gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'all-on-6-metal-ceramic'), 'A definitive metal-ceramic prosthesis on six implants — a metal framework with ceramic veneering for the whole jaw', 'Trajna metalokeramička proteza na šest implantata — metalni skelet sa keramičkom fasetom za cijelu vilicu', 'Трајна металокерамичка протеза на шест имплантата — метални скелет са керамичком фасетом за цијелу вилицу', 'Постоянный металлокерамический протез на шести имплантатах — металлический каркас с керамической облицовкой на всю челюсть', 'Eine definitive Metallkeramikprothese auf sechs Implantaten — ein Metallgerüst mit keramischer Verblendung für den gesamten Kiefer', 'Altı implant üzerine kalıcı metal destekli seramik protez — tüm çene için metal alt yapı ve seramik kaplama', 'After the implants have integrated: impressions, fabrication of the framework and veneering in the laboratory, try-ins, and screwing onto the implants; usually several visits over 3-6 weeks', 'Nakon srastanja implantata: otisci, izrada skeleta i fasete u laboratoriji, probe i pričvršćivanje na implantate; obično nekoliko posjeta tokom 3-6 nedjelja', 'Након срастања имплантата: отисци, израда скелета и фасете у лабораторији, пробе и причвршћивање на имплантате; обично неколико посјета током 3-6 недјеља', 'После приживления имплантатов: слепки, изготовление каркаса и облицовки в лаборатории, примерки и прикручивание к имплантатам; обычно несколько визитов в течение 3-6 недель', 'Nach der Einheilung der Implantate: Abdrücke, Anfertigung von Gerüst und Verblendung im Labor, Anproben und Verschrauben auf den Implantaten; in der Regel mehrere Termine über 3-6 Wochen', 'İmplantlar kaynaştıktan sonra: ölçüler, laboratuvarda alt yapı ve kaplamanın üretimi, provalar ve implantlara vidalanması; genellikle 3-6 hafta içinde birkaç seans', 'Full restoration of a jaw on six implants, when a more affordable framework option is preferred', 'Potpuna obnova zuba vilice na šest implantata, kada se preferira pristupačnija varijanta skeleta', 'Потпуна обнова зуба вилице на шест имплантата, када се преферира приступачнија варијанта скелета', 'Полное восстановление зубов челюсти на шести имплантатах, когда предпочтителен более доступный вариант каркаса', 'Vollständige Versorgung eines Kiefers auf sechs Implantaten, wenn eine preisgünstigere Gerüstvariante bevorzugt wird', 'Daha ekonomik alt yapı seçeneğinin tercih edildiği, altı implant üzerine tam çene restorasyonu', 'Stable implants and healthy gums; report any known metal allergy', 'Stabilni implantati i zdrave desni; napomenuti poznatu alergiju na metale', 'Стабилни имплантати и здраве десни; напоменути познату алергију на метале', 'Стабильные имплантаты, здоровые дёсны; сообщить об известной аллергии на металлы', 'Stabile Implantate und gesundes Zahnfleisch; eine bekannte Metallallergie mitteilen', 'Stabil implantlar ve sağlıklı diş etleri; bilinen metal alerjisinin bildirilmesi', 'Adaptation to the prosthesis takes 1-2 weeks; chipping of the ceramic veneer, pain, or inflammation around an implant require a dental examination', 'Privikavanje na konstrukciju traje 1-2 nedjelje; okrzavanje keramičke fasete, bol ili upala oko implantata zahtijevaju pregled kod ljekara', 'Привикавање на конструкцију траје 1-2 недјеље; окрзавање керамичке фасете, бол или упала око имплантата захтијевају преглед код љекара', 'Привыкание к конструкции занимает 1-2 недели; скол керамической облицовки, боль или воспаление вокруг имплантата требуют осмотра врача', 'Die Eingewöhnung dauert 1-2 Wochen; Abplatzungen der keramischen Verblendung, Schmerzen oder Entzündungen um ein Implantat erfordern eine ärztliche Untersuchung', 'Yapıya alışma 1-2 hafta sürer; seramik kaplamada kırılma, ağrı veya implant çevresinde iltihap hekim muayenesi gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'self-ligating-braces-metal-per-jaw'), 'A metal self-ligating bracket system for one jaw: the archwire is held by a clip built into the bracket, without elastic ligatures', 'Metalni samoligirajući fiksni aparat za jednu vilicu: žica se drži kopčom na samoj bravici, bez gumenih ligatura', 'Метални самолигирајући фиксни апарат за једну вилицу: жица се држи копчом на самој бравици, без гумених лигатура', 'Металлическая самолигирующая брекет-система на одну челюсть: дуга удерживается защёлкой самого брекета, без резиновых лигатур', 'Eine selbstligierende Metallbracket-Apparatur für einen Kiefer: der Bogen wird durch einen Clip am Bracket gehalten, ohne Gummiligaturen', 'Tek çene için metal kendinden bağlamalı braket sistemi: tel, lastik ligatür olmadan braketin kendi kapağıyla tutulur', 'The brackets are bonded to the teeth and the archwire is inserted; placement takes about an hour, and follow-up visits for wire changes are usually less frequent than with a conventional system — the intervals are set by the orthodontist', 'Bravice se lijepe na zube i postavlja se žica; postavljanje traje oko sat vremena, a posjete za zamjenu žice obično su rjeđe nego kod klasičnog aparata — intervale određuje ortodont', 'Бравице се лијепе на зубе и поставља се жица; постављање траје око сат времена, а посјете за замјену жице обично су рјеђе него код класичног апарата — интервале одређује ортодонт', 'Брекеты приклеивают к зубам и вставляют дугу; установка занимает около часа, далее визиты для смены дуг обычно реже, чем при классической системе — интервалы определяет ортодонт', 'Die Brackets werden auf die Zähne geklebt und der Bogen eingesetzt; das Einsetzen dauert etwa eine Stunde, Termine zum Bogenwechsel sind meist seltener als bei einer klassischen Apparatur — die Abstände legt der Kieferorthopäde fest', 'Braketler dişlere yapıştırılır ve tel takılır; takma işlemi yaklaşık bir saat sürer, tel değişimi için kontroller klasik sisteme göre genellikle daha seyrektir — aralıkları ortodontist belirler', 'Crowded teeth, malocclusion, gaps between teeth; convenient when fewer adjustment visits are preferred', 'Zbijenost zuba, nepravilan zagriz, razmaci između zuba; praktično kada se želi manje kontrolnih posjeta', 'Збијеност зуба, неправилан загриз, размаци између зуба; практично када се жели мање контролних посјета', 'Скученность зубов, неправильный прикус, промежутки между зубами; удобно, когда хочется реже приходить на коррекции', 'Zahnengstand, Fehlbiss, Zahnlücken; praktisch, wenn möglichst wenige Kontrolltermine gewünscht sind', 'Diş sıkışıklığı, kapanış bozukluğu, dişler arası boşluklar; daha az kontrol seansı istendiğinde uygundur', 'Treatment of cavities and a professional cleaning before placement; orthodontic diagnostics with X-rays', 'Liječenje karijesa i profesionalno čišćenje prije postavljanja; ortodontska dijagnostika sa snimcima', 'Лијечење каријеса и професионално чишћење прије постављања; ортодонтска дијагностика са снимцима', 'Лечение кариеса и профессиональная чистка до установки; ортодонтическая диагностика со снимками', 'Behandlung von Karies und professionelle Zahnreinigung vor dem Einsetzen; kieferorthopädische Diagnostik mit Röntgenaufnahmen', 'Takmadan önce çürük tedavisi ve profesyonel temizlik; röntgenlerle ortodontik tanı', 'Tooth soreness in the first days after placement and after each wire change is normal; a debonded bracket, a protruding wire end, or an injured mucosa are reasons to book an unscheduled orthodontic visit', 'Bolna osjetljivost zuba prvih dana nakon postavljanja i nakon zamjene žice je normalna; odlijepljena bravica, izbočen kraj žice ili povrijeđena sluznica razlog su za vanredni termin kod ortodonta', 'Болна осјетљивост зуба првих дана након постављања и након замјене жице је нормална; одлијепљена бравица, избочен крај жице или повријеђена слузница разлог су за ванредни термин код ортодонта', 'Болезненность зубов в первые дни после установки и после смены дуги — норма; отклеившийся брекет, торчащий конец дуги или травма слизистой — повод записаться к ортодонту вне графика', 'Druckempfindlichkeit der Zähne in den ersten Tagen nach dem Einsetzen und nach jedem Bogenwechsel ist normal; ein gelöstes Bracket, ein hervorstehendes Bogenende oder eine verletzte Schleimhaut sind ein Grund für einen Termin außerhalb des Plans', 'Takma sonrası ilk günlerde ve her tel değişiminden sonra diş hassasiyeti normaldir; yerinden çıkan braket, çıkıntı yapan tel ucu veya yaralanan mukoza plan dışı randevu gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'self-ligating-braces-ceramic-per-jaw'), 'A ceramic self-ligating bracket system for one jaw — less visible than metal, with the archwire held by the bracket''s clip', 'Keramički samoligirajući fiksni aparat za jednu vilicu — manje je vidljiv od metalnog, a žicu drži kopča na bravici', 'Керамички самолигирајући фиксни апарат за једну вилицу — мање је видљив од металног, а жицу држи копча на бравици', 'Керамическая самолигирующая брекет-система на одну челюсть — менее заметна, чем металлическая, дуга фиксируется защёлкой брекета', 'Eine selbstligierende Keramikbracket-Apparatur für einen Kiefer — weniger sichtbar als Metall, der Bogen wird vom Clip des Brackets gehalten', 'Tek çene için seramik kendinden bağlamalı braket sistemi — metale göre daha az görünür, tel braketin kapağıyla tutulur', 'Bonding the ceramic brackets and inserting the archwire (about an hour), then periodic visits for wire changes throughout treatment', 'Lijepljenje keramičkih bravica i postavljanje žice (oko sat vremena), zatim periodične posjete radi zamjene žice tokom liječenja', 'Лијепљење керамичких бравица и постављање жице (око сат времена), затим периодичне посјете ради замјене жице током лијечења', 'Приклеивание керамических брекетов и установка дуги (около часа), затем периодические визиты для смены дуг на протяжении лечения', 'Aufkleben der Keramikbrackets und Einsetzen des Bogens (etwa eine Stunde), danach regelmäßige Termine zum Bogenwechsel während der Behandlung', 'Seramik braketlerin yapıştırılması ve telin takılması (yaklaşık bir saat), ardından tedavi boyunca tel değişimi için düzenli kontroller', 'Correcting the bite and tooth position when an inconspicuous appliance matters', 'Ispravljanje zagriza i položaja zuba kada je važno da aparat bude neupadljiv', 'Исправљање загриза и положаја зуба када је важно да апарат буде неупадљив', 'Исправление прикуса и положения зубов, когда важна незаметность конструкции', 'Korrektur von Biss und Zahnstellung, wenn eine unauffällige Apparatur wichtig ist', 'Aparatın görünmemesinin önemli olduğu kapanış ve diş konumu düzeltmeleri', 'Oral health treatment and a professional cleaning; note that ceramic brackets are bulkier than metal ones and require care with hard foods', 'Sanacija usne duplje i profesionalno čišćenje; imati u vidu da su keramičke bravice krupnije od metalnih i zahtijevaju pažnju sa tvrdom hranom', 'Санација усне дупље и професионално чишћење; имати у виду да су керамичке бравице крупније од металних и захтијевају пажњу са тврдом храном', 'Санация полости рта и профессиональная чистка; учесть, что керамические брекеты крупнее металлических и требуют аккуратности с твёрдой пищей', 'Sanierung der Mundhöhle und professionelle Zahnreinigung; Keramikbrackets sind größer als Metallbrackets und erfordern Vorsicht bei harter Nahrung', 'Ağız sağlığının düzenlenmesi ve profesyonel temizlik; seramik braketlerin metale göre daha hacimli olduğunu ve sert gıdalarda dikkat gerektirdiğini bilmek', 'Discomfort in the first days is expected; a chipped or debonded bracket, as well as staining of the components from coffee and pigmented foods, are reasons to see the orthodontist', 'Nelagodnost prvih dana je očekivana; okrznuta ili odlijepljena bravica, kao i prebojavanje elemenata od kafe i hrane koja boji, razlog su za posjetu ortodontu', 'Нелагодност првих дана је очекивана; окрзнута или одлијепљена бравица, као и пребојавање елемената од кафе и хране која боји, разлог су за посјету ортодонту', 'Дискомфорт в первые дни ожидаем; скол или отклеивание брекета, а также окрашивание элементов от кофе и красящих продуктов — повод обратиться к ортодонту', 'Unbehagen in den ersten Tagen ist zu erwarten; ein abgeplatztes oder gelöstes Bracket sowie Verfärbungen der Bauteile durch Kaffee und farbintensive Lebensmittel sind ein Grund für einen Besuch beim Kieferorthopäden', 'İlk günlerde rahatsızlık beklenir; braketin kırılması veya yerinden çıkması, ayrıca kahve ve renklendirici gıdalarla parçaların boyanması ortodontiste başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'fixed-braces-ceramic-or-composite-per-jaw'), 'A fixed bracket appliance for one jaw made of light-colored ceramic or composite brackets', 'Fiksni aparat za jednu vilicu od keramičkih ili kompozitnih bravica svjetlije nijanse', 'Фиксни апарат за једну вилицу од керамичких или композитних бравица свјетлије нијансе', 'Несъёмная брекет-система на одну челюсть из керамических или композитных брекетов светлого оттенка', 'Eine festsitzende Apparatur für einen Kiefer aus hellen Keramik- oder Kunststoffbrackets', 'Açık renkli seramik veya kompozit braketlerden oluşan, tek çeneye uygulanan sabit ortodontik sistem', 'The brackets are bonded to the teeth with adhesive and the archwire is placed with ligatures; placement takes about an hour, followed by adjustment visits roughly monthly', 'Bravice se lijepe na zube adhezivom i postavlja se žica sa ligaturama; postavljanje traje oko sat vremena, a zatim slijede kontrole otprilike jednom mjesečno', 'Бравице се лијепе на зубе адхезивом и поставља се жица са лигатурама; постављање траје око сат времена, а затим слиједе контроле отприлике једном мјесечно', 'Брекеты фиксируют на зубы адгезивом и устанавливают дугу с лигатурами; установка около часа, затем визиты для коррекции примерно раз в месяц', 'Die Brackets werden mit Adhäsiv auf die Zähne geklebt und der Bogen mit Ligaturen eingesetzt; das Einsetzen dauert etwa eine Stunde, danach folgen Kontrolltermine etwa monatlich', 'Braketler adezivle dişlere yapıştırılır ve tel ligatürlerle takılır; takma yaklaşık bir saat sürer, ardından yaklaşık ayda bir kontrol seansları yapılır', 'Crowding, gaps, and malocclusion, when less visible brackets are preferred', 'Zbijenost, razmaci, nepravilan zagriz, kada se preferiraju manje vidljive bravice', 'Збијеност, размаци, неправилан загриз, када се преферирају мање видљиве бравице', 'Скученность, промежутки, неправильный прикус, когда предпочтительны менее заметные брекеты', 'Engstand, Lücken, Fehlbiss, wenn weniger sichtbare Brackets bevorzugt werden', 'Sıkışıklık, boşluklar, kapanış bozukluğu; daha az görünür braketlerin tercih edildiği durumlar', 'Oral health treatment is required; the orthodontist takes X-rays and impressions for the treatment plan', 'Obavezna je sanacija usne duplje; ortodont pravi snimke i otiske za plan liječenja', 'Обавезна је санација усне дупље; ортодонт прави снимке и отиске за план лијечења', 'Обязательна санация полости рта; ортодонт делает снимки и слепки для плана лечения', 'Eine Sanierung der Mundhöhle ist erforderlich; der Kieferorthopäde erstellt Röntgenbilder und Abdrücke für den Behandlungsplan', 'Ağız sağlığının düzenlenmesi zorunludur; ortodontist tedavi planı için röntgen ve ölçü alır', 'Soreness and rubbing in the first days are normal; a debonded bracket or darkening of composite components over time are discussed at an orthodontic visit', 'Bolna osjetljivost i žuljanje prvih dana su uobičajeni; odlijepljena bravica ili potamnjenje kompozitnih elemenata s vremenom razmatraju se na kontroli kod ortodonta', 'Болна осјетљивост и жуљање првих дана су уобичајени; одлијепљена бравица или потамњење композитних елемената с временом разматрају се на контроли код ортодонта', 'Болезненность и натирание в первые дни — обычное явление; отклеившийся брекет или потемнение композитных элементов со временем обсуждаются на визите к ортодонту', 'Druckempfindlichkeit und Reiben in den ersten Tagen sind normal; ein gelöstes Bracket oder eine Verdunklung der Kunststoffteile im Laufe der Zeit werden beim Kontrolltermin besprochen', 'İlk günlerde hassasiyet ve tahriş normaldir; yerinden çıkan braket veya kompozit parçaların zamanla koyulaşması kontrol seansında değerlendirilir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'fixed-braces-sapphire-per-jaw'), 'A bracket appliance for one jaw made of transparent sapphire brackets that are barely noticeable on the teeth', 'Fiksni aparat za jednu vilicu od prozirnih safirnih bravica koje su na zubima gotovo neprimjetne', 'Фиксни апарат за једну вилицу од прозирних сафирних бравица које су на зубима готово непримјетне', 'Брекет-система на одну челюсть из прозрачных сапфировых брекетов, которые почти незаметны на зубах', 'Eine Apparatur für einen Kiefer aus transparenten Saphirbrackets, die auf den Zähnen kaum auffallen', 'Dişler üzerinde neredeyse fark edilmeyen şeffaf safir braketlerden oluşan, tek çeneye uygulanan sistem', 'Bonding the sapphire brackets and inserting the archwire (about an hour), then regular adjustment visits throughout treatment', 'Lijepljenje safirnih bravica i postavljanje žice (oko sat vremena), zatim redovne kontrole tokom cijelog liječenja', 'Лијепљење сафирних бравица и постављање жице (око сат времена), затим редовне контроле током цијелог лијечења', 'Фиксация сапфировых брекетов и установка дуги (около часа), далее регулярные визиты для коррекции на протяжении всего лечения', 'Aufkleben der Saphirbrackets und Einsetzen des Bogens (etwa eine Stunde), danach regelmäßige Kontrolltermine während der gesamten Behandlung', 'Safir braketlerin yapıştırılması ve telin takılması (yaklaşık bir saat), ardından tedavi boyunca düzenli kontroller', 'Correcting tooth position and bite in adults, when the appearance of the braces is especially important', 'Ispravljanje položaja zuba i zagriza kod odraslih, kada je estetika aparata posebno važna', 'Исправљање положаја зуба и загриза код одраслих, када је естетика апарата посебно важна', 'Исправление положения зубов и прикуса у взрослых, когда эстетика брекетов особенно важна', 'Korrektur von Zahnstellung und Biss bei Erwachsenen, wenn die Ästhetik der Apparatur besonders wichtig ist', 'Aparatın görünümünün özellikle önemli olduğu, yetişkinlerde diş konumu ve kapanış düzeltmeleri', 'Oral health treatment and a cleaning before placement; discuss with the orthodontist that sapphire brackets cost more than metal ones with comparable effectiveness', 'Sanacija usne duplje i čišćenje prije postavljanja; sa ortodontom razmotriti da su safirne bravice skuplje od metalnih uz sličnu efikasnost', 'Санација усне дупље и чишћење прије постављања; са ортодонтом размотрити да су сафирне бравице скупље од металних уз сличну ефикасност', 'Санация полости рта и чистка перед установкой; обсудить с ортодонтом, что сапфировые брекеты дороже металлических при похожей эффективности', 'Sanierung der Mundhöhle und Reinigung vor dem Einsetzen; mit dem Kieferorthopäden besprechen, dass Saphirbrackets bei vergleichbarer Wirksamkeit teurer als Metallbrackets sind', 'Takmadan önce ağız sağlığının düzenlenmesi ve temizlik; safir braketlerin benzer etkinlikte metale göre daha pahalı olduğunun ortodontistle konuşulması', 'Discomfort after placement and adjustments is normal; chipped transparent brackets, mucosal irritation, or debonding require an unscheduled visit', 'Nelagodnost nakon postavljanja i kontrola je normalna; okrznute prozirne bravice, žuljanje sluznice ili odlijepljivanje zahtijevaju vanredni termin', 'Нелагодност након постављања и контрола је нормална; окрзнуте прозирне бравице, жуљање слузнице или одлијепљивање захтијевају ванредни термин', 'Дискомфорт после установки и коррекций — норма; сколы прозрачных брекетов, натирание слизистой или отклеивание требуют внепланового визита', 'Unbehagen nach dem Einsetzen und nach Anpassungen ist normal; abgeplatzte transparente Brackets, Reizungen der Schleimhaut oder ein Lösen erfordern einen zusätzlichen Termin', 'Takma ve kontroller sonrası rahatsızlık normaldir; şeffaf braketlerde kırılma, mukoza tahrişi veya yerinden çıkma plan dışı randevu gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'fixed-orthodontic-braces-per-arch'), 'Placement of a fixed bracket appliance on one dental arch (upper or lower)', 'Postavljanje fiksnog aparata na jedan zubni niz (gornji ili donji)', 'Постављање фиксног апарата на један зубни низ (горњи или доњи)', 'Установка несъёмной брекет-системы на одну зубную дугу (верхнюю или нижнюю)', 'Einsetzen einer festsitzenden Bracket-Apparatur auf einen Zahnbogen (oben oder unten)', 'Tek diş arkına (üst veya alt) sabit braket sisteminin takılması', 'Brackets are bonded to each tooth in the arch and connected with an orthodontic wire; treatment then continues with activation visits, usually every 4-8 weeks', 'Bravice se lijepe na svaki zub u nizu i povezuju ortodontskom žicom; liječenje se nastavlja posjetama za aktivaciju, obično svakih 4-8 nedjelja', 'Бравице се лијепе на сваки зуб у низу и повезују ортодонтском жицом; лијечење се наставља посјетама за активацију, обично сваких 4-8 недјеља', 'Брекеты приклеивают к каждому зубу дуги и соединяют ортодонтической дугой; далее лечение продолжается визитами для активации, обычно раз в 4-8 недель', 'Die Brackets werden auf jeden Zahn des Bogens geklebt und mit einem kieferorthopädischen Draht verbunden; die Behandlung wird mit Aktivierungsterminen fortgesetzt, meist alle 4-8 Wochen', 'Braketler arktaki her dişe yapıştırılır ve ortodontik telle birleştirilir; tedavi genellikle 4-8 haftada bir aktivasyon seanslarıyla sürer', 'Crowding and misaligned teeth, bite anomalies, preparation for prosthetic or implant treatment', 'Zbijenost i nepravilan položaj zuba, anomalije zagriza, priprema za protetiku ili implantaciju', 'Збијеност и неправилан положај зуба, аномалије загриза, припрема за протетику или имплантацију', 'Скученность и неправильное положение зубов, аномалии прикуса, подготовка к протезированию или имплантации', 'Engstand und Zahnfehlstellungen, Bissanomalien, Vorbereitung auf Zahnersatz oder Implantate', 'Sıkışıklık ve diş konumu bozuklukları, kapanış anomalileri, protez veya implant tedavisine hazırlık', 'Diagnostics with X-rays and impressions, treatment of cavities, a professional cleaning; check whether removal of the appliance and a retainer are included in the price', 'Dijagnostika sa rendgenom i otiscima, liječenje karijesa, profesionalno čišćenje; provjeriti da li su skidanje aparata i retainer uključeni u cijenu', 'Дијагностика са рендгеном и отисцима, лијечење каријеса, професионално чишћење; провјерити да ли су скидање апарата и ретаинер укључени у цијену', 'Диагностика с рентгеном и слепками, лечение кариеса, профессиональная чистка; уточнить, входит ли снятие системы и ретейнер в цену', 'Diagnostik mit Röntgen und Abdrücken, Kariesbehandlung, professionelle Zahnreinigung; nachfragen, ob das Entfernen der Apparatur und ein Retainer im Preis enthalten sind', 'Röntgen ve ölçülerle tanı, çürük tedavisi, profesyonel temizlik; aparatın sökümü ve pekiştirme apareyinin fiyata dahil olup olmadığını sormak', 'Pain when biting for 2-3 days after an activation is normal; a debonded bracket, an irritating wire, or gum inflammation require an unscheduled visit', 'Bol pri zagrizanju 2-3 dana nakon aktivacije je normalna; odlijepljena bravica, žica koja povređuje ili upala desni zahtijevaju termin van plana', 'Бол при загризању 2-3 дана након активације је нормална; одлијепљена бравица, жица која повређује или упала десни захтијевају термин ван плана', 'Боль при накусывании 2-3 дня после активации — норма; отклеившийся брекет, травмирующая дуга или воспаление дёсен требуют визита вне графика', 'Schmerzen beim Zubeißen für 2-3 Tage nach einer Aktivierung sind normal; ein gelöstes Bracket, ein verletzender Draht oder eine Zahnfleischentzündung erfordern einen Termin außerhalb des Plans', 'Aktivasyondan sonra 2-3 gün ısırırken ağrı normaldir; yerinden çıkan braket, tahriş eden tel veya diş eti iltihabı plan dışı randevu gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'orthodontic-removable-plate-appliance'), 'A removable orthodontic plate with a screw and wire that the child puts on themselves — it widens the jaw and guides tooth development', 'Pokretna ortodontska ploča sa vijkom i žicom koju dijete samo stavlja — širi vilicu i usmjerava razvoj zuba', 'Покретна ортодонтска плоча са вијком и жицом коју дијете само ставља — шири вилицу и усмјерава развој зуба', 'Съёмная ортодонтическая пластинка с винтом и дугой, которую ребёнок надевает сам — расширяет челюсть и направляет рост зубов', 'Eine herausnehmbare kieferorthopädische Platte mit Schraube und Bogen, die das Kind selbst einsetzt — sie erweitert den Kiefer und lenkt die Zahnentwicklung', 'Çocuğun kendi taktığı, vida ve tel içeren hareketli ortodontik plak — çeneyi genişletir ve diş gelişimini yönlendirir', 'An impression, fabrication of the plate in the laboratory, and fitting; the child then wears it on the prescribed schedule (usually most of the day) and the screw is turned periodically as instructed by the orthodontist', 'Otisak, izrada ploče u laboratoriji i prilagođavanje; dijete je zatim nosi po propisanom rasporedu (obično veći dio dana), a vijak se periodično zavrće po uputstvu ortodonta', 'Отисак, израда плоче у лабораторији и прилагођавање; дијете је затим носи по прописаном распореду (обично већи дио дана), а вијак се периодично заврће по упутству ортодонта', 'Слепок, изготовление пластинки в лаборатории и припасовка; далее ребёнок носит её по назначенному графику (обычно большую часть суток), а винт периодически подкручивают по инструкции ортодонта', 'Abdruck, Anfertigung der Platte im Labor und Einpassen; das Kind trägt sie danach nach dem verordneten Plan (meist den größten Teil des Tages), die Schraube wird nach Anweisung des Kieferorthopäden regelmäßig nachgestellt', 'Ölçü, plağın laboratuvarda üretimi ve uyumlama; ardından çocuk plağı belirlenen programa göre (genellikle günün büyük bölümünde) takar, vida ortodontistin talimatına göre periyodik olarak çevrilir', 'Orthodontic treatment in children and adolescents: a narrow jaw, individual tooth position anomalies, preparation for later treatment with braces', 'Ortodontsko liječenje kod djece i adolescenata: sužena vilica, pojedinačne nepravilnosti položaja zuba, priprema za kasnije liječenje fiksnim aparatom', 'Ортодонтско лијечење код дјеце и адолесцената: сужена вилица, појединачне неправилности положаја зуба, припрема за касније лијечење фиксним апаратом', 'Ортодонтическое лечение у детей и подростков: сужение челюсти, отдельные аномалии положения зубов, подготовка к дальнейшему лечению брекетами', 'Kieferorthopädische Behandlung bei Kindern und Jugendlichen: schmaler Kiefer, einzelne Zahnfehlstellungen, Vorbereitung auf eine spätere Behandlung mit festsitzender Apparatur', 'Çocuk ve ergenlerde ortodontik tedavi: dar çene, tek tek diş konumu bozuklukları, sonraki sabit tedaviye hazırlık', 'An orthodontic examination and X-rays; the child needs to be ready to wear and clean the plate consistently', 'Ortodontski pregled i snimci; važno je da je dijete spremno da ploču nosi i redovno čisti', 'Ортодонтски преглед и снимци; важно је да је дијете спремно да плочу носи и редовно чисти', 'Ортодонтический осмотр и снимки; важно, чтобы ребёнок был готов носить и чистить пластинку регулярно', 'Kieferorthopädische Untersuchung und Röntgenaufnahmen; das Kind sollte bereit sein, die Platte konsequent zu tragen und zu reinigen', 'Ortodontik muayene ve röntgenler; çocuğun plağı düzenli takmaya ve temizlemeye hazır olması önemlidir', 'Altered speech and increased salivation are possible in the first days; sore spots are resolved by adjustment, and if the plate no longer fits, see the orthodontist instead of forcing it in', 'Prvih dana su mogući izmijenjen izgovor i pojačano stvaranje pljuvačke; žuljevi se rješavaju korekcijom, a ako ploča više ne ulazi, treba doći kod ortodonta, a ne je utiskivati silom', 'Првих дана су могући измијењен изговор и појачано стварање пљувачке; жуљеви се рјешавају корекцијом, а ако плоча више не улази, треба доћи код ортодонта, а не је утискивати силом', 'Первые дни возможны нарушение дикции и повышенное слюноотделение; натирания устраняются коррекцией, а если пластинка перестала надеваться, нужно прийти к ортодонту, а не давить силой', 'In den ersten Tagen sind eine veränderte Aussprache und verstärkter Speichelfluss möglich; Druckstellen werden durch Korrekturen behoben, und passt die Platte nicht mehr, sollte man zum Kieferorthopäden gehen und sie nicht mit Kraft einsetzen', 'İlk günlerde konuşmada değişiklik ve tükürük artışı olabilir; vurma yaraları düzeltmeyle giderilir, plak artık oturmuyorsa zorlamak yerine ortodontiste gitmek gerekir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'orthodontic-functional-monoblock-appliance'), 'A removable functional appliance (monoblock) that covers both jaws at once and guides their relative position during growth', 'Pokretni funkcionalni aparat (monoblok) koji obuhvata obje vilice odjednom i usmjerava njihov međusobni položaj tokom rasta', 'Покретни функционални апарат (моноблок) који обухвата обје вилице одједном и усмјерава њихов међусобни положај током раста', 'Съёмный функциональный аппарат (моноблок), который охватывает обе челюсти сразу и направляет их взаимное положение во время роста', 'Ein herausnehmbares funktionelles Gerät (Monoblock), das beide Kiefer gleichzeitig umfasst und ihre Lage zueinander während des Wachstums lenkt', 'İki çeneyi birlikte saran ve büyüme sırasında birbirlerine göre konumlarını yönlendiren hareketli fonksiyonel aparey (monoblok)', 'Impressions of both jaws and bite registration, fabrication of the appliance in the laboratory, and fitting; worn as prescribed, most often at night and part of the day', 'Otisci obje vilice i određivanje položaja zagriza, izrada aparata u laboratoriji, prilagođavanje; nosi se po nalogu ljekara, najčešće noću i dio dana', 'Отисци обје вилице и одређивање положаја загриза, израда апарата у лабораторији, прилагођавање; носи се по налогу љекара, најчешће ноћу и дио дана', 'Слепки обеих челюстей и определение положения прикуса, изготовление аппарата в лаборатории, припасовка; носится по назначению врача, чаще всего ночью и часть дня', 'Abdrücke beider Kiefer und Bissregistrierung, Anfertigung des Geräts im Labor, Einpassen; wird nach Anweisung getragen, meist nachts und einen Teil des Tages', 'Her iki çeneden ölçü ve kapanış kaydı, apareyin laboratuvarda üretimi, uyumlama; hekimin talimatına göre, çoğunlukla geceleri ve günün bir bölümünde takılır', 'Bite anomalies in children and adolescents during the period of active jaw growth', 'Anomalije zagriza kod djece i adolescenata u periodu aktivnog rasta vilica', 'Аномалије загриза код дјеце и адолесцената у периоду активног раста вилица', 'Аномалии прикуса у детей и подростков в период активного роста челюстей', 'Bissanomalien bei Kindern und Jugendlichen in der Phase des aktiven Kieferwachstums', 'Çene büyümesinin aktif olduğu dönemde çocuk ve ergenlerde kapanış anomalileri', 'Orthodontic diagnostics with X-rays; the child''s willingness to wear the appliance consistently is essential — the result depends on it', 'Ortodontska dijagnostika sa snimcima; važna je spremnost djeteta da aparat nosi redovno — od toga zavisi rezultat', 'Ортодонтска дијагностика са снимцима; важна је спремност дјетета да апарат носи редовно — од тога зависи резултат', 'Ортодонтическая диагностика со снимками; важна готовность ребёнка носить аппарат регулярно — от этого зависит результат', 'Kieferorthopädische Diagnostik mit Röntgenaufnahmen; die Bereitschaft des Kindes, das Gerät konsequent zu tragen, ist entscheidend — davon hängt das Ergebnis ab', 'Röntgenlerle ortodontik tanı; çocuğun apareyi düzenli takmaya istekli olması sonucu belirler', 'Discomfort and increased salivation are possible during the first nights; pain in the chewing muscles or joints, as well as sore spots, are reasons to see the orthodontist for an adjustment', 'Prvih noći su mogući nelagodnost i pojačano stvaranje pljuvačke; bol u žvačnim mišićima ili zglobovima, kao i žuljevi, razlog su za pregled kod ortodonta radi korekcije', 'Првих ноћи су могући нелагодност и појачано стварање пљувачке; бол у жвачним мишићима или зглобовима, као и жуљеви, разлог су за преглед код ортодонта ради корекције', 'Первые ночи возможны дискомфорт и повышенное слюноотделение; боль в жевательных мышцах или суставах, а также натирания — повод показаться ортодонту для коррекции', 'In den ersten Nächten sind Unbehagen und verstärkter Speichelfluss möglich; Schmerzen in der Kaumuskulatur oder den Kiefergelenken sowie Druckstellen sind ein Grund für eine Korrektur beim Kieferorthopäden', 'İlk gecelerde rahatsızlık ve tükürük artışı olabilir; çiğneme kaslarında veya eklemlerde ağrı ile vurma yaraları düzeltme için ortodontiste başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'invisalign-aligner'), 'A clear removable Invisalign aligner — one element of a series that gradually moves the teeth', 'Prozirna pokretna folija sistema Invisalign — jedan element u seriji koja postepeno pomjera zube', 'Прозирна покретна фолија система Invisalign — један елемент у серији која постепено помјера зубе', 'Прозрачная съёмная капа системы Invisalign — один элемент в серии, которая постепенно перемещает зубы', 'Eine transparente herausnehmbare Invisalign-Schiene — ein Element einer Serie, die die Zähne allmählich bewegt', 'Şeffaf hareketli Invisalign plağı — dişleri kademeli olarak hareket ettiren serinin bir parçası', 'Each aligner is worn on the prescribed schedule (as a rule, a large part of the day) and then replaced by the next one in the series; it is taken out for eating and brushing', 'Svaka folija se nosi po propisanom rasporedu (obično veći dio dana), a zatim se mijenja sljedećom u seriji; folija se skida za vrijeme jela i pranja zuba', 'Свака фолија се носи по прописаном распореду (обично већи дио дана), а затим се мијења сљедећом у серији; фолија се скида за вријеме јела и прања зуба', 'Каждую капу носят по назначенному графику (как правило, значительную часть суток), затем меняют на следующую в серии; капу снимают на время еды и чистки зубов', 'Jede Schiene wird nach dem verordneten Plan getragen (in der Regel einen großen Teil des Tages) und dann durch die nächste der Serie ersetzt; zum Essen und Zähneputzen wird sie herausgenommen', 'Her plak belirlenen programa göre (kural olarak günün büyük bölümünde) takılır, sonra serideki bir sonrakiyle değiştirilir; yemek ve diş fırçalama sırasında çıkarılır', 'Correcting tooth position in adults and adolescents when braces are unsuitable for aesthetic or lifestyle reasons', 'Ispravljanje položaja zuba kod odraslih i adolescenata kada fiksni aparat ne odgovara iz estetskih ili praktičnih razloga', 'Исправљање положаја зуба код одраслих и адолесцената када фиксни апарат не одговара из естетских или практичних разлога', 'Исправление положения зубов у взрослых и подростков, когда брекеты не подходят по эстетическим или бытовым причинам', 'Korrektur der Zahnstellung bei Erwachsenen und Jugendlichen, wenn eine festsitzende Apparatur aus ästhetischen oder praktischen Gründen nicht passt', 'Estetik veya günlük yaşam nedenleriyle sabit apareyin uygun olmadığı yetişkin ve ergenlerde diş konumu düzeltmesi', 'Digital scanning and a treatment plan before starting; the result depends directly on wearing the aligners as instructed', 'Digitalno skeniranje i plan liječenja prije početka; rezultat direktno zavisi od discipline u nošenju folija', 'Дигитално скенирање и план лијечења прије почетка; резултат директно зависи од дисциплине у ношењу фолија', 'Цифровое сканирование и план лечения до начала; результат напрямую зависит от дисциплины в ношении кап', 'Digitaler Scan und Behandlungsplan vor dem Start; das Ergebnis hängt unmittelbar von der konsequenten Tragedauer ab', 'Başlamadan önce dijital tarama ve tedavi planı; sonuç plakların düzenli takılmasına doğrudan bağlıdır', 'Pressure and mild soreness in the first days after switching aligners are normal; a cracked or lost aligner, or a feeling that the teeth are not moving as planned, is a reason to contact the orthodontist', 'Pritisak i blaga bol prvih dana nakon zamjene folije su normalni; napukla ili izgubljena folija, kao i osjećaj da se zubi ne pomjeraju po planu, razlog su za kontakt sa ortodontom', 'Притисак и блага бол првих дана након замјене фолије су нормални; напукла или изгубљена фолија, као и осјећај да се зуби не помјерају по плану, разлог су за контакт са ортодонтом', 'Давление и лёгкая болезненность в первые дни после смены капы — норма; треснувшая или потерянная капа, а также ощущение, что зубы не двигаются по плану, — повод связаться с ортодонтом', 'Druck und leichte Schmerzen in den ersten Tagen nach dem Schienenwechsel sind normal; eine gerissene oder verlorene Schiene sowie der Eindruck, dass sich die Zähne nicht wie geplant bewegen, sind ein Grund, den Kieferorthopäden zu kontaktieren', 'Plak değişiminden sonraki ilk günlerde baskı ve hafif ağrı normaldir; çatlayan veya kaybolan plak ya da dişlerin plana göre hareket etmediği hissi ortodontistle iletişim gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'comprehensive-orthodontic-diagnostics'), 'A complete orthodontic work-up before treatment: examination, X-rays, impressions or a digital scan, and preparation of the treatment plan', 'Kompletna ortodontska dijagnostika prije liječenja: pregled, snimci, otisci ili digitalno skeniranje i izrada plana liječenja', 'Комплетна ортодонтска дијагностика прије лијечења: преглед, снимци, отисци или дигитално скенирање и израда плана лијечења', 'Полное ортодонтическое обследование перед лечением: осмотр, снимки, слепки или сканирование и расчёт плана лечения', 'Eine vollständige kieferorthopädische Diagnostik vor der Behandlung: Untersuchung, Röntgenaufnahmen, Abdrücke oder digitaler Scan und Erstellung des Behandlungsplans', 'Tedavi öncesi eksiksiz ortodontik değerlendirme: muayene, röntgenler, ölçü veya dijital tarama ve tedavi planının hazırlanması', 'The orthodontist examines the teeth and bite, orders a panoramic and lateral skull X-ray, takes impressions or a digital scan, photographs the face and teeth, and then prepares the plan; usually 1 visit plus a separate consultation about the plan', 'Ortodont pregleda zube i zagriz, upućuje na panoramski i profilni snimak glave, uzima otiske ili digitalni skan, fotografiše lice i zube, a zatim izrađuje plan; obično 1 posjeta plus posebna konsultacija o planu', 'Ортодонт прегледа зубе и загриз, упућује на панорамски и профилни снимак главе, узима отиске или дигитални скан, фотографише лице и зубе, а затим израђује план; обично 1 посјета плус посебна консултација о плану', 'Ортодонт осматривает зубы и прикус, направляет на панорамный и боковой снимок черепа, снимает слепки или делает цифровой скан, фотографирует лицо и зубы, затем составляет план; обычно 1 визит плюс отдельная консультация по плану', 'Der Kieferorthopäde untersucht Zähne und Biss, veranlasst Panorama- und Fernröntgenseitenbild, nimmt Abdrücke oder einen digitalen Scan, fotografiert Gesicht und Zähne und erstellt dann den Plan; in der Regel 1 Termin plus eine separate Besprechung des Plans', 'Ortodontist dişleri ve kapanışı inceler, panoramik ve profil kafa röntgeni ister, ölçü veya dijital tarama alır, yüz ve diş fotoğraflarını çeker, ardından planı hazırlar; genellikle 1 seans artı plan için ayrı bir görüşme', 'Before starting any orthodontic treatment — braces, aligners, removable appliances; also for a second opinion on a plan already proposed', 'Prije početka bilo kojeg ortodontskog liječenja — fiksni aparat, folije, pokretni aparati; takođe za drugo mišljenje o već predloženom planu', 'Прије почетка било којег ортодонтског лијечења — фиксни апарат, фолије, покретни апарати; такође за друго мишљење о већ предложеном плану', 'Перед началом любого ортодонтического лечения — брекеты, капы, съёмные аппараты; второе мнение по уже предложенному плану', 'Vor Beginn jeder kieferorthopädischen Behandlung — festsitzende Apparatur, Schienen, herausnehmbare Geräte; auch für eine Zweitmeinung zu einem vorliegenden Plan', 'Herhangi bir ortodontik tedaviye başlamadan önce — braket, şeffaf plak, hareketli apareyler; önerilmiş bir plan için ikinci görüş almak amacıyla da', 'Come with clean teeth; bringing existing X-rays is useful if they were taken recently', 'Doći sa očišćenim zubima; korisno je donijeti postojeće snimke ako su nedavno urađeni', 'Доћи са очишћеним зубима; корисно је донијети постојеће снимке ако су недавно урађени', 'Прийти с почищенными зубами; полезно принести имеющиеся снимки, если они сделаны недавно', 'Mit gereinigten Zähnen kommen; vorhandene Röntgenbilder sind hilfreich, wenn sie aktuell sind', 'Dişleri temizlenmiş olarak gelmek; yakın zamanda çekilmiş röntgenleri getirmek yararlıdır', 'The work-up is painless; it may reveal hidden issues — unerupted teeth, cavities, the state of the jaw joint — which the orthodontist will include in the treatment plan', 'Dijagnostika je bezbolna; njenim rezultatom mogu se otkriti skriveni problemi — neizrasli zubi, karijes, stanje viličnog zgloba — koje ljekar uključuje u plan liječenja', 'Дијагностика је безболна; њеним резултатом могу се открити скривени проблеми — неизрасли зуби, каријес, стање виличног зглоба — које љекар укључује у план лијечења', 'Обследование безболезненно; по его итогам могут выявиться скрытые проблемы — непрорезавшиеся зубы, кариес, состояние височно-челюстного сустава — и врач включит их в план лечения', 'Die Diagnostik ist schmerzfrei; sie kann verborgene Befunde aufdecken — nicht durchgebrochene Zähne, Karies, den Zustand des Kiefergelenks — die der Arzt in den Behandlungsplan aufnimmt', 'Değerlendirme ağrısızdır; sonucunda gizli sorunlar — sürmemiş dişler, çürükler, çene ekleminin durumu — ortaya çıkabilir ve hekim bunları tedavi planına dahil eder')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'orthodontic-retainer'), 'A retainer — an appliance that holds the teeth in their new position after braces are removed: a thin wire on the inner surface of the teeth or a clear plate', 'Retainer — konstrukcija koja drži zube u novom položaju nakon skidanja fiksnog aparata: tanka žica sa unutrašnje strane zuba ili prozirna folija', 'Ретаинер — конструкција која држи зубе у новом положају након скидања фиксног апарата: танка жица са унутрашње стране зуба или прозирна фолија', 'Ретейнер — конструкция, удерживающая зубы в новом положении после снятия брекетов: тонкая проволока с внутренней стороны зубов или прозрачная капа', 'Ein Retainer — eine Vorrichtung, die die Zähne nach dem Entfernen der Brackets in der neuen Position hält: ein dünner Draht auf der Zahninnenseite oder eine transparente Schiene', 'Pekiştirme apareyi — braketler söküldükten sonra dişleri yeni konumunda tutan yapı: dişlerin iç yüzeyine yapıştırılan ince tel veya şeffaf plak', 'Made from an impression or scan after the braces are removed; the fixed type is bonded to the inner surface of the teeth, while the removable type is worn on the schedule set by the orthodontist', 'Izrađuje se po otisku ili skanu nakon skidanja aparata; fiksna varijanta se lijepi na unutrašnju stranu zuba, a pokretna se nosi po rasporedu koji odredi ortodont', 'Израђује се по отиску или скану након скидања апарата; фиксна варијанта се лијепи на унутрашњу страну зуба, а покретна се носи по распореду који одреди ортодонт', 'Изготавливается по слепку или скану после снятия брекетов; несъёмный вариант приклеивается к внутренней поверхности зубов, съёмный носится по графику, назначенному ортодонтом', 'Wird nach dem Entfernen der Apparatur aus einem Abdruck oder Scan angefertigt; die festsitzende Variante wird auf die Zahninnenseite geklebt, die herausnehmbare nach dem Plan des Kieferorthopäden getragen', 'Braketler söküldükten sonra ölçü veya taramayla üretilir; sabit tür dişlerin iç yüzeyine yapıştırılır, hareketli tür ortodontistin belirlediği programa göre takılır', 'A mandatory stage after any orthodontic treatment — without it the teeth gradually drift back toward their previous position', 'Obavezna faza nakon svakog ortodontskog liječenja — bez nje se zubi postepeno vraćaju u prethodni položaj', 'Обавезна фаза након сваког ортодонтског лијечења — без ње се зуби постепено враћају у претходни положај', 'Обязательный этап после любого ортодонтического лечения — без него зубы постепенно возвращаются к прежнему положению', 'Ein zwingender Abschnitt nach jeder kieferorthopädischen Behandlung — ohne ihn wandern die Zähne allmählich in die alte Position zurück', 'Her ortodontik tedaviden sonra zorunlu aşama — olmadan dişler kademeli olarak eski konumuna döner', 'A professional cleaning after the braces are removed; ask the orthodontist how long it must be worn — usually a matter of years', 'Profesionalno čišćenje nakon skidanja aparata; provjeriti sa ortodontom rok nošenja — obično se mjeri godinama', 'Професионално чишћење након скидања апарата; провјерити са ортодонтом рок ношења — обично се мјери годинама', 'Профессиональная чистка после снятия брекетов; уточнить у ортодонта срок ношения — обычно он измеряется годами', 'Professionelle Zahnreinigung nach dem Entfernen der Apparatur; die Tragedauer beim Kieferorthopäden erfragen — meist über Jahre', 'Braketler söküldükten sonra profesyonel temizlik; kullanım süresini ortodontiste sormak — genellikle yıllarla ölçülür', 'A debonded wire or a cracked plate means the retention no longer works — see the orthodontist as soon as possible, before the teeth shift', 'Odlijepljena žica ili napukla folija znače da držanje više ne funkcioniše — kod ortodonta treba doći što prije, dok se zubi nisu pomjerili', 'Одлијепљена жица или напукла фолија значе да држање више не функционише — код ортодонта треба доћи што прије, док се зуби нису помјерили', 'Отклеившаяся проволока или треснувшая капа означают, что удержание больше не работает — к ортодонту нужно попасть как можно быстрее, пока зубы не сместились', 'Ein gelöster Draht oder eine gerissene Schiene bedeutet, dass die Stabilisierung nicht mehr wirkt — möglichst schnell zum Kieferorthopäden, bevor sich die Zähne verschieben', 'Yerinden çıkan tel veya çatlayan plak, tutuculuğun artık çalışmadığı anlamına gelir — dişler kaymadan en kısa sürede ortodontiste gitmek gerekir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'retainer-placement-per-arch'), 'Placement of a retainer on one jaw — fixing the retaining appliance after orthodontic treatment', 'Postavljanje retainera na jednu vilicu — fiksiranje konstrukcije za držanje nakon ortodontskog liječenja', 'Постављање ретаинера на једну вилицу — фиксирање конструкције за држање након ортодонтског лијечења', 'Установка ретейнера на одну челюсть — фиксация удерживающей конструкции после ортодонтического лечения', 'Einsetzen eines Retainers für einen Kiefer — Befestigung der Haltevorrichtung nach der kieferorthopädischen Behandlung', 'Tek çeneye pekiştirme apareyinin takılması — ortodontik tedaviden sonra tutucu yapının sabitlenmesi', 'The teeth are polished and a thin wire is bonded to their inner surface with composite (or a removable plate is fitted); takes 20-40 minutes in a single visit', 'Zubi se poliraju, na unutrašnju stranu se kompozitom lijepi tanka žica (ili se prilagođava pokretna folija); traje 20-40 minuta u jednoj posjeti', 'Зуби се полирају, на унутрашњу страну се композитом лијепи танка жица (или се прилагођава покретна фолија); траје 20-40 минута у једној посјети', 'Зубы полируют, на внутреннюю поверхность приклеивают тонкую проволоку композитом (или припасовывают съёмную капу); занимает 20-40 минут за один визит', 'Die Zähne werden poliert und ein dünner Draht wird mit Komposit auf die Innenseite geklebt (oder eine herausnehmbare Schiene wird angepasst); dauert 20-40 Minuten in einem Termin', 'Dişler parlatılır, iç yüzeylerine kompozitle ince tel yapıştırılır (veya hareketli plak uyumlanır); tek seansta 20-40 dakika sürer', 'Immediately after braces are removed from that jaw; re-placement if a previous retainer has debonded or broken', 'Odmah nakon skidanja fiksnog aparata sa te vilice; ponovno postavljanje ako se prethodni retainer odlijepio ili slomio', 'Одмах након скидања фиксног апарата са те вилице; поновно постављање ако се претходни ретаинер одлијепио или сломио', 'Сразу после снятия брекетов на соответствующей челюсти; повторная установка, если предыдущий ретейнер отклеился или сломался', 'Direkt nach dem Entfernen der Apparatur an diesem Kiefer; erneutes Einsetzen, wenn ein früherer Retainer sich gelöst oder gebrochen hat', 'O çenedeki braketler söküldükten hemen sonra; önceki apareyin çıkması veya kırılması hâlinde yeniden takma', 'A professional cleaning before bonding improves the strength of the attachment', 'Profesionalno čišćenje prije lijepljenja poboljšava čvrstinu veze', 'Професионално чишћење прије лијепљења побољшава чврстину везе', 'Профессиональная чистка перед приклеиванием улучшает прочность фиксации', 'Eine professionelle Zahnreinigung vor dem Kleben verbessert die Haftung', 'Yapıştırma öncesi profesyonel temizlik bağlanma dayanımını artırır', 'The tongue gets used to the wire in the first days — this is normal; a sharp edge, a debonded section, or plaque build-up around the retainer are reasons to see the dentist', 'Prvih dana se jezik privikava na žicu — to je normalno; oštra ivica, odlijepljen dio ili nakupljanje plaka oko retainera razlog su za posjetu stomatologu', 'Првих дана се језик привикава на жицу — то је нормално; оштра ивица, одлијепљен дио или накупљање плака око ретаинера разлог су за посјету стоматологу', 'Первые дни язык привыкает к проволоке — это нормально; острый край, отклеившийся участок или скопление налёта вокруг ретейнера — повод обратиться к стоматологу', 'In den ersten Tagen gewöhnt sich die Zunge an den Draht — das ist normal; eine scharfe Kante, eine gelöste Stelle oder Plaqueansammlungen um den Retainer sind ein Grund für einen Zahnarztbesuch', 'İlk günlerde dil tele alışır — bu normaldir; keskin kenar, yerinden çıkan bölüm veya aparey çevresinde plak birikmesi diş hekimine başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'retention-aligner-fabrication'), 'Fabrication of a clear retention plate that is worn over the teeth to hold the result of orthodontic treatment', 'Izrada prozirne retencione folije koja se stavlja preko zuba i drži rezultat ortodontskog liječenja', 'Израда прозирне ретенционе фолије која се ставља преко зуба и држи резултат ортодонтског лијечења', 'Изготовление прозрачной ретенционной каппы, которая надевается на зубы и удерживает результат ортодонтического лечения', 'Anfertigung einer transparenten Retentionsschiene, die über die Zähne gesetzt wird und das Ergebnis der kieferorthopädischen Behandlung hält', 'Ortodontik tedavi sonucunu korumak için dişlerin üzerine takılan şeffaf pekiştirme plağının üretimi', 'An impression or digital scan is taken, the plate is made on a model and tried in; usually 2 visits a few days apart', 'Uzima se otisak ili digitalni skan, folija se izrađuje po modelu i proba; obično 2 posjete u razmaku od nekoliko dana', 'Узима се отисак или дигитални скан, фолија се израђује по моделу и проба; обично 2 посјете у размаку од неколико дана', 'Снимается слепок или цифровой скан, каппа изготавливается по модели и примеряется; обычно 2 визита с интервалом в несколько дней', 'Es wird ein Abdruck oder digitaler Scan genommen, die Schiene am Modell angefertigt und anprobiert; in der Regel 2 Termine im Abstand von einigen Tagen', 'Ölçü veya dijital tarama alınır, plak model üzerinde üretilir ve prova edilir; genellikle birkaç gün arayla 2 seans', 'After braces are removed or aligner treatment is completed; replacement of a worn, cracked, or lost retention plate', 'Nakon skidanja fiksnog aparata ili završetka liječenja folijama; zamjena istrošene, napukle ili izgubljene retencione folije', 'Након скидања фиксног апарата или завршетка лијечења фолијама; замјена истрошене, напукле или изгубљене ретенционе фолије', 'После снятия брекетов или завершения лечения капами; замена изношенной, треснувшей или потерянной ретенционной каппы', 'Nach dem Entfernen der Apparatur oder dem Abschluss einer Schienenbehandlung; Ersatz einer abgenutzten, gerissenen oder verlorenen Retentionsschiene', 'Braketler söküldükten veya şeffaf plak tedavisi tamamlandıktan sonra; yıpranmış, çatlamış ya da kaybolmuş plağın yenilenmesi', 'A professional cleaning before the impression; ask the orthodontist how many hours a day it must be worn', 'Profesionalno čišćenje prije uzimanja otiska; provjeriti sa ortodontom koliko sati dnevno treba nositi foliju', 'Професионално чишћење прије узимања отиска; провјерити са ортодонтом колико сати дневно треба носити фолију', 'Профессиональная чистка перед снятием слепка; уточнить у ортодонта, сколько часов в сутки нужно носить каппу', 'Professionelle Zahnreinigung vor der Abdrucknahme; beim Kieferorthopäden erfragen, wie viele Stunden pro Tag sie getragen werden muss', 'Ölçü öncesi profesyonel temizlik; günde kaç saat takılması gerektiğini ortodontiste sormak', 'Slight pressure during the first nights is normal; if the plate becomes hard to seat, the teeth may have shifted — this calls for an examination rather than forcing it on', 'Blag pritisak prvih noći je normalan; ako folija počne teško da ulazi, to može značiti pomjeranje zuba — potreban je pregled, a ne nasilno stavljanje', 'Благ притисак првих ноћи је нормалан; ако фолија почне тешко да улази, то може значити помјерање зуба — потребан је преглед, а не насилно стављање', 'Лёгкое давление в первые ночи — норма; если каппа стала надеваться с трудом, это может означать смещение зубов — нужен осмотр, а не силовое надевание', 'Leichter Druck in den ersten Nächten ist normal; lässt sich die Schiene nur schwer einsetzen, können sich die Zähne verschoben haben — dann ist eine Kontrolle nötig und kein Einsetzen mit Kraft', 'İlk gecelerde hafif baskı normaldir; plak zor oturmaya başlarsa dişler kaymış olabilir — zorlamak yerine muayene gerekir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'home-teeth-whitening'), 'Tooth whitening carried out by the patient at home with custom trays and gel provided by the dentist', 'Bijeljenje zuba koje pacijent sam sprovodi kod kuće individualnim folijama sa gelom koje mu je dao stomatolog', 'Бијељење зуба које пацијент сам спроводи код куће индивидуалним фолијама са гелом које му је дао стоматолог', 'Отбеливание зубов, которое пациент выполняет дома индивидуальными каппами с гелем, выданными стоматологом', 'Zahnaufhellung, die der Patient zu Hause mit individuellen Schienen und einem vom Zahnarzt bereitgestellten Gel durchführt', 'Diş hekiminin verdiği kişiye özel plaklar ve jelle hastanın evde uyguladığı diş beyazlatma', 'The dentist takes impressions and makes the trays, supplies the gel, and explains the regimen; the trays are worn at home for the prescribed time over 1-2 weeks, after which the dentist assesses the result', 'Stomatolog uzima otiske i izrađuje folije, daje gel i objašnjava režim; folije se nose kod kuće propisano vrijeme tokom 1-2 nedjelje, a zatim ljekar procjenjuje rezultat', 'Стоматолог узима отиске и израђује фолије, даје гел и објашњава режим; фолије се носе код куће прописано вријеме током 1-2 недјеље, а затим љекар процјењује резултат', 'Стоматолог снимает слепки и изготавливает каппы, выдаёт гель и объясняет режим; каппы надевают дома на назначенное время в течение 1-2 недель, затем врач оценивает результат', 'Der Zahnarzt nimmt Abdrücke und fertigt die Schienen an, gibt das Gel mit und erklärt das Vorgehen; die Schienen werden zu Hause für die verordnete Zeit über 1-2 Wochen getragen, danach beurteilt der Zahnarzt das Ergebnis', 'Hekim ölçü alıp plakları hazırlar, jeli verir ve kullanım düzenini anlatır; plaklar 1-2 hafta boyunca belirtilen süreyle evde takılır, ardından hekim sonucu değerlendirir', 'Enamel darkened by coffee, tea, smoking, or age, when a gradual home course is preferred to an in-office procedure', 'Potamnjela gleđ od kafe, čaja, pušenja i sa godinama, kada se preferira postepeni kućni tretman umjesto procedure u ordinaciji', 'Потамњела глеђ од кафе, чаја, пушења и са годинама, када се преферира постепени кућни третман умјесто процедуре у ординацији', 'Потемнение эмали от кофе, чая, курения и с возрастом, когда предпочтителен постепенный домашний курс вместо кабинетной процедуры', 'Durch Kaffee, Tee, Rauchen oder Alter dunkler gewordener Zahnschmelz, wenn eine schrittweise Anwendung zu Hause der Behandlung in der Praxis vorgezogen wird', 'Kahve, çay, sigara ve yaşla koyulaşan mine; muayenehane işlemi yerine kademeli evde uygulamanın tercih edilmesi', 'An examination, treatment of cavities, and a professional cleaning are required beforehand; whitening does not lighten fillings and crowns — their color stays the same', 'Obavezni su pregled, liječenje karijesa i profesionalno čišćenje prije početka; bijeljenje ne posvjetljuje plombe i krunice — njihova boja ostaje ista', 'Обавезни су преглед, лијечење каријеса и професионално чишћење прије почетка; бијељење не посвјетљује пломбе и крунице — њихова боја остаје иста', 'Обязательны осмотр, лечение кариеса и профессиональная чистка до начала; отбеливание не осветляет пломбы и коронки — их цвет останется прежним', 'Untersuchung, Kariesbehandlung und professionelle Zahnreinigung sind vorab erforderlich; Füllungen und Kronen werden nicht aufgehellt — ihre Farbe bleibt unverändert', 'Öncesinde muayene, çürük tedavisi ve profesyonel temizlik zorunludur; beyazlatma dolgu ve kronları açmaz — renkleri aynı kalır', 'Increased tooth sensitivity and mild gum irritation during the course are common and usually reversible; if pain is severe, pause and contact the dentist', 'Povećana osjetljivost zuba i blaga iritacija desni tokom tretmana su česti i obično prolazni; kod jake boli treba napraviti pauzu i kontaktirati stomatologa', 'Повећана осјетљивост зуба и блага иритација десни током третмана су чести и обично пролазни; код јаке боли треба направити паузу и контактирати стоматолога', 'Повышенная чувствительность зубов и лёгкое раздражение дёсен во время курса — частое и обычно обратимое явление; при сильной боли нужно сделать паузу и связаться со стоматологом', 'Erhöhte Zahnempfindlichkeit und leichte Zahnfleischreizungen während der Anwendung sind häufig und meist vorübergehend; bei starken Schmerzen pausieren und den Zahnarzt kontaktieren', 'Uygulama sırasında diş hassasiyetinin artması ve hafif diş eti tahrişi sıktır ve genellikle geçicidir; şiddetli ağrıda ara verip hekime başvurmak gerekir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'in-office-teeth-whitening-single-arch'), 'In-office whitening of one dental arch with a professional gel under the dentist''s supervision', 'Bijeljenje zuba jedne vilice u ordinaciji profesionalnim gelom pod nadzorom stomatologa', 'Бијељење зуба једне вилице у ординацији професионалним гелом под надзором стоматолога', 'Кабинетное отбеливание зубов одной челюсти профессиональным гелем под контролем стоматолога', 'Zahnaufhellung eines Zahnbogens in der Praxis mit einem professionellen Gel unter Aufsicht des Zahnarztes', 'Tek diş arkının, hekim gözetiminde profesyonel jelle muayenehanede beyazlatılması', 'The gums are isolated with a protective barrier and the gel is applied to the teeth in several rounds, sometimes activated with a lamp; the procedure takes 45-90 minutes in one visit', 'Desni se izoluju zaštitnom barijerom, a gel se nanosi na zube u nekoliko navrata, ponekad sa aktivacijom lampom; procedura traje 45-90 minuta u jednoj posjeti', 'Десни се изолују заштитном баријером, а гел се наноси на зубе у неколико наврата, понекад са активацијом лампом; процедура траје 45-90 минута у једној посјети', 'Дёсны изолируют защитным барьером, на зубы наносят гель в несколько подходов, иногда с активацией лампой; процедура занимает 45-90 минут за один визит', 'Das Zahnfleisch wird mit einer Schutzbarriere abgedeckt und das Gel in mehreren Durchgängen auf die Zähne aufgetragen, teils mit Lampenaktivierung; die Behandlung dauert 45-90 Minuten in einem Termin', 'Diş etleri koruyucu bariyerle izole edilir, jel dişlere birkaç turda uygulanır, bazen lamba ile aktive edilir; işlem tek seansta 45-90 dakika sürer', 'A wish to lighten the teeth quickly, before an event or before restoring front teeth to choose the shade', 'Želja da se zubi posvijetle brzo, pred događaj ili prije protetike prednjih zuba radi izbora nijanse', 'Жеља да се зуби посвијетле брзо, пред догађај или прије протетике предњих зуба ради избора нијансе', 'Желание осветлить зубы быстро, к событию или перед протезированием передних зубов для подбора оттенка', 'Wunsch nach schneller Aufhellung, vor einem Anlass oder vor der Versorgung der Frontzähne zur Farbbestimmung', 'Dişleri hızlı açmak isteği, bir etkinlik öncesi veya ön diş protezinde renk seçimi öncesi', 'An examination and professional cleaning in advance; pigmented foods and drinks are avoided for the first 1-2 days afterwards', 'Pregled i profesionalno čišćenje unaprijed; prvih 1-2 dana nakon procedure izbjegavaju se hrana i napici koji boje', 'Преглед и професионално чишћење унапријед; првих 1-2 дана након процедуре избјегавају се храна и напици који боје', 'Осмотр и профессиональная чистка заранее; в первые 1-2 суток после процедуры избегают красящих продуктов и напитков', 'Untersuchung und professionelle Zahnreinigung im Vorfeld; in den ersten 1-2 Tagen danach farbintensive Lebensmittel und Getränke meiden', 'Önceden muayene ve profesyonel temizlik; işlemden sonraki ilk 1-2 gün renklendirici yiyecek ve içeceklerden kaçınmak', 'Tooth sensitivity and slight whitening of areas of the gum right after the procedure usually pass within 1-2 days; sharp pain or prolonged burning of the gum is a reason to contact the clinic', 'Osjetljivost zuba i blago bijeljenje dijelova desni odmah nakon procedure obično prolaze za 1-2 dana; jaka bol ili dugotrajno peckanje desni razlog su za kontakt sa klinikom', 'Осјетљивост зуба и благо бијељење дијелова десни одмах након процедуре обично пролазе за 1-2 дана; јака бол или дуготрајно пецкање десни разлог су за контакт са клиником', 'Чувствительность зубов и лёгкое побеление участков десны сразу после процедуры обычно проходят за 1-2 дня; резкая боль или длительное жжение десны — повод связаться с клиникой', 'Zahnempfindlichkeit und eine leichte Weißfärbung von Zahnfleischbereichen direkt nach der Behandlung vergehen meist in 1-2 Tagen; starke Schmerzen oder anhaltendes Brennen am Zahnfleisch sind ein Grund, die Praxis zu kontaktieren', 'İşlemden hemen sonra diş hassasiyeti ve diş etinin bazı bölgelerinde hafif beyazlaşma genellikle 1-2 günde geçer; şiddetli ağrı veya diş etinde uzun süren yanma kliniğe başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'laser-teeth-whitening'), 'In-office whitening in which the action of the gel is accelerated with a laser or a special lamp', 'Bijeljenje u ordinaciji kod kojeg se djelovanje gela ubrzava laserom ili posebnom lampom', 'Бијељење у ординацији код којег се дјеловање гела убрзава ласером или посебном лампом', 'Кабинетное отбеливание, при котором действие геля ускоряется лазером или специальной лампой', 'Aufhellung in der Praxis, bei der die Wirkung des Gels mit einem Laser oder einer speziellen Lampe beschleunigt wird', 'Jelin etkisinin lazer veya özel bir lambayla hızlandırıldığı muayenehane beyazlatması', 'Gum isolation, application of the gel, and laser activation in several cycles; one visit, usually 45-60 minutes', 'Izolacija desni, nanošenje gela i aktivacija laserom u nekoliko ciklusa; jedna posjeta, obično 45-60 minuta', 'Изолација десни, наношење гела и активација ласером у неколико циклуса; једна посјета, обично 45-60 минута', 'Изоляция дёсен, нанесение геля и активация лазером в несколько циклов; один визит, обычно 45-60 минут', 'Abdecken des Zahnfleischs, Auftragen des Gels und Laseraktivierung in mehreren Zyklen; ein Termin, meist 45-60 Minuten', 'Diş etlerinin izolasyonu, jelin uygulanması ve birkaç döngüde lazerle aktivasyon; tek seans, genellikle 45-60 dakika', 'Darkened enamel, when the fastest visible result in a single appointment is wanted', 'Potamnjela gleđ, kada je potreban najbrži vidljiv rezultat u jednoj posjeti', 'Потамњела глеђ, када је потребан најбржи видљив резултат у једној посјети', 'Потемнение эмали, когда нужен максимально быстрый видимый результат за одно посещение', 'Dunkler Zahnschmelz, wenn ein möglichst schnelles sichtbares Ergebnis in einer Sitzung gewünscht ist', 'Koyulaşmış mine; tek seansta en hızlı görünür sonucun istendiği durumlar', 'An examination, treatment of cavities, and a professional cleaning before the procedure; afterwards, 1-2 days without pigmented foods, coffee, and wine', 'Pregled, liječenje karijesa i profesionalno čišćenje prije procedure; nakon toga 1-2 dana bez hrane koja boji, kafe i vina', 'Преглед, лијечење каријеса и професионално чишћење прије процедуре; након тога 1-2 дана без хране која боји, кафе и вина', 'Осмотр, лечение кариеса и профессиональная чистка до процедуры; после — 1-2 дня без красящих продуктов, кофе и вина', 'Untersuchung, Kariesbehandlung und professionelle Zahnreinigung vor der Behandlung; danach 1-2 Tage ohne farbintensive Lebensmittel, Kaffee und Wein', 'İşlemden önce muayene, çürük tedavisi ve profesyonel temizlik; sonrasında 1-2 gün renklendirici gıdalar, kahve ve şaraptan kaçınmak', 'Increased tooth sensitivity in the first 1-2 days is the most common reaction; prolonged or severe pain and persistent gum irritation require a dental consultation', 'Povećana osjetljivost zuba prvih 1-2 dana je najčešća reakcija; dugotrajna ili jaka bol, kao i uporna iritacija desni, zahtijevaju konsultaciju sa stomatologom', 'Повећана осјетљивост зуба првих 1-2 дана је најчешћа реакција; дуготрајна или јака бол, као и упорна иритација десни, захтијевају консултацију са стоматологом', 'Повышенная чувствительность зубов в первые 1-2 дня — самая частая реакция; долгая или сильная боль, а также стойкое раздражение дёсен требуют консультации стоматолога', 'Erhöhte Zahnempfindlichkeit in den ersten 1-2 Tagen ist die häufigste Reaktion; anhaltende oder starke Schmerzen sowie dauerhafte Zahnfleischreizungen erfordern eine zahnärztliche Beratung', 'İlk 1-2 günde diş hassasiyetinin artması en sık görülen tepkidir; uzun süren veya şiddetli ağrı ile inatçı diş eti tahrişi hekim görüşü gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'direct-composite-veneer'), 'A composite facing that the dentist shapes directly on the tooth in a single visit, changing its form and color', 'Ljuspica od kompozita koju stomatolog oblikuje direktno na zubu u jednoj posjeti, mijenjajući oblik i boju', 'Љуспица од композита коју стоматолог обликује директно на зубу у једној посјети, мијењајући облик и боју', 'Накладка из композитного материала, которую стоматолог формирует прямо на зубе за одно посещение, меняя форму и цвет', 'Eine Verblendung aus Komposit, die der Zahnarzt in einer Sitzung direkt am Zahn formt und damit Form und Farbe verändert', 'Hekimin tek seansta doğrudan diş üzerinde şekillendirdiği, dişin biçimini ve rengini değiştiren kompozit kaplama', 'The tooth is prepared minimally or not at all, composite is applied and cured in layers, then shaped and polished; 40-90 minutes per tooth, one visit', 'Zub se priprema minimalno ili bez brušenja, kompozit se nanosi i polimerizuje u slojevima, zatim se obrađuje i polira; 40-90 minuta po zubu, jedna posjeta', 'Зуб се припрема минимално или без брушења, композит се наноси и полимеризује у слојевима, затим се обрађује и полира; 40-90 минута по зубу, једна посјета', 'Зуб подготавливают минимально или без обточки, послойно наносят и полимеризуют композит, затем шлифуют и полируют; 40-90 минут на зуб, один визит', 'Der Zahn wird minimal oder gar nicht beschliffen, das Komposit wird schichtweise aufgetragen und ausgehärtet, danach ausgearbeitet und poliert; 40-90 Minuten pro Zahn, ein Termin', 'Diş çok az aşındırılır veya hiç aşındırılmaz, kompozit katman katman uygulanıp sertleştirilir, sonra şekillendirilip parlatılır; diş başına 40-90 dakika, tek seans', 'Small chips, gaps between front teeth, changing the shape or color of one or two teeth; a faster and more conservative option than ceramic veneers', 'Manja okrzavanja, razmaci između prednjih zuba, promjena oblika ili boje jednog-dva zuba; brža i štedljivija varijanta od keramičkih ljuspica', 'Мања окрзавања, размаци између предњих зуба, промјена облика или боје једног-два зуба; бржа и штедљивија варијанта од керамичких љуспица', 'Небольшие сколы, промежутки между передними зубами, изменение формы или цвета одного-двух зубов; более быстрый и щадящий вариант, чем керамические виниры', 'Kleine Absplitterungen, Lücken zwischen den Frontzähnen, Änderung von Form oder Farbe eines oder zweier Zähne; schneller und zahnschonender als Keramikveneers', 'Küçük kırıklar, ön dişler arası boşluklar, bir-iki dişin şekil veya renginin değiştirilmesi; seramik kaplamalara göre daha hızlı ve daha koruyucu seçenek', 'No special preparation is required; note that composite changes color over time and needs polishing more often than ceramic', 'Posebna priprema nije potrebna; imati u vidu da kompozit s vremenom mijenja boju i zahtijeva poliranje češće od keramike', 'Посебна припрема није потребна; имати у виду да композит с временом мијења боју и захтијева полирање чешће од керамике', 'Специальной подготовки не требуется; учесть, что композит со временем меняет цвет и требует полировки чаще, чем керамика', 'Keine besondere Vorbereitung nötig; Komposit verfärbt sich mit der Zeit und muss häufiger poliert werden als Keramik', 'Özel hazırlık gerekmez; kompozitin zamanla renk değiştirdiğini ve seramiğe göre daha sık parlatma gerektirdiğini bilmek', 'Mild sensitivity in the first days is normal; a chipped edge, roughness, or staining at the margin with the tooth are reasons for an adjustment at the dentist', 'Blaga osjetljivost prvih dana je uobičajena; okrznuta ivica, hrapavost ili prebojavanje granice sa zubom razlog su za korekciju kod stomatologa', 'Блага осјетљивост првих дана је уобичајена; окрзнута ивица, храпавост или пребојавање границе са зубом разлог су за корекцију код стоматолога', 'Небольшая чувствительность в первые дни — обычное явление; скол края, шероховатость или окрашивание границы с зубом — повод для коррекции у стоматолога', 'Leichte Empfindlichkeit in den ersten Tagen ist normal; eine abgeplatzte Kante, Rauheit oder Verfärbungen am Übergang zum Zahn sind ein Grund für eine Korrektur beim Zahnarzt', 'İlk günlerde hafif hassasiyet normaldir; kenarda kırık, pürüzlülük veya dişle birleşim yerinde renklenme diş hekiminde düzeltme gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'digital-smile-design'), 'Digital planning of the appearance of a smile: from photographs and scans, the dentist models the shape and position of the future teeth before treatment starts', 'Digitalno planiranje izgleda osmijeha: na osnovu fotografija i skenova ljekar modeluje oblik i položaj budućih zuba prije početka liječenja', 'Дигитално планирање изгледа осмијеха: на основу фотографија и скенова љекар моделује облик и положај будућих зуба прије почетка лијечења', 'Цифровое планирование внешнего вида улыбки: по фотографиям и сканам врач моделирует форму и положение будущих зубов до начала лечения', 'Digitale Planung des Aussehens des Lächelns: anhand von Fotos und Scans modelliert der Zahnarzt Form und Stellung der künftigen Zähne, bevor die Behandlung beginnt', 'Gülüşün görünümünün dijital planlanması: hekim, fotoğraf ve taramalardan yola çıkarak tedaviye başlamadan önce gelecekteki dişlerin şeklini ve konumunu modeller', 'A photo protocol of the face and teeth, digital scanning, modeling in software, and a discussion of options with the patient; sometimes a trial mock-up is made and tried on the teeth', 'Fotoprotokol lica i zuba, digitalno skeniranje, modelovanje u programu i razgovor o varijantama sa pacijentom; ponekad se izrađuje probni maket koji se proba na zubima', 'Фотопротокол лица и зуба, дигитално скенирање, моделовање у програму и разговор о варијантама са пацијентом; понекад се израђује пробни макет који се проба на зубима', 'Фотопротокол лица и зубов, цифровое сканирование, моделирование в программе и обсуждение вариантов с пациентом; иногда изготавливается пробный макет, который примеряют на зубы', 'Fotoprotokoll von Gesicht und Zähnen, digitaler Scan, Modellierung in der Software und Besprechung der Varianten mit dem Patienten; teils wird ein Probemodell angefertigt und auf den Zähnen anprobiert', 'Yüz ve dişlerin fotoğraf protokolü, dijital tarama, programda modelleme ve seçeneklerin hastayla görüşülmesi; bazen dişlere prova edilen bir maket hazırlanır', 'Before aesthetic restoration of front teeth — veneers, crowns, comprehensive prosthetics; when seeing the result in advance matters', 'Prije estetske restauracije prednjih zuba — ljuspicama, krunicama, kompleksnom protetikom; kada je važno unaprijed vidjeti rezultat', 'Прије естетске рестаурације предњих зуба — љуспицама, круницама, комплексном протетиком; када је важно унапријед видјети резултат', 'Перед эстетической реставрацией передних зубов — винирами, коронками, комплексным протезированием; когда важно увидеть результат заранее', 'Vor der ästhetischen Versorgung der Frontzähne — Veneers, Kronen, umfassender Zahnersatz; wenn es wichtig ist, das Ergebnis vorab zu sehen', 'Ön dişlerin estetik restorasyonundan önce — kaplama, kron, kapsamlı protez; sonucu önceden görmenin önemli olduğu durumlar', 'Come without bright lipstick and ready for facial photographs; it helps to define beforehand what exactly you dislike about your current smile', 'Doći bez jarkog ruža, spreman za fotografisanje lica; korisno je unaprijed formulisati šta se konkretno ne voli na sadašnjem osmijehu', 'Доћи без јарког ружа, спреман за фотографисање лица; корисно је унапријед формулисати шта се конкретно не воли на садашњем осмијеху', 'Прийти без яркой помады, готовым к фотографированию лица; полезно заранее сформулировать, что именно не нравится в текущей улыбке', 'Ohne kräftigen Lippenstift kommen und auf Gesichtsfotos vorbereitet sein; hilfreich ist, vorab zu formulieren, was am aktuellen Lächeln konkret stört', 'Parlak ruj olmadan, yüz fotoğrafına hazır gelmek; mevcut gülüşte tam olarak neyin rahatsız ettiğini önceden belirlemek yararlıdır', 'The planning itself is painless; the model is a plan, not a guarantee — the final look depends on the condition of the teeth and gums and on the chosen materials, and is discussed with the dentist', 'Samo planiranje je bezbolno; rezultat modelovanja je plan, a ne garancija: konačan izgled zavisi od stanja zuba, desni i izabranih materijala i dogovara se sa ljekarom', 'Само планирање је безболно; резултат моделовања је план, а не гаранција: коначан изглед зависи од стања зуба, десни и изабраних материјала и договара се са љекаром', 'Само планирование безболезненно; результат моделирования — это план, а не гарантия: итоговый вид зависит от состояния зубов, дёсен и выбранных материалов, и обсуждается с врачом', 'Die Planung selbst ist schmerzfrei; das Modell ist ein Plan und keine Garantie — das Endergebnis hängt vom Zustand der Zähne und des Zahnfleischs sowie von den gewählten Materialien ab und wird mit dem Arzt abgestimmt', 'Planlamanın kendisi ağrısızdır; modelleme sonucu bir plandır, garanti değildir: nihai görünüm dişlerin ve diş etlerinin durumuna ve seçilen malzemelere bağlıdır, hekimle birlikte değerlendirilir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'hyaluronic-acid-filler'), 'Injection of a hyaluronic acid gel to restore volume and refine facial contours', 'Injekciono ubrizgavanje gela na osnovi hijaluronske kiseline radi vraćanja volumena i korekcije kontura lica', 'Ињекционо убризгавање гела на основи хијалуронске киселине ради враћања волумена и корекције контура лица', 'Инъекционное введение геля на основе гиалуроновой кислоты для восполнения объёма и коррекции контуров лица', 'Injektion eines Gels auf Basis von Hyaluronsäure, um Volumen wiederherzustellen und Gesichtskonturen zu korrigieren', 'Hacim kaybını gidermek ve yüz hatlarını düzeltmek için hyaluronik asit bazlı jelin enjeksiyonu', 'The skin is disinfected, an anesthetic cream is applied if needed, and the product is injected with a fine needle or cannula into the planned areas; the procedure takes 20-40 minutes', 'Koža se dezinfikuje, po potrebi se nanosi anestetička krema, a preparat se ubrizgava tankom iglom ili kanilom u planirane zone; procedura traje 20-40 minuta', 'Кожа се дезинфикује, по потреби се наноси анестетичка крема, а препарат се убризгава танком иглом или канилом у планиране зоне; процедура траје 20-40 минута', 'Кожу обрабатывают антисептиком, при необходимости наносят анестезирующий крем, препарат вводят тонкой иглой или канюлей в намеченные зоны; процедура занимает 20-40 минут', 'Die Haut wird desinfiziert, bei Bedarf eine Anästhesiecreme aufgetragen, und das Präparat wird mit einer feinen Nadel oder Kanüle in die geplanten Bereiche eingebracht; die Behandlung dauert 20-40 Minuten', 'Cilt dezenfekte edilir, gerekirse anestezik krem uygulanır, ürün ince iğne veya kanülle planlanan bölgelere verilir; işlem 20-40 dakika sürer', 'Age-related volume loss, nasolabial folds, reshaping of the lips, chin, and cheekbones — the areas and volume are determined by the doctor at the consultation', 'Gubitak volumena sa godinama, nazolabijalne bore, korekcija oblika usana, brade i jagodica — zone i količinu određuje ljekar na konsultaciji', 'Губитак волумена са годинама, назолабијалне боре, корекција облика усана, браде и јагодица — зоне и количину одређује љекар на консултацији', 'Возрастная потеря объёма, носогубные складки, коррекция формы губ, подбородка и скул — зоны и объём определяет врач на консультации', 'Altersbedingter Volumenverlust, Nasolabialfalten, Konturierung von Lippen, Kinn und Wangenknochen — Bereiche und Menge legt der Arzt im Beratungsgespräch fest', 'Yaşa bağlı hacim kaybı, nazolabial kıvrımlar, dudak, çene ve elmacık şeklinin düzeltilmesi — bölgeleri ve miktarı hekim muayenede belirler', 'For a few days beforehand, alcohol should be avoided and, as agreed with the doctor, medications that increase bleeding; report pregnancy, autoimmune conditions, a tendency to cold sores, and any previously injected products', 'Nekoliko dana prije treba izbjegavati alkohol i, u dogovoru sa ljekarom, lijekove koji povećavaju krvarenje; obavijestiti o trudnoći, autoimunim bolestima, sklonosti herpesu i ranije ubrizgavanim preparatima', 'Неколико дана прије треба избјегавати алкохол и, у договору са љекаром, лијекове који повећавају крварење; обавијестити о трудноћи, аутоимуним болестима, склоности херпесу и раније убризгаваним препаратима', 'За несколько дней стоит воздержаться от алкоголя и, по согласованию с врачом, от препаратов, повышающих кровоточивость; сообщить о беременности, аутоиммунных заболеваниях, склонности к герпесу и ранее введённых препаратах', 'Einige Tage vorher auf Alkohol und, in Absprache mit dem Arzt, auf blutungsfördernde Medikamente verzichten; Schwangerschaft, Autoimmunerkrankungen, Neigung zu Lippenherpes und früher injizierte Präparate mitteilen', 'İşlemden birkaç gün önce alkolden ve hekimle görüşerek kanamayı artıran ilaçlardan kaçınmak; gebelik, otoimmün hastalıklar, uçuk eğilimi ve daha önce uygulanmış ürünleri bildirmek', 'Swelling, redness, and bruising in the first 2-7 days are a normal reaction; blanching of the skin, severe pain, visual disturbances, as well as increasing asymmetry or lumps require immediate contact with the doctor who performed the procedure', 'Oticanje, crvenilo i modrice prvih 2-7 dana su uobičajena reakcija; bijeljenje kože, jaka bol, smetnje vida, kao i pojačana asimetrija ili čvorići zahtijevaju hitno obraćanje ljekaru koji je radio proceduru', 'Отицање, црвенило и модрице првих 2-7 дана су уобичајена реакција; бијељење коже, јака бол, сметње вида, као и појачана асиметрија или чворићи захтијевају хитно обраћање љекару који је радио процедуру', 'Отёк, покраснение и синяки в первые 2-7 дней — обычная реакция; побеление кожи, резкая боль, нарушение зрения, а также нарастающая асимметрия или уплотнения требуют немедленного обращения к врачу, который проводил процедуру', 'Schwellung, Rötung und Blutergüsse in den ersten 2-7 Tagen sind eine normale Reaktion; Abblassen der Haut, starke Schmerzen, Sehstörungen sowie zunehmende Asymmetrie oder Knötchen erfordern die sofortige Kontaktaufnahme mit dem behandelnden Arzt', 'İlk 2-7 günde şişlik, kızarıklık ve morluk normal tepkidir; ciltte solma, şiddetli ağrı, görme bozukluğu ile artan asimetri veya sertlikler işlemi yapan hekime derhal başvurmayı gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'hyaluronic-filler'), 'Injections of a hyaluronic filler to smooth folds and restore volume in a chosen facial area', 'Injekcije hijaluronskog filera radi ublažavanja bora i vraćanja volumena u izabranoj zoni lica', 'Ињекције хијалуронског филера ради ублажавања бора и враћања волумена у изабраној зони лица', 'Инъекции гиалуронового филлера для сглаживания складок и восстановления объёма в выбранной зоне лица', 'Injektionen eines Hyaluron-Fillers, um Falten zu glätten und Volumen in einem gewählten Gesichtsbereich wiederherzustellen', 'Seçilen yüz bölgesinde kıvrımları yumuşatmak ve hacim kazandırmak için hyaluronik dolgu enjeksiyonları', 'After the consultation and marking, the product is injected into or under the skin; 20-40 minutes, with the effect visible immediately and fully assessed after 1-2 weeks once the swelling subsides', 'Nakon konsultacije i obilježavanja, preparat se ubrizgava u kožu ili pod kožu; 20-40 minuta, efekat je vidljiv odmah, a konačno se procjenjuje nakon 1-2 nedjelje kada oticanje prođe', 'Након консултације и обиљежавања, препарат се убризгава у кожу или под кожу; 20-40 минута, ефекат је видљив одмах, а коначно се процјењује након 1-2 недјеље када отицање прође', 'После консультации и разметки препарат вводят инъекциями в кожу или под кожу; 20-40 минут, эффект виден сразу и окончательно оценивается через 1-2 недели, когда сойдёт отёк', 'Nach Beratung und Markierung wird das Präparat in oder unter die Haut injiziert; 20-40 Minuten, das Ergebnis ist sofort sichtbar und wird nach 1-2 Wochen endgültig beurteilt, wenn die Schwellung abgeklungen ist', 'Muayene ve işaretlemeden sonra ürün cilde veya cilt altına enjekte edilir; 20-40 dakika, etki hemen görülür ve şişlik geçtikten sonra 1-2 hafta içinde tam olarak değerlendirilir', 'Wrinkles and folds, loss of volume in the lips and cheekbones, contour asymmetry — the indications are determined by the doctor', 'Bore i brazde, izgubljen volumen usana i jagodica, asimetrija kontura — indikacije određuje ljekar', 'Боре и бразде, изгубљен волумен усана и јагодица, асиметрија контура — индикације одређује љекар', 'Морщины и складки, потеря объёма губ и скул, асимметрия контуров — показания определяет врач', 'Falten und Furchen, Volumenverlust an Lippen und Wangenknochen, Konturasymmetrien — die Indikation stellt der Arzt', 'Kırışıklık ve kıvrımlar, dudak ve elmacıkta hacim kaybı, hat asimetrisi — endikasyonu hekim belirler', 'Do not schedule the procedure right before important events (allow 2 weeks for swelling and bruising); report allergies, anticoagulant use, pregnancy, and breastfeeding', 'Ne planirati proceduru neposredno pred važne događaje (ostaviti 2 nedjelje zbog oticanja i modrica); obavijestiti o alergijama, uzimanju antikoagulanasa, trudnoći i dojenju', 'Не планирати процедуру непосредно пред важне догађаје (оставити 2 недјеље због отицања и модрица); обавијестити о алергијама, узимању антикоагуланаса, трудноћи и дојењу', 'Не планировать процедуру перед важными событиями (нужен запас 2 недели на отёк и синяки); сообщить об аллергиях, приёме антикоагулянтов, беременности и кормлении', 'Den Termin nicht unmittelbar vor wichtigen Anlässen legen (2 Wochen Puffer für Schwellung und Blutergüsse); Allergien, Einnahme von Antikoagulanzien, Schwangerschaft und Stillzeit mitteilen', 'İşlemi önemli etkinliklerin hemen öncesine planlamamak (şişlik ve morluk için 2 hafta pay bırakmak); alerjileri, kan sulandırıcı kullanımını, gebelik ve emzirmeyi bildirmek', 'Slight swelling, tenderness, and bruising in the first days are expected; with marked pain, blanching or a change in skin color, or impaired vision, contact the doctor immediately', 'Blago oticanje, osjetljivost i modrice prvih dana su očekivani; kod izražene boli, bijeljenja ili promjene boje kože i pogoršanja vida treba se odmah obratiti ljekaru', 'Благо отицање, осјетљивост и модрице првих дана су очекивани; код изражене боли, бијељења или промјене боје коже и погоршања вида треба се одмах обратити љекару', 'Небольшой отёк, чувствительность и синяки в первые дни ожидаемы; при выраженной боли, побелении или изменении цвета кожи, ухудшении зрения нужно немедленно связаться с врачом', 'Leichte Schwellung, Empfindlichkeit und Blutergüsse in den ersten Tagen sind zu erwarten; bei starken Schmerzen, Abblassen oder Farbveränderung der Haut sowie Sehverschlechterung sofort den Arzt kontaktieren', 'İlk günlerde hafif şişlik, hassasiyet ve morluk beklenir; belirgin ağrı, ciltte solma veya renk değişikliği ve görmede bozulma durumunda derhal hekime başvurmak gerekir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'hyaluronic-fillers-1ml'), 'Injection of one milliliter of hyaluronic filler — the standard unit by which the cost of treatment is usually calculated', 'Ubrizgavanje jednog mililitra hijaluronskog filera — standardna jedinica po kojoj se obično računa cijena korekcije', 'Убризгавање једног милилитра хијалуронског филера — стандардна јединица по којој се обично рачуна цијена корекције', 'Введение одного миллилитра гиалуронового филлера — стандартная единица, по которой обычно считается стоимость коррекции', 'Injektion von einem Milliliter Hyaluron-Filler — die Standardeinheit, nach der die Kosten der Behandlung meist berechnet werden', 'Bir mililitre hyaluronik dolgu uygulaması — işlem ücretinin genellikle hesaplandığı standart birim', 'The doctor injects the product from a 1 ml syringe into the agreed areas; one or several syringes may be used in one visit, depending on the plan', 'Ljekar ubrizgava preparat iz šprica od 1 ml u dogovorene zone; u jednoj posjeti može se koristiti jedan ili više špriceva, zavisno od plana', 'Љекар убризгава препарат из шприца од 1 мл у договорене зоне; у једној посјети може се користити један или више шприцева, зависно од плана', 'Врач вводит препарат из шприца объёмом 1 мл в согласованные зоны; за один визит может использоваться один или несколько шприцев, в зависимости от плана', 'Der Arzt injiziert das Präparat aus einer 1-ml-Spritze in die vereinbarten Bereiche; je nach Plan können in einem Termin eine oder mehrere Spritzen verwendet werden', 'Hekim, 1 ml şırıngadaki ürünü belirlenen bölgelere enjekte eder; plana göre tek seansta bir veya birkaç şırınga kullanılabilir', 'Correction of the lips, nasolabial folds, cheekbones, or chin; repeat treatments to maintain the result', 'Korekcija usana, nazolabijalnih bora, jagodica ili brade; ponovne procedure radi održavanja rezultata', 'Корекција усана, назолабијалних бора, јагодица или браде; поновне процедуре ради одржавања резултата', 'Коррекция губ, носогубных складок, скул или подбородка; повторные процедуры для поддержания результата', 'Korrektur von Lippen, Nasolabialfalten, Wangenknochen oder Kinn; Auffrischungen zur Erhaltung des Ergebnisses', 'Dudak, nazolabial kıvrım, elmacık veya çene düzeltmesi; sonucun korunması için tekrar uygulamalar', 'Check with the clinic how many milliliters your case requires — the final price depends on it; avoid alcohol for 2-3 days and, as agreed with the doctor, blood-thinning medications', 'Provjeriti u klinici koliko mililitara je potrebno u vašem slučaju — od toga zavisi konačan iznos; 2-3 dana prije izbjegavati alkohol i, u dogovoru sa ljekarom, lijekove za razrjeđivanje krvi', 'Провјерити у клиници колико милилитара је потребно у вашем случају — од тога зависи коначан износ; 2-3 дана прије избјегавати алкохол и, у договору са љекаром, лијекове за разрјеђивање крви', 'Уточнить у клиники, сколько миллилитров понадобится в вашем случае — итоговая сумма зависит от этого; за 2-3 дня исключить алкоголь и по согласованию с врачом кроверазжижающие препараты', 'In der Praxis klären, wie viele Milliliter in Ihrem Fall nötig sind — davon hängt der Endpreis ab; 2-3 Tage vorher Alkohol meiden und, in Absprache mit dem Arzt, blutverdünnende Medikamente', 'Sizin durumunuzda kaç mililitre gerektiğini klinikten teyit etmek — toplam tutar buna bağlıdır; 2-3 gün önce alkolden ve hekimle görüşerek kan sulandırıcılardan kaçınmak', 'Swelling and bruising in the first days are normal; persistent lumps, nodules, marked asymmetry, or pain require examination by the doctor who performed the procedure', 'Oticanje i modrice prvih dana su normalni; čvorići koji ne prolaze, izražena asimetrija ili bol zahtijevaju pregled kod ljekara koji je radio proceduru', 'Отицање и модрице првих дана су нормални; чворићи који не пролазе, изражена асиметрија или бол захтијевају преглед код љекара који је радио процедуру', 'Отёк и синяки первых дней — норма; сохраняющиеся уплотнения, узелки, выраженная асимметрия или боль требуют осмотра у врача, проводившего процедуру', 'Schwellung und Blutergüsse in den ersten Tagen sind normal; anhaltende Verhärtungen, Knötchen, ausgeprägte Asymmetrie oder Schmerzen erfordern eine Untersuchung beim behandelnden Arzt', 'İlk günlerde şişlik ve morluk normaldir; geçmeyen sertlikler, nodüller, belirgin asimetri veya ağrı işlemi yapan hekimin muayenesini gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'botox-injection'), 'An injection of a botulinum toxin product (Botox) that temporarily weakens the action of facial muscles', 'Injekcija preparata botulinum toksina (Botox) koji privremeno slabi rad mimičnih mišića', 'Ињекција препарата ботулинум токсина (Botox) који привремено слаби рад мимичних мишића', 'Инъекция препарата ботулинического токсина (Botox), который временно ослабляет работу мимических мышц', 'Eine Injektion eines Botulinumtoxin-Präparats (Botox), das die Aktivität der mimischen Muskulatur zeitweise abschwächt', 'Mimik kaslarının çalışmasını geçici olarak zayıflatan botulinum toksin ürününün (Botox) enjeksiyonu', 'The doctor marks the injection points and delivers the product with a fine needle into the muscles of the chosen area; 10-20 minutes, with the effect developing over 3-14 days and lasting several months', 'Ljekar obilježava tačke i tankom iglom ubrizgava preparat u mišiće izabrane zone; 10-20 minuta, efekat se razvija tokom 3-14 dana i traje nekoliko mjeseci', 'Љекар обиљежава тачке и танком иглом убризгава препарат у мишиће изабране зоне; 10-20 минута, ефекат се развија током 3-14 дана и траје неколико мјесеци', 'Врач намечает точки, вводит препарат тонкой иглой в мышцы выбранной зоны; 10-20 минут, эффект развивается в течение 3-14 дней и сохраняется несколько месяцев', 'Der Arzt markiert die Einstichpunkte und injiziert das Präparat mit einer feinen Nadel in die Muskeln des gewählten Bereichs; 10-20 Minuten, die Wirkung entwickelt sich über 3-14 Tage und hält einige Monate', 'Hekim noktaları işaretler ve ürünü ince iğneyle seçilen bölgenin kaslarına uygular; 10-20 dakika, etki 3-14 gün içinde gelişir ve birkaç ay sürer', 'Expression lines on the forehead, between the brows, and around the eyes; for medical indications also muscle spasms and excessive sweating — as prescribed by a doctor', 'Mimične bore čela, između obrva i oko očiju; po medicinskim indikacijama i spazmi mišića i pojačano znojenje — propisuje ljekar', 'Мимичне боре чела, између обрва и око очију; по медицинским индикацијама и спазми мишића и појачано знојење — прописује љекар', 'Мимические морщины лба, межбровья и вокруг глаз; по медицинским показаниям также спазмы мышц и повышенная потливость — назначает врач', 'Mimikfalten an Stirn, Zornesfalte und um die Augen; bei medizinischer Indikation auch Muskelspasmen und übermäßiges Schwitzen — auf ärztliche Verordnung', 'Alın, kaş arası ve göz çevresindeki mimik kırışıklıkları; tıbbi endikasyonlarda kas spazmları ve aşırı terleme — hekim kararıyla', 'Report neurological conditions, pregnancy and breastfeeding, and any aminoglycoside antibiotics; after the procedure, avoid bending over or lying down for 4 hours and avoid sport, sauna, and alcohol that day', 'Obavijestiti o neurološkim bolestima, trudnoći i dojenju, uzimanju aminoglikozidnih antibiotika; nakon procedure 4 sata se ne saginjati i ne ležati, tog dana izbjegavati sport, saunu i alkohol', 'Обавијестити о неуролошким болестима, трудноћи и дојењу, узимању аминогликозидних антибиотика; након процедуре 4 сата се не сагињати и не лежати, тог дана избјегавати спорт, сауну и алкохол', 'Сообщить о неврологических заболеваниях, беременности и кормлении, приёме антибиотиков-аминогликозидов; после процедуры 4 часа не наклоняться и не лежать, в этот день избегать спорта, сауны и алкоголя', 'Neurologische Erkrankungen, Schwangerschaft und Stillzeit sowie die Einnahme von Aminoglykosid-Antibiotika mitteilen; nach der Behandlung 4 Stunden nicht bücken oder hinlegen und am selben Tag Sport, Sauna und Alkohol meiden', 'Nörolojik hastalıkları, gebelik ve emzirmeyi, aminoglikozid antibiyotik kullanımını bildirmek; işlemden sonra 4 saat eğilmemek ve uzanmamak, o gün spor, sauna ve alkolden kaçınmak', 'Slight redness and pinpoint bruises at the injection sites are a normal reaction; drooping of an eyelid or brow, double vision, or marked asymmetry are reasons to contact the doctor promptly (such effects are reversible but need monitoring)', 'Blago crvenilo i tačkaste modrice na mjestima uboda su uobičajena reakcija; spuštanje vjeđe ili obrve, dvostruke slike, izražena asimetrija razlog su da se odmah obratite ljekaru (takvi efekti su prolazni, ali zahtijevaju nadzor)', 'Благо црвенило и тачкасте модрице на мјестима убода су уобичајена реакција; спуштање вјеђе или обрве, двоструке слике, изражена асиметрија разлог су да се одмах обратите љекару (такви ефекти су пролазни, али захтијевају надзор)', 'Небольшие покраснения и точечные синячки в местах укола — обычная реакция; опущение века или брови, двоение, выраженная асимметрия — повод сразу обратиться к врачу (такие эффекты обратимы, но требуют наблюдения)', 'Leichte Rötungen und punktförmige Blutergüsse an den Einstichstellen sind eine normale Reaktion; ein hängendes Augenlid oder eine hängende Braue, Doppelbilder oder eine ausgeprägte Asymmetrie sind ein Grund, den Arzt zeitnah zu kontaktieren (solche Effekte sind vorübergehend, bedürfen aber der Kontrolle)', 'Enjeksiyon yerlerinde hafif kızarıklık ve noktasal morluklar normal tepkidir; göz kapağı veya kaşın düşmesi, çift görme, belirgin asimetri hemen hekime başvurma nedenidir (bu etkiler geçicidir ancak izlem gerektirir)')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'botox-single-region'), 'Botulinum toxin injections in a single anatomical region — for example only the forehead, only the glabella, or only the area around the eyes', 'Injekcije botulinum toksina u jednu anatomsku zonu — na primjer samo čelo, samo između obrva ili samo područje oko očiju', 'Ињекције ботулинум токсина у једну анатомску зону — на примјер само чело, само између обрва или само подручје око очију', 'Инъекции ботулотоксина в одну анатомическую зону — например, только лоб, только межбровье или только область вокруг глаз', 'Botulinumtoxin-Injektionen in einer einzelnen anatomischen Region — zum Beispiel nur die Stirn, nur die Zornesfalte oder nur die Augenpartie', 'Tek anatomik bölgeye botulinum toksin enjeksiyonu — örneğin yalnızca alın, yalnızca kaş arası veya yalnızca göz çevresi', 'Skin disinfection, marking, and injection of the product into the muscles of the chosen region; 10-15 minutes, with the result appearing after a few days', 'Dezinfekcija kože, obilježavanje i ubrizgavanje preparata u mišiće izabrane zone; 10-15 minuta, rezultat se vidi nakon nekoliko dana', 'Дезинфекција коже, обиљежавање и убризгавање препарата у мишиће изабране зоне; 10-15 минута, резултат се види након неколико дана', 'Обработка кожи, разметка и введение препарата в мышцы выбранной зоны; 10-15 минут, результат проявляется через несколько дней', 'Desinfektion der Haut, Markierung und Injektion des Präparats in die Muskeln der gewählten Region; 10-15 Minuten, das Ergebnis zeigt sich nach einigen Tagen', 'Cildin dezenfeksiyonu, işaretleme ve ürünün seçilen bölgenin kaslarına uygulanması; 10-15 dakika, sonuç birkaç gün içinde ortaya çıkar', 'A first experience of the procedure, treatment of one specific region, or maintaining the result of earlier injections', 'Prvo iskustvo sa procedurom, korekcija jedne konkretne zone, održavanje rezultata prethodnih injekcija', 'Прво искуство са процедуром, корекција једне конкретне зоне, одржавање резултата претходних ињекција', 'Первое знакомство с процедурой, коррекция одной конкретной зоны, поддержание результата после предыдущих инъекций', 'Erste Erfahrung mit der Behandlung, Korrektur einer bestimmten Region oder Erhaltung des Ergebnisses früherer Injektionen', 'İşlemle ilk deneyim, tek bir bölgenin düzeltilmesi, önceki uygulamaların sonucunun korunması', 'Check with the clinic what exactly counts as a "region" and how many units of product are included in the price; no alcohol on the day of the procedure', 'Provjeriti u klinici šta se tačno smatra „zonom“ i koliko jedinica preparata ulazi u cijenu; na dan procedure ne piti alkohol', 'Провјерити у клиници шта се тачно сматра „зоном“ и колико јединица препарата улази у цијену; на дан процедуре не пити алкохол', 'Уточнить у клиники, что именно считается «зоной» и сколько единиц препарата входит в цену; в день процедуры не употреблять алкоголь', 'In der Praxis klären, was genau als "Region" gilt und wie viele Einheiten im Preis enthalten sind; am Behandlungstag keinen Alkohol trinken', '"Bölge" olarak tam olarak neyin sayıldığını ve fiyata kaç ünite ürün dahil olduğunu klinikten teyit etmek; işlem günü alkol almamak', 'Pinpoint redness and a mild headache in the first 24 hours are normal; asymmetry, a drooping eyelid, or unusual facial muscle weakness are reasons to see the doctor', 'Tačkasta crvenila i blaga glavobolja prvog dana su uobičajeni; asimetrija, spuštena vjeđa ili neobična slabost mišića lica razlog su za obraćanje ljekaru', 'Тачкаста црвенила и блага главобоља првог дана су уобичајени; асиметрија, спуштена вјеђа или необична слабост мишића лица разлог су за обраћање љекару', 'Точечные покраснения и лёгкая головная боль в первые сутки — обычное явление; асимметрия, опущение века или необычная слабость мышц лица — повод обратиться к врачу', 'Punktförmige Rötungen und leichte Kopfschmerzen am ersten Tag sind normal; Asymmetrie, ein hängendes Augenlid oder ungewöhnliche Schwäche der Gesichtsmuskulatur sind ein Grund, den Arzt aufzusuchen', 'İlk gün noktasal kızarıklık ve hafif baş ağrısı normaldir; asimetri, göz kapağı düşmesi veya yüz kaslarında olağan dışı güçsüzlük hekime başvurma nedenidir')
