INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'vistabel-botox'), 'Injections of Vistabel — a botulinum toxin type A product used to soften expression lines', 'Injekcije preparata Vistabel — botulinum toksina tipa A koji se koristi za ublažavanje mimičnih bora', 'Ињекције препарата Vistabel — ботулинум токсина типа А који се користи за ублажавање мимичних бора', 'Инъекции препарата Vistabel — botulinum toxin типа A, применяемый для коррекции мимических морщин', 'Injektionen von Vistabel — einem Botulinumtoxin-Typ-A-Präparat zur Abmilderung von Mimikfalten', 'Vistabel enjeksiyonları — mimik kırışıklıklarını yumuşatmak için kullanılan A tipi botulinum toksin ürünü', 'The doctor injects the product into the muscles of the planned area with a fine needle; 10-20 minutes, with the effect building over 3-14 days and gradually wearing off after several months', 'Ljekar tankom iglom ubrizgava preparat u mišiće planirane zone; 10-20 minuta, efekat raste tokom 3-14 dana i postepeno prolazi nakon nekoliko mjeseci', 'Љекар танком иглом убризгава препарат у мишиће планиране зоне; 10-20 минута, ефекат расте током 3-14 дана и постепено пролази након неколико мјесеци', 'Врач вводит препарат в мышцы намеченной зоны тонкой иглой; 10-20 минут, эффект нарастает в течение 3-14 дней и постепенно проходит через несколько месяцев', 'Der Arzt injiziert das Präparat mit einer feinen Nadel in die Muskeln des geplanten Bereichs; 10-20 Minuten, die Wirkung baut sich über 3-14 Tage auf und lässt nach einigen Monaten allmählich nach', 'Hekim ürünü ince iğneyle planlanan bölgenin kaslarına uygular; 10-20 dakika, etki 3-14 gün içinde artar ve birkaç ay sonra kademeli olarak geçer', 'Expression lines on the forehead and between the brows, and crow''s feet around the eyes', 'Mimične bore čela, između obrva i „pačje noge“ oko očiju', 'Мимичне боре чела, између обрва и „пачје ноге“ око очију', 'Мимические морщины лба, межбровья, «гусиные лапки» вокруг глаз', 'Mimikfalten an Stirn und Zornesfalte sowie Krähenfüße um die Augen', 'Alın ve kaş arası mimik kırışıklıkları, göz çevresindeki kaz ayakları', 'Report neuromuscular disorders, pregnancy, breastfeeding, and current medications; avoid alcohol, sport, and sauna on the day of the procedure', 'Obavijestiti o bolestima nervno-mišićnog sistema, trudnoći, dojenju i lijekovima koje uzimate; na dan procedure izbjegavati alkohol, sport i saunu', 'Обавијестити о болестима нервно-мишићног система, трудноћи, дојењу и лијековима које узимате; на дан процедуре избјегавати алкохол, спорт и сауну', 'Сообщить о заболеваниях нервно-мышечной системы, беременности, кормлении, принимаемых препаратах; в день процедуры избегать алкоголя, спорта и сауны', 'Erkrankungen des Nerven- und Muskelsystems, Schwangerschaft, Stillzeit und eingenommene Medikamente mitteilen; am Behandlungstag Alkohol, Sport und Sauna meiden', 'Sinir-kas sistemi hastalıklarını, gebelik, emzirme ve kullanılan ilaçları bildirmek; işlem günü alkol, spor ve saunadan kaçınmak', 'Small bruises and redness at the injection sites pass within a few days; a drooping eyelid or brow, double vision, or noticeable asymmetry require examination by the doctor who performed the procedure', 'Male modrice i crvenilo na mjestima uboda prolaze za nekoliko dana; spuštena vjeđa ili obrva, dvostruke slike ili primjetna asimetrija zahtijevaju pregled kod ljekara koji je radio proceduru', 'Мале модрице и црвенило на мјестима убода пролазе за неколико дана; спуштена вјеђа или обрва, двоструке слике или примјетна асиметрија захтијевају преглед код љекара који је радио процедуру', 'Небольшие синячки и покраснение в местах инъекций проходят за несколько дней; опущение века или брови, двоение или заметная асимметрия требуют осмотра у врача, который проводил процедуру', 'Kleine Blutergüsse und Rötungen an den Einstichstellen vergehen in wenigen Tagen; ein hängendes Augenlid oder eine hängende Braue, Doppelbilder oder eine merkliche Asymmetrie erfordern eine Untersuchung beim behandelnden Arzt', 'Enjeksiyon yerlerinde küçük morluklar ve kızarıklık birkaç günde geçer; göz kapağı veya kaş düşmesi, çift görme ya da belirgin asimetri işlemi yapan hekimin muayenesini gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'hyperhidrosis-botox-treatment'), 'Treatment of excessive sweating with botulinum toxin injections that temporarily block stimulation of the sweat glands', 'Liječenje pojačanog znojenja injekcijama botulinum toksina koji privremeno blokira stimulaciju žlijezda za pot', 'Лијечење појачаног знојења ињекцијама ботулинум токсина који привремено блокира стимулацију жлијезда за пот', 'Лечение повышенной потливости инъекциями ботулотоксина, который временно блокирует стимуляцию потовых желёз', 'Behandlung von übermäßigem Schwitzen mit Botulinumtoxin-Injektionen, die die Stimulation der Schweißdrüsen zeitweise blockieren', 'Ter bezlerinin uyarılmasını geçici olarak engelleyen botulinum toksin enjeksiyonlarıyla aşırı terlemenin tedavisi', 'The area is marked (armpits, palms, soles), local cooling or anesthesia is used if needed, and a series of superficial injections is given; 20-40 minutes, with the effect developing over 3-14 days and lasting several months', 'Zona se obilježava (pazuh, dlanovi, stopala), po potrebi se primjenjuje lokalno hlađenje ili anestezija, a zatim se daje serija površnih injekcija; 20-40 minuta, efekat se razvija za 3-14 dana i traje nekoliko mjeseci', 'Зона се обиљежава (пазух, дланови, стопала), по потреби се примјењује локално хлађење или анестезија, а затим се даје серија површних ињекција; 20-40 минута, ефекат се развија за 3-14 дана и траје неколико мјесеци', 'Зону размечают (подмышки, ладони, стопы), при необходимости применяют местное охлаждение или анестезию, затем делают серию поверхностных инъекций; 20-40 минут, эффект развивается за 3-14 дней и держится несколько месяцев', 'Der Bereich wird markiert (Achseln, Handflächen, Fußsohlen), bei Bedarf werden lokale Kühlung oder Betäubung eingesetzt und dann eine Serie oberflächlicher Injektionen gesetzt; 20-40 Minuten, die Wirkung entwickelt sich über 3-14 Tage und hält einige Monate', 'Bölge işaretlenir (koltuk altı, avuç içi, ayak tabanı), gerekirse yüzeysel soğutma veya anestezi uygulanır, ardından bir dizi yüzeyel enjeksiyon yapılır; 20-40 dakika, etki 3-14 günde gelişir ve birkaç ay sürer', 'Marked sweating of the armpits, palms, or soles that interferes with daily life, when antiperspirants and topical products do not help', 'Izraženo znojenje pazuha, dlanova ili stopala koje otežava svakodnevni život, kada antiperspiranti i lokalna sredstva ne pomažu', 'Изражено знојење пазуха, дланова или стопала које отежава свакодневни живот, када антиперспиранти и локална средства не помажу', 'Выраженная потливость подмышек, ладоней или стоп, мешающая в быту, когда антиперспиранты и местные средства не помогают', 'Ausgeprägtes Schwitzen an Achseln, Handflächen oder Fußsohlen, das den Alltag beeinträchtigt, wenn Antitranspirantien und lokale Mittel nicht helfen', 'Antiperspiran ve yüzeysel ürünlerin işe yaramadığı, günlük yaşamı zorlaştıran belirgin koltuk altı, avuç içi veya ayak tabanı terlemesi', 'Do not remove hair in the treatment area for a few days beforehand; report neurological and muscle disorders, pregnancy, and breastfeeding; the doctor may suggest a test to map the area', 'Nekoliko dana prije ne odstranjivati dlake u zoni tretmana; obavijestiti o neurološkim i mišićnim bolestima, trudnoći i dojenju; ljekar može predložiti test za određivanje granica zone', 'Неколико дана прије не одстрањивати длаке у зони третмана; обавијестити о неуролошким и мишићним болестима, трудноћи и дојењу; љекар може предложити тест за одређивање граница зоне', 'За несколько дней не удалять волосы в зоне обработки; сообщить о неврологических и мышечных заболеваниях, беременности и кормлении; врач может предложить пробу для определения границ зоны', 'Einige Tage vorher keine Haare im Behandlungsbereich entfernen; neurologische und muskuläre Erkrankungen, Schwangerschaft und Stillzeit mitteilen; der Arzt kann einen Test zur Abgrenzung des Bereichs vorschlagen', 'İşlemden birkaç gün önce bölgedeki tüyleri almamak; nörolojik ve kas hastalıklarını, gebelik ve emzirmeyi bildirmek; hekim bölgeyi belirlemek için test önerebilir', 'Mild soreness and redness at the injection sites are a normal reaction; with injections into the palms, temporary weakness of the small hand muscles is possible — report such changes, as well as increasing swelling, to the doctor', 'Blaga bol i crvenilo na mjestima uboda su uobičajena reakcija; kod injekcija u dlanove moguća je privremena slabost sitnih mišića ruke — o takvim promjenama, kao i o pojačanom oticanju, treba obavijestiti ljekara', 'Блага бол и црвенило на мјестима убода су уобичајена реакција; код ињекција у дланове могућа је привремена слабост ситних мишића руке — о таквим промјенама, као и о појачаном отицању, треба обавијестити љекара', 'Небольшая болезненность и покраснение в местах уколов — обычная реакция; при инъекциях в ладони возможна временная слабость мелких мышц кисти — о таких изменениях, а также о нарастании отёка нужно сообщить врачу', 'Leichte Schmerzen und Rötung an den Einstichstellen sind eine normale Reaktion; bei Injektionen in die Handflächen ist eine vorübergehende Schwäche der kleinen Handmuskeln möglich — solche Veränderungen sowie eine zunehmende Schwellung sollten dem Arzt mitgeteilt werden', 'Enjeksiyon yerlerinde hafif ağrı ve kızarıklık normal tepkidir; avuç içi uygulamalarında elin küçük kaslarında geçici güçsüzlük olabilir — bu değişiklikleri ve artan şişliği hekime bildirmek gerekir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'prp-facial-treatment'), 'A treatment using platelet-rich plasma (PRP) obtained from the patient''s own blood, injected into the skin of the face', 'Tretman sa plazmom bogatom trombocitima (PRP) dobijenom iz sopstvene krvi pacijenta, koja se ubrizgava u kožu lica', 'Третман са плазмом богатом тромбоцитима (PRP) добијеном из сопствене крви пацијента, која се убризгава у кожу лица', 'Процедура с использованием обогащённой тромбоцитами плазмы (PRP), полученной из собственной крови пациента, для инъекций в кожу лица', 'Eine Behandlung mit thrombozytenreichem Plasma (PRP) aus dem eigenen Blut des Patienten, das in die Gesichtshaut injiziert wird', 'Hastanın kendi kanından elde edilen trombositten zengin plazmanın (PRP) yüz cildine enjekte edildiği işlem', 'Blood is drawn from a vein, centrifuged to separate the plasma, and injected into the facial skin as micro-injections (sometimes combined with microneedling); the visit takes 45-60 minutes, and a course usually consists of several sessions', 'Vadi se krv iz vene, centrifugira radi izdvajanja plazme i ubrizgava mikroinjekcijama u kožu lica (ponekad u kombinaciji sa mikroiglicama); posjeta traje 45-60 minuta, a tretman se obično sastoji od nekoliko procedura', 'Вади се крв из вене, центрифугира ради издвајања плазме и убризгава микроињекцијама у кожу лица (понекад у комбинацији са микроиглицама); посјета траје 45-60 минута, а третман се обично састоји од неколико процедура', 'Берут кровь из вены, центрифугируют для выделения плазмы и вводят её микроинъекциями в кожу лица (иногда в сочетании с микронидлингом); визит занимает 45-60 минут, курс обычно из нескольких процедур', 'Es wird Blut aus einer Vene entnommen, zur Gewinnung des Plasmas zentrifugiert und in Mikroinjektionen in die Gesichtshaut eingebracht (teils in Kombination mit Microneedling); der Termin dauert 45-60 Minuten, eine Kur besteht meist aus mehreren Sitzungen', 'Damardan kan alınır, plazmayı ayırmak için santrifüj edilir ve yüz cildine mikroenjeksiyonlarla uygulanır (bazen mikro iğneleme ile birlikte); seans 45-60 dakika sürer, kür genellikle birkaç oturumdan oluşur', 'Dull skin, fine lines, reduced skin density; often as an addition to other methods — the plan is set by the doctor', 'Bezizražajna koža, sitne bore, smanjena gustina kože; često kao dopuna drugim metodama — plan određuje ljekar', 'Безизражајна кожа, ситне боре, смањена густина коже; често као допуна другим методама — план одређује љекар', 'Тусклая кожа, мелкие морщины, снижение плотности кожи; часто как дополнение к другим методам — план определяет врач', 'Fahle Haut, feine Fältchen, nachlassende Hautdichte; häufig als Ergänzung zu anderen Verfahren — den Plan legt der Arzt fest', 'Donuk cilt, ince çizgiler, cilt yoğunluğunun azalması; sıklıkla diğer yöntemlere ek olarak — planı hekim belirler', 'Come well rested and not fasting, and drink enough water; report clotting disorders, anticoagulant use, blood diseases, and active skin infections', 'Doći naspavan i ne na prazan stomak, piti dovoljno vode; obavijestiti o poremećajima zgrušavanja, uzimanju antikoagulanasa, bolestima krvi i aktivnim infekcijama kože', 'Доћи наспаван и не на празан стомак, пити довољно воде; обавијестити о поремећајима згрушавања, узимању антикоагуланаса, болестима крви и активним инфекцијама коже', 'Прийти выспавшимся и не натощак, пить достаточно воды; сообщить о нарушениях свёртывания, приёме антикоагулянтов, заболеваниях крови и активных инфекциях кожи', 'Ausgeschlafen und nicht nüchtern kommen, ausreichend Wasser trinken; Gerinnungsstörungen, Einnahme von Antikoagulanzien, Blutkrankheiten und aktive Hautinfektionen mitteilen', 'Dinlenmiş ve aç olmayarak gelmek, yeterli su içmek; pıhtılaşma bozukluklarını, kan sulandırıcı kullanımını, kan hastalıklarını ve aktif cilt enfeksiyonlarını bildirmek', 'Redness, swelling, and pinpoint bruises in the first 1-3 days are an expected reaction; increasing pain, pustules, or fever require a medical examination', 'Crvenilo, oticanje i tačkaste modrice prvih 1-3 dana su očekivana reakcija; bol koja se pojačava, gnojne promjene ili povišena temperatura zahtijevaju pregled kod ljekara', 'Црвенило, отицање и тачкасте модрице првих 1-3 дана су очекивана реакција; бол која се појачава, гнојне промјене или повишена температура захтијевају преглед код љекара', 'Покраснение, отёк и точечные синячки в первые 1-3 дня — ожидаемая реакция; усиливающаяся боль, гнойнички или температура требуют осмотра врача', 'Rötung, Schwellung und punktförmige Blutergüsse in den ersten 1-3 Tagen sind eine erwartete Reaktion; zunehmende Schmerzen, Pusteln oder Fieber erfordern eine ärztliche Untersuchung', 'İlk 1-3 günde kızarıklık, şişlik ve noktasal morluk beklenen tepkidir; artan ağrı, iltihaplı kabarcıklar veya ateş hekim muayenesi gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'scalp-mesotherapy'), 'A course of micro-injections into the scalp with a cocktail of vitamins, trace elements, and other substances selected by the doctor', 'Kura mikroinjekcija u kožu glave sa koktelom vitamina, mikroelemenata i drugih supstanci koji određuje ljekar', 'Кура микроињекција у кожу главе са коктелом витамина, микроелемената и других супстанци који одређује љекар', 'Курс микроинъекций в кожу головы с коктейлем витаминов, микроэлементов и других веществ, подобранным врачом', 'Eine Kur mit Mikroinjektionen in die Kopfhaut mit einem vom Arzt zusammengestellten Cocktail aus Vitaminen, Spurenelementen und weiteren Substanzen', 'Hekimin belirlediği vitamin, mineral ve diğer maddelerden oluşan karışımın saçlı deriye mikroenjeksiyonlarla uygulandığı kür', 'The scalp is disinfected and a series of superficial injections is given along parted lines; the session takes 20-30 minutes and is usually part of a course of several sessions 1-2 weeks apart', 'Koža glave se dezinfikuje i daje se serija površnih injekcija po razdjeljcima; procedura traje 20-30 minuta i obično se sprovodi kao kura od nekoliko seansi u intervalu od 1-2 nedjelje', 'Кожа главе се дезинфикује и даје се серија површних ињекција по раздјељцима; процедура траје 20-30 минута и обично се спроводи као кура од неколико сеанси у интервалу од 1-2 недјеље', 'Кожу головы обрабатывают антисептиком и делают серию поверхностных инъекций по проборам; процедура занимает 20-30 минут, обычно проводится курсом из нескольких сеансов с интервалом 1-2 недели', 'Die Kopfhaut wird desinfiziert und eine Serie oberflächlicher Injektionen entlang gezogener Scheitel gesetzt; die Sitzung dauert 20-30 Minuten und erfolgt meist als Kur mit mehreren Sitzungen im Abstand von 1-2 Wochen', 'Saçlı deri dezenfekte edilir ve ayrılan bölümler boyunca bir dizi yüzeyel enjeksiyon yapılır; seans 20-30 dakika sürer ve genellikle 1-2 hafta arayla birkaç oturumluk kür şeklinde uygulanır', 'Increased hair loss, thinning hair, or a scalp condition that needs support — after an examination establishing the cause', 'Pojačano opadanje kose, stanjivanje vlasi, stanje kože glave koje zahtijeva podršku — nakon pregleda i utvrđivanja uzroka', 'Појачано опадање косе, стањивање власи, стање коже главе које захтијева подршку — након прегледа и утврђивања узрока', 'Повышенное выпадение волос, истончение волос, состояние кожи головы, требующее поддержки — после обследования и выяснения причины', 'Verstärkter Haarausfall, dünner werdendes Haar oder ein Kopfhautzustand, der Unterstützung braucht — nach einer Untersuchung zur Klärung der Ursache', 'Artan saç dökülmesi, saç incelmesi, destek gerektiren saçlı deri durumu — muayene ve nedenin belirlenmesinden sonra', 'Wash the hair the day before or on the day of the procedure (check with the clinic); report scalp conditions, allergies, anticoagulant use, pregnancy, and breastfeeding', 'Oprati glavu dan prije ili na dan procedure (provjeriti u klinici); obavijestiti o bolestima kože glave, alergijama, uzimanju antikoagulanasa, trudnoći i dojenju', 'Опрати главу дан прије или на дан процедуре (провјерити у клиници); обавијестити о болестима коже главе, алергијама, узимању антикоагуланаса, трудноћи и дојењу', 'Помыть голову накануне или в день процедуры (уточнить в клинике); сообщить о заболеваниях кожи головы, аллергиях, приёме антикоагулянтов, беременности и кормлении', 'Die Haare am Vortag oder am Behandlungstag waschen (in der Praxis erfragen); Kopfhauterkrankungen, Allergien, Einnahme von Antikoagulanzien, Schwangerschaft und Stillzeit mitteilen', 'Saçı bir gün önce veya işlem günü yıkamak (klinikten teyit etmek); saçlı deri hastalıklarını, alerjileri, kan sulandırıcı kullanımını, gebelik ve emzirmeyi bildirmek', 'Mild tenderness, redness, and pinpoint crusts in the first days are a normal reaction; marked swelling, pustules, or increased hair loss are reasons to see a doctor and clarify the cause (hair loss is often related to general conditions and requires diagnosis)', 'Blaga bol, crvenilo i tačkaste kraste prvih dana su uobičajena reakcija; izraženo oticanje, gnojne promjene ili pojačano opadanje kose razlog su za pregled kod ljekara i utvrđivanje uzroka (opadanje kose je često povezano sa opštim stanjima i zahtijeva dijagnostiku)', 'Блага бол, црвенило и тачкасте красте првих дана су уобичајена реакција; изражено отицање, гнојне промјене или појачано опадање косе разлог су за преглед код љекара и утврђивање узрока (опадање косе је често повезано са општим стањима и захтијева дијагностику)', 'Небольшая болезненность, покраснение и точечные корочки в первые дни — обычная реакция; выраженный отёк, гнойнички или усиление выпадения волос — повод показаться врачу и уточнить причину (выпадение волос часто связано с общими состояниями и требует диагностики)', 'Leichte Schmerzempfindlichkeit, Rötung und punktförmige Krusten in den ersten Tagen sind eine normale Reaktion; deutliche Schwellung, Pusteln oder verstärkter Haarausfall sind ein Grund, einen Arzt aufzusuchen und die Ursache zu klären (Haarausfall hängt oft mit allgemeinen Erkrankungen zusammen und erfordert eine Diagnostik)', 'İlk günlerde hafif hassasiyet, kızarıklık ve noktasal kabuklanma normal tepkidir; belirgin şişlik, iltihaplı kabarcıklar veya saç dökülmesinin artması hekime başvurup nedeni araştırmayı gerektirir (saç dökülmesi sıklıkla genel durumlarla ilişkilidir ve tanı gerektirir)')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'lipolysis'), 'An injection procedure in which a product that breaks down fat cells is delivered into subcutaneous fat in a small, localized area', 'Injekciona procedura kod koje se u potkožno masno tkivo ubrizgava preparat koji razgrađuje masne ćelije u manjoj lokalnoj zoni', 'Ињекциона процедура код које се у поткожно масно ткиво убризгава препарат који разграђује масне ћелије у мањој локалној зони', 'Инъекционная процедура, при которой в подкожную жировую ткань вводят препарат, разрушающий жировые клетки в небольшой локальной зоне', 'Eine Injektionsbehandlung, bei der ein Präparat, das Fettzellen auflöst, in das Unterhautfettgewebe eines kleinen, begrenzten Bereichs eingebracht wird', 'Küçük ve sınırlı bir bölgede yağ hücrelerini çözen bir ürünün deri altı yağ dokusuna enjekte edildiği işlem', 'The area is marked and a series of injections is given; 20-40 minutes, usually requiring a course of several sessions a few weeks apart', 'Zona se obilježava i daje se serija injekcija preparata; 20-40 minuta, obično je potrebna kura od nekoliko procedura u intervalu od nekoliko nedjelja', 'Зона се обиљежава и даје се серија ињекција препарата; 20-40 минута, обично је потребна кура од неколико процедура у интервалу од неколико недјеља', 'Зону размечают и делают серию инъекций препарата; 20-40 минут, обычно требуется курс из нескольких процедур с интервалом в несколько недель', 'Der Bereich wird markiert und eine Serie von Injektionen gesetzt; 20-40 Minuten, in der Regel ist eine Kur mit mehreren Sitzungen im Abstand von einigen Wochen erforderlich', 'Bölge işaretlenir ve bir dizi enjeksiyon yapılır; 20-40 dakika, genellikle birkaç hafta arayla birkaç oturumluk kür gerekir', 'Localized fat deposits that persist at a normal body weight — a double chin, the area below the shoulder blades, small areas on the body; it is not a treatment for general excess weight', 'Lokalne masne naslage koje ostaju i pri normalnoj tjelesnoj masi — podvaljak, zona ispod lopatica, manja područja na tijelu; nije metoda za liječenje opšte prekomjerne težine', 'Локалне масне наслаге које остају и при нормалној тјелесној маси — подваљак, зона испод лопатица, мања подручја на тијелу; није метода за лијечење опште прекомјерне тежине', 'Локальные жировые отложения, которые не уходят при нормальном весе — второй подбородок, зона под лопатками, небольшие участки на теле; не метод лечения общего избыточного веса', 'Lokale Fettdepots, die bei normalem Körpergewicht bestehen bleiben — Doppelkinn, Bereich unter den Schulterblättern, kleine Areale am Körper; kein Verfahren zur Behandlung von allgemeinem Übergewicht', 'Normal kiloda da kalan bölgesel yağ birikimleri — çene altı, kürek kemiği altı, vücutta küçük alanlar; genel fazla kilonun tedavi yöntemi değildir', 'A consultation with assessment of general health; report liver and gallbladder disease, autoimmune conditions, pregnancy, and breastfeeding; ask in advance which product is used', 'Konsultacija sa procjenom opšteg stanja; obavijestiti o bolestima jetre i žučne kese, autoimunim bolestima, trudnoći i dojenju; unaprijed pitati koji se preparat koristi', 'Консултација са процјеном општег стања; обавијестити о болестима јетре и жучне кесе, аутоимуним болестима, трудноћи и дојењу; унапријед питати који се препарат користи', 'Консультация с оценкой общего состояния; сообщить о заболеваниях печени, желчного пузыря, аутоиммунных болезнях, беременности и кормлении; заранее спросить, какой именно препарат используется', 'Beratungsgespräch mit Beurteilung des Allgemeinzustands; Erkrankungen von Leber und Gallenblase, Autoimmunerkrankungen, Schwangerschaft und Stillzeit mitteilen; vorab erfragen, welches Präparat verwendet wird', 'Genel durumun değerlendirildiği muayene; karaciğer ve safra kesesi hastalıklarını, otoimmün hastalıkları, gebelik ve emzirmeyi bildirmek; hangi ürünün kullanıldığını önceden sormak', 'Swelling, redness, tenderness, and firmness in the treated area over the first days to weeks are an expected reaction; increasing pain, fever, marked redness, or skin irregularities require a medical examination', 'Oticanje, crvenilo, bol i čvrstina u zoni tretmana prvih dana do nedjelja su očekivana reakcija; bol koja se pojačava, povišena temperatura, izraženo crvenilo ili neravnine kože zahtijevaju pregled kod ljekara', 'Отицање, црвенило, бол и чврстина у зони третмана првих дана до недјеља су очекивана реакција; бол која се појачава, повишена температура, изражено црвенило или неравнине коже захтијевају преглед код љекара', 'Отёк, покраснение, болезненность и уплотнение в зоне обработки в первые дни-недели — ожидаемая реакция; нарастающая боль, температура, выраженное покраснение или неровности кожи требуют осмотра врача', 'Schwellung, Rötung, Druckempfindlichkeit und Verhärtung im behandelten Bereich in den ersten Tagen bis Wochen sind eine erwartete Reaktion; zunehmende Schmerzen, Fieber, deutliche Rötung oder Unebenheiten der Haut erfordern eine ärztliche Untersuchung', 'İlk günlerde ve haftalarda uygulama bölgesinde şişlik, kızarıklık, hassasiyet ve sertlik beklenen tepkidir; artan ağrı, ateş, belirgin kızarıklık veya ciltte düzensizlik hekim muayenesi gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'otoplasty'), 'Plastic surgery to change the shape and position of the ears — most often to correct prominent ears', 'Plastična operacija za promjenu oblika i položaja ušnih školjki — najčešće radi korekcije klempavih ušiju', 'Пластична операција за промјену облика и положаја ушних шкољки — најчешће ради корекције клемпавих ушију', 'Пластическая операция по изменению формы и положения ушных раковин — чаще всего для коррекции оттопыренных ушей', 'Plastische Operation zur Veränderung von Form und Lage der Ohren — meist zur Korrektur abstehender Ohren', 'Kulakların şeklini ve konumunu değiştiren estetik cerrahi — çoğunlukla kepçe kulak düzeltmesi için', 'Usually under local anesthesia (in children with sedation or general anesthesia): an incision behind the ear, reshaping of the cartilage, sutures, and a supportive dressing; 1-2 hours, most often going home the same day', 'Obično u lokalnoj anesteziji (kod djece sa sedacijom ili opštom anestezijom): rez iza uha, promjena oblika hrskavice, šavovi i fiksirajući zavoj; 1-2 sata, najčešće se kući ide istog dana', 'Обично у локалној анестезији (код дјеце са седацијом или општом анестезијом): рез иза уха, промјена облика хрскавице, шавови и фиксирајући завој; 1-2 сата, најчешће се кући иде истог дана', 'Обычно под местной анестезией (у детей — с седацией или общим наркозом): разрез за ухом, изменение формы хряща, наложение швов и фиксирующая повязка; 1-2 часа, домой чаще всего в тот же день', 'Meist unter Lokalanästhesie (bei Kindern mit Sedierung oder Vollnarkose): Schnitt hinter dem Ohr, Umformung des Knorpels, Nähte und ein stützender Verband; 1-2 Stunden, meist noch am selben Tag nach Hause', 'Genellikle lokal anestezi altında (çocuklarda sedasyon veya genel anestezi): kulak arkasından kesi, kıkırdağın yeniden şekillendirilmesi, dikişler ve destekleyici sargı; 1-2 saat, çoğunlukla aynı gün eve dönülür', 'Prominent ears, asymmetry of the ears, shape deformities — the indications and suitable age are discussed with the surgeon', 'Klempave uši, asimetrija ušnih školjki, deformiteti oblika — indikacije i odgovarajući uzrast dogovaraju se sa hirurgom', 'Клемпаве уши, асиметрија ушних шкољки, деформитети облика — индикације и одговарајући узраст договарају се са хирургом', 'Оттопыренные уши, асимметрия ушных раковин, деформации формы — показания и подходящий возраст обсуждаются с хирургом', 'Abstehende Ohren, Asymmetrie der Ohrmuscheln, Formveränderungen — Indikation und passendes Alter werden mit dem Chirurgen besprochen', 'Kepçe kulak, kulaklar arası asimetri, şekil bozuklukları — endikasyon ve uygun yaş cerrahla görüşülür', 'Preoperative tests and an anesthesiologist consultation, stopping blood thinners as agreed with the doctor, washing the hair the day before; plan for 1-2 weeks with a supportive dressing and no sport', 'Preoperativne analize i konsultacija sa anesteziologom, prekid lijekova za razrjeđivanje krvi u dogovoru sa ljekarom, oprati glavu dan prije; planirati 1-2 nedjelje sa fiksirajućim zavojem i bez sporta', 'Преоперативне анализе и консултација са анестезиологом, прекид лијекова за разрјеђивање крви у договору са љекаром, опрати главу дан прије; планирати 1-2 недјеље са фиксирајућим завојем и без спорта', 'Предоперационные анализы и консультация анестезиолога, отказ от кроверазжижающих препаратов по согласованию с врачом, вымыть голову накануне; спланировать 1-2 недели с фиксирующей повязкой и без спорта', 'Präoperative Untersuchungen und Anästhesiegespräch, Absetzen blutverdünnender Medikamente in Absprache mit dem Arzt, Haarwäsche am Vortag; 1-2 Wochen mit stützendem Verband und ohne Sport einplanen', 'Ameliyat öncesi tetkikler ve anestezi uzmanı görüşmesi, hekimle görüşerek kan sulandırıcıların kesilmesi, bir gün önce saçın yıkanması; destekleyici sargıyla ve sporsuz 1-2 hafta planlamak', 'Swelling, bruising, and a feeling of tightness in the first weeks are a normal reaction; sharp pain, increasing swelling on one side, bleeding, or fever require immediate contact with the surgeon', 'Oticanje, modrice i osjećaj zatezanja prvih nedjelja su uobičajena reakcija; jaka bol, pojačano oticanje sa jedne strane, krvarenje ili povišena temperatura zahtijevaju hitno obraćanje hirurgu', 'Отицање, модрице и осјећај затезања првих недјеља су уобичајена реакција; јака бол, појачано отицање са једне стране, крварење или повишена температура захтијевају хитно обраћање хирургу', 'Отёк, синяки и чувство натяжения в первые недели — обычная реакция; резкая боль, нарастающий отёк с одной стороны, кровотечение или температура требуют немедленного обращения к хирургу', 'Schwellung, Blutergüsse und ein Spannungsgefühl in den ersten Wochen sind eine normale Reaktion; starke Schmerzen, einseitig zunehmende Schwellung, Blutung oder Fieber erfordern die sofortige Kontaktaufnahme mit dem Chirurgen', 'İlk haftalarda şişlik, morluk ve gerginlik hissi normal tepkidir; şiddetli ağrı, tek tarafta artan şişlik, kanama veya ateş cerraha derhal başvurmayı gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'rhinoplasty'), 'Plastic surgery to change the shape of the nose — the bridge, the tip, or the width of the nostrils', 'Plastična operacija za promjenu oblika nosa — hrbata, vrha, širine krila', 'Пластична операција за промјену облика носа — хрбата, врха, ширине крила', 'Пластическая операция по изменению формы носа — спинки, кончика, ширины крыльев', 'Plastische Operation zur Veränderung der Nasenform — Nasenrücken, Nasenspitze, Breite der Nasenflügel', 'Burnun şeklini — sırtını, ucunu, kanat genişliğini — değiştiren estetik cerrahi', 'Under general anesthesia (less often local with sedation), the surgeon reshapes the cartilage and bony part of the nose through incisions inside the nose or at the columella, then places packing, a splint, or tape support; 1.5-3 hours, usually 1 day in hospital', 'U opštoj anesteziji (rjeđe lokalnoj sa sedacijom) hirurg mijenja hrskavice i koštani dio nosa kroz rezove unutar nosa ili u području kolumele, a zatim postavlja tampone, splint ili fiksaciju flasterom; 1,5-3 sata, obično 1 dan u bolnici', 'У општој анестезији (рјеђе локалној са седацијом) хирург мијења хрскавице и коштани дио носа кроз резове унутар носа или у подручју колумеле, а затим поставља тампоне, сплинт или фиксацију фластером; 1,5-3 сата, обично 1 дан у болници', 'Под общей анестезией (реже местной с седацией) хирург изменяет хрящи и костную часть носа через разрезы внутри носа или в области колумеллы, затем накладывает тампоны, шину или пластырную фиксацию; 1,5-3 часа, обычно 1 день в стационаре', 'Unter Vollnarkose (seltener Lokalanästhesie mit Sedierung) formt der Chirurg Knorpel und Knochenanteil der Nase über Schnitte im Naseninneren oder am Nasensteg um und legt danach Tamponaden, eine Schiene oder Pflasterfixierung an; 1,5-3 Stunden, meist 1 Tag im Krankenhaus', 'Genel anestezi altında (daha seyrek sedasyonla lokal) cerrah, burun içinden veya kolumelladan yapılan kesilerle kıkırdakları ve kemik bölümü yeniden şekillendirir, ardından tampon, splint veya bant desteği uygular; 1,5-3 saat, genellikle 1 gün hastanede', 'A nose shape the patient is unhappy with, the consequences of injury, asymmetry — the surgical plan is discussed at the consultation', 'Oblik nosa kojim pacijent nije zadovoljan, posljedice povreda, asimetrija — plan operacije se dogovara na konsultaciji sa hirurgom', 'Облик носа којим пацијент није задовољан, посљедице повреда, асиметрија — план операције се договара на консултацији са хирургом', 'Форма носа, которая не устраивает пациента, последствия травм, асимметрия — план операции обсуждается на консультации с хирургом', 'Eine Nasenform, mit der der Patient unzufrieden ist, Folgen von Verletzungen, Asymmetrien — der Operationsplan wird im Beratungsgespräch festgelegt', 'Hastanın memnun olmadığı burun şekli, travma sonuçları, asimetri — ameliyat planı cerrahla görüşmede belirlenir', 'Preoperative work-up, an anesthesiologist consultation, stopping smoking and blood thinners as agreed with the doctor; plan 1-2 weeks off work and 4-6 weeks without physical exertion', 'Pregledi prije operacije, konsultacija sa anesteziologom, prestanak pušenja i lijekova za razrjeđivanje krvi u dogovoru sa ljekarom; planirati 1-2 nedjelje bez rada i 4-6 nedjelja bez fizičkih napora', 'Прегледи прије операције, консултација са анестезиологом, престанак пушења и лијекова за разрјеђивање крви у договору са љекаром; планирати 1-2 недјеље без рада и 4-6 недјеља без физичких напора', 'Обследование перед операцией, консультация анестезиолога, отказ от курения и кроверазжижающих препаратов по согласованию с врачом; спланировать 1-2 недели без работы и 4-6 недель без физических нагрузок', 'Voruntersuchungen, Anästhesiegespräch, Rauchstopp und Absetzen blutverdünnender Medikamente in Absprache mit dem Arzt; 1-2 Wochen Arbeitspause und 4-6 Wochen ohne körperliche Anstrengung einplanen', 'Ameliyat öncesi tetkikler, anestezi uzmanı görüşmesi, hekimle görüşerek sigaranın ve kan sulandırıcıların bırakılması; 1-2 hafta işten uzak kalmayı ve 4-6 hafta ağır efordan kaçınmayı planlamak', 'Swelling and bruising around the eyes and a blocked nose in the first 1-2 weeks are a normal reaction; the final shape takes months to settle; heavy bleeding, fever, or increasing pain require immediate contact with the surgeon', 'Oticanje i modrice oko očiju, zapušen nos prvih 1-2 nedjelje su uobičajena reakcija; konačan oblik se formira mjesecima; jako krvarenje, povišena temperatura ili bol koja se pojačava zahtijevaju hitno obraćanje hirurgu', 'Отицање и модрице око очију, запушен нос првих 1-2 недјеље су уобичајена реакција; коначан облик се формира мјесецима; јако крварење, повишена температура или бол која се појачава захтијевају хитно обраћање хирургу', 'Отёк и синяки вокруг глаз, заложенность носа в первые 1-2 недели — обычная реакция; окончательная форма формируется месяцами; сильное кровотечение, температура или нарастающая боль требуют немедленного обращения к хирургу', 'Schwellung und Blutergüsse um die Augen sowie eine verstopfte Nase in den ersten 1-2 Wochen sind eine normale Reaktion; die endgültige Form bildet sich über Monate; starke Blutung, Fieber oder zunehmende Schmerzen erfordern die sofortige Kontaktaufnahme mit dem Chirurgen', 'İlk 1-2 haftada göz çevresinde şişlik, morluk ve burun tıkanıklığı normal tepkidir; nihai şekil aylar içinde oturur; şiddetli kanama, ateş veya artan ağrı cerraha derhal başvurmayı gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'rhinoplasty-with-septoplasty'), 'A combined operation: reshaping the nose and straightening a deviated septum that impairs breathing', 'Istovremena operacija: promjena oblika nosa i ispravljanje iskrivljene nosne pregrade koja otežava disanje', 'Истовремена операција: промјена облика носа и исправљање искривљене носне преграде која отежава дисање', 'Одновременная операция: изменение формы носа и исправление искривлённой носовой перегородки, мешающей дыханию', 'Ein kombinierter Eingriff: Veränderung der Nasenform und Korrektur einer verkrümmten Nasenscheidewand, die die Atmung behindert', 'Birlikte yapılan ameliyat: burnun şeklinin değiştirilmesi ve solunumu güçleştiren eğri burun bölmesinin düzeltilmesi', 'Under general anesthesia the surgeon straightens the septum and at the same time changes the external shape of the nose, then places packing or silicone splints and an external splint; 2-3.5 hours, usually 1 day in hospital', 'U opštoj anesteziji hirurg ispravlja pregradu i istovremeno mijenja vanjski oblik nosa, a zatim postavlja tampone ili silikonske splintove i vanjsku šinu; 2-3,5 sata, obično 1 dan u bolnici', 'У општој анестезији хирург исправља преграду и истовремено мијења вањски облик носа, а затим поставља тампоне или силиконске сплинтове и вањску шину; 2-3,5 сата, обично 1 дан у болници', 'Под общей анестезией хирург выпрямляет перегородку и одновременно изменяет наружную форму носа, затем устанавливает тампоны или силиконовые сплинты и внешнюю шину; 2-3,5 часа, обычно 1 день в стационаре', 'Unter Vollnarkose richtet der Chirurg die Nasenscheidewand und verändert gleichzeitig die äußere Nasenform, danach werden Tamponaden oder Silikonschienen und eine äußere Schiene eingesetzt; 2-3,5 Stunden, meist 1 Tag im Krankenhaus', 'Genel anestezi altında cerrah bölmeyi düzeltir ve aynı zamanda burnun dış şeklini değiştirir, ardından tampon veya silikon splintler ile dış atel uygular; 2-3,5 saat, genellikle 1 gün hastanede', 'A combination of an aesthetic request and impaired nasal breathing, or a deviated septum after injury', 'Kombinacija estetskog zahtjeva i otežanog disanja na nos, iskrivljena pregrada nakon povrede', 'Комбинација естетског захтјева и отежаног дисања на нос, искривљена преграда након повреде', 'Сочетание эстетического запроса и затруднённого носового дыхания, искривление перегородки после травмы', 'Kombination aus ästhetischem Wunsch und behinderter Nasenatmung, Nasenscheidewandverkrümmung nach einer Verletzung', 'Estetik talep ile burun tıkanıklığının bir arada olması, travma sonrası bölme eğriliği', 'Work-up and an anesthesiologist consultation, an ENT examination of the nose; stopping smoking; plan 1-2 weeks of recovery, with nasal breathing restricted in the first days', 'Pregledi i konsultacija sa anesteziologom, ORL pregled nosa; prestanak pušenja; planirati 1-2 nedjelje oporavka, prvih dana će disanje na nos biti otežano', 'Прегледи и консултација са анестезиологом, ОРЛ преглед носа; престанак пушења; планирати 1-2 недјеље опоравка, првих дана ће дисање на нос бити отежано', 'Обследование и консультация анестезиолога, ЛОР-осмотр носа; отказ от курения; спланировать 1-2 недели восстановления, первые дни дыхание через нос будет затруднено', 'Voruntersuchungen und Anästhesiegespräch, HNO-Untersuchung der Nase; Rauchstopp; 1-2 Wochen Erholung einplanen, in den ersten Tagen ist die Nasenatmung eingeschränkt', 'Tetkikler ve anestezi uzmanı görüşmesi, KBB burun muayenesi; sigaranın bırakılması; 1-2 hafta iyileşme planlamak, ilk günlerde burundan solunum kısıtlı olur', 'Congestion, swelling, and bruising in the first 1-2 weeks are expected; heavy bleeding, high fever, purulent discharge, or a sharp increase in pain is a reason to contact the surgeon urgently', 'Zapušenost, oticanje i modrice prvih 1-2 nedjelje su očekivani; obilno krvarenje, visoka temperatura, gnojni iscjedak ili naglo jačanje boli razlog su za hitan kontakt sa hirurgom', 'Запушеност, отицање и модрице првих 1-2 недјеље су очекивани; обилно крварење, висока температура, гнојни исцједак или нагло јачање боли разлог су за хитан контакт са хирургом', 'Заложенность, отёк и синяки в первые 1-2 недели ожидаемы; обильное кровотечение, высокая температура, гнойные выделения или резкое усиление боли — повод срочно связаться с хирургом', 'Verstopfung, Schwellung und Blutergüsse in den ersten 1-2 Wochen sind zu erwarten; starke Blutung, hohes Fieber, eitriges Sekret oder ein plötzlich stärkerer Schmerz sind ein Grund, den Chirurgen sofort zu kontaktieren', 'İlk 1-2 haftada tıkanıklık, şişlik ve morluk beklenir; yoğun kanama, yüksek ateş, iltihaplı akıntı veya ağrının aniden artması cerraha acilen başvurma nedenidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'blepharoplasty'), 'Plastic surgery of the eyelids: removal of excess skin and, if needed, fat pads around the eyes', 'Plastična operacija vjeđa: uklanjanje viška kože i, po potrebi, masnih jastučića oko očiju', 'Пластична операција вјеђа: уклањање вишка коже и, по потреби, масних јастучића око очију', 'Пластическая операция на веках: удаление избытка кожи и, при необходимости, жировых грыж вокруг глаз', 'Plastische Operation der Augenlider: Entfernung überschüssiger Haut und bei Bedarf von Fettpolstern um die Augen', 'Göz kapaklarının estetik cerrahisi: fazla derinin ve gerekirse göz çevresindeki yağ yastıklarının alınması', 'Usually under local anesthesia: an incision in the natural crease of the upper lid or just below the lash line of the lower lid, removal of excess tissue, and fine sutures; 45-90 minutes, home the same day', 'Obično u lokalnoj anesteziji: rez u prirodnoj brazdi gornje vjeđe ili ispod linije trepavica donje, uklanjanje viška tkiva i tanki šavovi; 45-90 minuta, kući istog dana', 'Обично у локалној анестезији: рез у природној бразди горње вјеђе или испод линије трепавица доње, уклањање вишка ткива и танки шавови; 45-90 минута, кући истог дана', 'Обычно под местной анестезией: разрез по естественной складке верхнего века или под ресничным краем нижнего, удаление избытка тканей и тонкие швы; 45-90 минут, домой в тот же день', 'Meist unter Lokalanästhesie: Schnitt in der natürlichen Falte des Oberlids oder knapp unter der Wimpernkante des Unterlids, Entfernung des Gewebeüberschusses und feine Nähte; 45-90 Minuten, am selben Tag nach Hause', 'Genellikle lokal anestezi altında: üst kapağın doğal kıvrımından veya alt kapağın kirpik hattının altından kesi, fazla dokunun alınması ve ince dikişler; 45-90 dakika, aynı gün eve dönüş', 'Drooping skin of the upper lids (including when it narrows the field of vision), bags under the eyes, marked age-related changes of the lids', 'Nadvijena koža gornjih vjeđa (uključujući i kada sužava vidno polje), „vrećice“ pod očima, izražene promjene vjeđa sa godinama', 'Надвијена кожа горњих вјеђа (укључујући и када сужава видно поље), „врећице“ под очима, изражене промјене вјеђа са годинама', 'Нависание кожи верхних век (в том числе если оно сужает поле зрения), «мешки» под глазами, выраженные возрастные изменения век', 'Hängende Haut der Oberlider (auch wenn sie das Gesichtsfeld einengt), Tränensäcke, ausgeprägte altersbedingte Lidveränderungen', 'Üst kapaklarda sarkan deri (görme alanını daralttığı durumlar dahil), göz altı torbaları, kapaklarda belirgin yaşa bağlı değişiklikler', 'An ophthalmologist''s examination if there are eye complaints, preoperative tests, stopping blood thinners as agreed with the doctor; put off make-up and contact lenses for 1-2 weeks', 'Pregled oftalmologa kod smetnji sa očima, preoperativne analize, prekid lijekova za razrjeđivanje krvi u dogovoru sa ljekarom; odložiti šminku i kontaktna sočiva 1-2 nedjelje', 'Преглед офталмолога код сметњи са очима, преоперативне анализе, прекид лијекова за разрјеђивање крви у договору са љекаром; одложити шминку и контактна сочива 1-2 недјеље', 'Осмотр офтальмологом при жалобах на глаза, предоперационные анализы, отказ от кроверазжижающих препаратов по согласованию с врачом; на 1-2 недели отложить макияж и контактные линзы', 'Augenärztliche Untersuchung bei Augenbeschwerden, präoperative Tests, Absetzen blutverdünnender Medikamente in Absprache mit dem Arzt; Make-up und Kontaktlinsen für 1-2 Wochen aussetzen', 'Göz şikâyeti varsa göz hekimi muayenesi, ameliyat öncesi tetkikler, hekimle görüşerek kan sulandırıcıların kesilmesi; 1-2 hafta makyaj ve kontakt lensi bırakmak', 'Swelling, bruising, a feeling of tightness, and dry eyes in the first 1-2 weeks are a normal reaction; sharp pain, reduced vision, increasing swelling, or bleeding require immediate medical attention', 'Oticanje, modrice, osjećaj zatezanja i suhoća očiju prvih 1-2 nedjelje su uobičajena reakcija; jaka bol, slabljenje vida, pojačano oticanje ili krvarenje zahtijevaju hitno obraćanje ljekaru', 'Отицање, модрице, осјећај затезања и сухоћа очију првих 1-2 недјеље су уобичајена реакција; јака бол, слабљење вида, појачано отицање или крварење захтијевају хитно обраћање љекару', 'Отёк, синяки, чувство натяжения и сухость глаз в первые 1-2 недели — обычная реакция; резкая боль, снижение зрения, нарастающий отёк или кровотечение требуют немедленного обращения к врачу', 'Schwellung, Blutergüsse, Spannungsgefühl und trockene Augen in den ersten 1-2 Wochen sind eine normale Reaktion; starke Schmerzen, Sehverschlechterung, zunehmende Schwellung oder Blutung erfordern sofortige ärztliche Hilfe', 'İlk 1-2 haftada şişlik, morluk, gerginlik hissi ve gözlerde kuruluk normal tepkidir; şiddetli ağrı, görmede azalma, artan şişlik veya kanama derhal hekime başvurmayı gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'upper-blepharoplasty'), 'Surgery of the upper eyelids only — removal of the excess skin that makes the lid hang over the eye', 'Operacija samo gornjih vjeđa — uklanjanje viška kože zbog kojeg vjeđa pada preko oka', 'Операција само горњих вјеђа — уклањање вишка коже због којег вјеђа пада преко ока', 'Пластика только верхних век — удаление избытка кожи, из-за которого веко нависает над глазом', 'Operation nur der Oberlider — Entfernung des Hautüberschusses, durch den das Lid über das Auge hängt', 'Yalnızca üst göz kapaklarının ameliyatı — kapağın göz üzerine sarkmasına yol açan fazla derinin alınması', 'Local anesthesia, an incision in the natural lid crease, removal of a strip of skin (and, if needed, part of the muscle and fat), and a fine suture; 40-60 minutes, with sutures removed after 5-7 days', 'Lokalna anestezija, rez u prirodnoj brazdi vjeđe, uklanjanje trake kože (po potrebi i dijela mišića i masti), tanak šav; 40-60 minuta, šavovi se skidaju nakon 5-7 dana', 'Локална анестезија, рез у природној бразди вјеђе, уклањање траке коже (по потреби и дијела мишића и масти), танак шав; 40-60 минута, шавови се скидају након 5-7 дана', 'Местная анестезия, разрез по естественной складке века, удаление полоски кожи (при необходимости — части мышцы и жира), тонкий шов; 40-60 минут, швы снимают через 5-7 дней', 'Lokalanästhesie, Schnitt in der natürlichen Lidfalte, Entfernung eines Hautstreifens (bei Bedarf auch von Muskel- und Fettanteilen) und eine feine Naht; 40-60 Minuten, Fadenentfernung nach 5-7 Tagen', 'Lokal anestezi, kapağın doğal kıvrımından kesi, bir deri şeridinin (gerekirse kas ve yağın bir bölümünün) alınması ve ince dikiş; 40-60 dakika, dikişler 5-7 gün sonra alınır', 'Overhanging upper eyelid skin, a feeling of heavy lids, narrowing of the visual field due to excess skin', 'Nadvijena koža gornje vjeđe, osjećaj težine vjeđa, sužavanje vidnog polja zbog viška kože', 'Надвијена кожа горње вјеђе, осјећај тежине вјеђа, сужавање видног поља због вишка коже', 'Нависающая кожа верхнего века, ощущение тяжести век, сужение поля зрения из-за избытка кожи', 'Überhängende Oberlidhaut, Gefühl schwerer Lider, Einengung des Gesichtsfelds durch Hautüberschuss', 'Üst kapakta sarkan deri, kapaklarda ağırlık hissi, fazla deri nedeniyle görme alanının daralması', 'Preoperative tests, stopping blood thinners as agreed with the doctor, no make-up on the day of surgery; plan for a week with noticeable swelling', 'Preoperativne analize, prekid lijekova za razrjeđivanje krvi u dogovoru sa ljekarom, bez šminke na dan operacije; planirati nedjelju sa primjetnim oticanjem', 'Преоперативне анализе, прекид лијекова за разрјеђивање крви у договору са љекаром, без шминке на дан операције; планирати недјељу са примјетним отицањем', 'Предоперационные анализы, отмена кроверазжижающих средств по согласованию с врачом, не пользоваться макияжем в день операции; спланировать неделю с заметным отёком', 'Präoperative Tests, Absetzen blutverdünnender Mittel in Absprache mit dem Arzt, am Operationstag kein Make-up; eine Woche mit deutlicher Schwellung einplanen', 'Ameliyat öncesi tetkikler, hekimle görüşerek kan sulandırıcıların kesilmesi, ameliyat günü makyaj yapmamak; belirgin şişliğin olacağı bir hafta planlamak', 'Swelling and bruising for 1-2 weeks and temporary dryness or watering are normal; increasing swelling of one lid, pain in the eye, or worsening vision require an urgent examination', 'Oticanje i modrice 1-2 nedjelje, privremena suhoća i suzenje su uobičajeni; pojačano oticanje jedne vjeđe, bol u oku ili pogoršanje vida zahtijevaju hitan pregled', 'Отицање и модрице 1-2 недјеље, привремена сухоћа и сузење су уобичајени; појачано отицање једне вјеђе, бол у оку или погоршање вида захтијевају хитан преглед', 'Отёк и синяки 1-2 недели, временная сухость и слезотечение — обычное явление; нарастающий отёк одного века, боль в глазу или ухудшение зрения требуют срочного осмотра', 'Schwellung und Blutergüsse für 1-2 Wochen sowie vorübergehende Trockenheit oder Tränenfluss sind normal; zunehmende Schwellung eines Lides, Schmerzen im Auge oder Sehverschlechterung erfordern eine sofortige Untersuchung', '1-2 hafta şişlik ve morluk, geçici kuruluk ve sulanma normaldir; tek kapakta artan şişlik, gözde ağrı veya görmenin bozulması acil muayene gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'lower-blepharoplasty'), 'Surgery of the lower eyelids — correction of under-eye bags and excess skin', 'Operacija donjih vjeđa — korekcija „vrećica“ pod očima i viška kože', 'Операција доњих вјеђа — корекција „врећица“ под очима и вишка коже', 'Пластика нижних век — коррекция «мешков» под глазами и избытка кожи', 'Operation der Unterlider — Korrektur von Tränensäcken und Hautüberschuss', 'Alt göz kapaklarının ameliyatı — göz altı torbalarının ve fazla derinin düzeltilmesi', 'Under local anesthesia with sedation or general anesthesia: an incision just below the lash line or inside the lid, redistribution or removal of the fat pads, and excision of a strip of skin if needed; 60-90 minutes', 'U lokalnoj anesteziji sa sedacijom ili opštoj anesteziji: rez ispod linije trepavica ili sa unutrašnje strane vjeđe, preraspoređivanje ili uklanjanje masnih jastučića, po potrebi i uklanjanje trake kože; 60-90 minuta', 'У локалној анестезији са седацијом или општој анестезији: рез испод линије трепавица или са унутрашње стране вјеђе, прераспоређивање или уклањање масних јастучића, по потреби и уклањање траке коже; 60-90 минута', 'Под местной анестезией с седацией или общим наркозом: разрез под ресничным краем или изнутри века, перераспределение либо удаление жировых грыж, при необходимости — иссечение полоски кожи; 60-90 минут', 'Unter Lokalanästhesie mit Sedierung oder Vollnarkose: Schnitt knapp unter der Wimpernkante oder von der Lidinnenseite, Umverteilung oder Entfernung der Fettpolster, bei Bedarf Entfernung eines Hautstreifens; 60-90 Minuten', 'Sedasyonla lokal anestezi veya genel anestezi altında: kirpik hattının hemen altından ya da kapağın iç yüzünden kesi, yağ yastıklarının yeniden dağıtılması veya alınması, gerekirse bir deri şeridinin çıkarılması; 60-90 dakika', 'Pronounced under-eye bags, lax lower lid skin, changes that do not respond to cosmetic products', 'Izražene „vrećice“ pod očima, mlitava koža donjih vjeđa, promjene na koje kozmetika ne djeluje', 'Изражене „врећице“ под очима, млитава кожа доњих вјеђа, промјене на које козметика не дјелује', 'Выраженные «мешки» под глазами, дряблая кожа нижних век, изменения, не поддающиеся косметическим средствам', 'Ausgeprägte Tränensäcke, schlaffe Unterlidhaut, Veränderungen, auf die Kosmetik nicht anspricht', 'Belirgin göz altı torbaları, alt kapakta gevşek deri, kozmetik ürünlerin etkili olmadığı değişiklikler', 'An examination with assessment of lower lid position by the surgeon, preoperative tests, stopping blood thinners as agreed with the doctor; plan 2 weeks with swelling and bruising', 'Pregled i procjena položaja donje vjeđe od strane hirurga, preoperativne analize, prekid lijekova za razrjeđivanje krvi u dogovoru sa ljekarom; planirati 2 nedjelje sa oticanjem i modricama', 'Преглед и процјена положаја доње вјеђе од стране хирурга, преоперативне анализе, прекид лијекова за разрјеђивање крви у договору са љекаром; планирати 2 недјеље са отицањем и модрицама', 'Осмотр и оценка положения нижнего века хирургом, предоперационные анализы, отказ от кроверазжижающих препаратов по согласованию с врачом; спланировать 2 недели с отёком и синяками', 'Untersuchung und Beurteilung der Unterlidposition durch den Chirurgen, präoperative Tests, Absetzen blutverdünnender Medikamente in Absprache mit dem Arzt; 2 Wochen mit Schwellung und Blutergüssen einplanen', 'Cerrahın alt kapak konumunu değerlendirdiği muayene, ameliyat öncesi tetkikler, hekimle görüşerek kan sulandırıcıların kesilmesi; şişlik ve morlukla geçecek 2 hafta planlamak', 'Swelling, bruising, and temporary dry eyes in the first 2 weeks are normal; marked pain, visual disturbance, or an everted or poorly closing lid margin require immediate contact with the surgeon', 'Oticanje, modrice i privremena suhoća očiju prve 2 nedjelje su uobičajeni; izražena bol, smetnje vida, izvrnuta ivica vjeđe ili nepotpuno zatvaranje oka zahtijevaju hitno obraćanje hirurgu', 'Отицање, модрице и привремена сухоћа очију прве 2 недјеље су уобичајени; изражена бол, сметње вида, изврнута ивица вјеђе или непотпуно затварање ока захтијевају хитно обраћање хирургу', 'Отёк, синяки и временная сухость глаз в первые 2 недели — обычное явление; выраженная боль, нарушение зрения, выворот или отставание края века требуют немедленного обращения к хирургу', 'Schwellung, Blutergüsse und vorübergehend trockene Augen in den ersten 2 Wochen sind normal; starke Schmerzen, Sehstörungen oder ein nach außen gedrehter bzw. nicht vollständig schließender Lidrand erfordern die sofortige Kontaktaufnahme mit dem Chirurgen', 'İlk 2 haftada şişlik, morluk ve geçici göz kuruluğu normaldir; belirgin ağrı, görme bozukluğu, kapak kenarının dışa dönmesi veya gözün tam kapanmaması cerraha derhal başvurmayı gerektirir')
