INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'circumcision-local-anesthesia'), 'Surgical removal of the foreskin, performed under local anesthesia', 'Hirurško uklanjanje kožice (prepucijuma) u lokalnoj anesteziji', 'Хируршко уклањање кожице (препуцијума) у локалној анестезији', 'Хирургическое удаление крайней плоти, выполняемое под местной анестезией', 'Chirurgische Entfernung der Vorhaut, durchgeführt unter Lokalanästhesie', 'Lokal anestezi altında sünnet derisinin cerrahi olarak alınması', 'After local anesthesia the surgeon removes the foreskin and places sutures (usually absorbable), then a dressing; 30-45 minutes, home the same day', 'Nakon lokalne anestezije ljekar uklanja kožicu i postavlja šavove (obično resorptivne), a zatim zavoj; 30-45 minuta, kući istog dana', 'Након локалне анестезије љекар уклања кожицу и поставља шавове (обично ресорптивне), а затим завој; 30-45 минута, кући истог дана', 'После местной анестезии врач удаляет крайнюю плоть и накладывает швы (обычно рассасывающиеся), затем повязку; 30-45 минут, домой в тот же день', 'Nach der Lokalanästhesie entfernt der Arzt die Vorhaut und legt Nähte (meist selbstauflösend) sowie einen Verband an; 30-45 Minuten, am selben Tag nach Hause', 'Lokal anesteziden sonra hekim sünnet derisini alır ve dikiş (genellikle emilebilir) ile pansuman uygular; 30-45 dakika, aynı gün eve dönüş', 'Phimosis, recurrent inflammation, scarring of the foreskin, as well as surgery by personal or religious choice — medical indications are determined by a urologist', 'Fimoza, ponavljane upale, cikatriksne promjene kožice, kao i operacija po ličnom ili vjerskom izboru — medicinske indikacije određuje urolog', 'Фимоза, понављане упале, цикатриксне промјене кожице, као и операција по личном или вјерском избору — медицинске индикације одређује уролог', 'Фимоз, повторяющиеся воспаления, рубцовые изменения крайней плоти, а также операция по личному или религиозному выбору — медицинские показания определяет уролог', 'Phimose, wiederkehrende Entzündungen, narbige Veränderungen der Vorhaut sowie ein Eingriff aus persönlicher oder religiöser Entscheidung — medizinische Indikationen stellt der Urologe', 'Fimozis, yinelenen iltihaplar, sünnet derisinde nedbe değişiklikleri ve kişisel ya da dini tercihle yapılan işlem — tıbbi endikasyonu ürolog belirler', 'A urologist''s examination, hygiene of the operative area, reporting current medications and any allergy to anesthetics; plan 1-2 weeks without physical exertion and 4-6 weeks without sexual activity (the period is specified by the doctor)', 'Pregled urologa, higijena operativnog područja, obavijestiti o lijekovima i alergiji na anestetike; planirati 1-2 nedjelje bez fizičkih napora i 4-6 nedjelja bez seksualnih odnosa (rok precizira ljekar)', 'Преглед уролога, хигијена оперативног подручја, обавијестити о лијековима и алергији на анестетике; планирати 1-2 недјеље без физичких напора и 4-6 недјеља без сексуалних односа (рок прецизира љекар)', 'Осмотр уролога, гигиена области операции, сообщить о принимаемых препаратах и аллергии на анестетики; спланировать 1-2 недели без физических нагрузок и 4-6 недель без половых контактов (срок уточняет врач)', 'Urologische Untersuchung, Hygiene des Operationsbereichs, Mitteilung eingenommener Medikamente und einer Allergie gegen Betäubungsmittel; 1-2 Wochen ohne körperliche Anstrengung und 4-6 Wochen ohne Geschlechtsverkehr einplanen (den Zeitraum legt der Arzt fest)', 'Ürolog muayenesi, bölgenin hijyeni, kullanılan ilaçların ve anestezik alerjisinin bildirilmesi; 1-2 hafta ağır efordan, 4-6 hafta cinsel ilişkiden uzak kalmayı planlamak (süreyi hekim belirler)', 'Swelling, bluish discoloration, and moderate soreness in the first 1-2 weeks are a normal reaction; increasing pain, purulent discharge, bleeding, fever, or inability to pass urine require urgent medical attention', 'Oticanje, plavičasta prebojenost i umjerena bol prvih 1-2 nedjelje su uobičajena reakcija; bol koja se pojačava, gnojni iscjedak, krvarenje, povišena temperatura ili nemogućnost mokrenja zahtijevaju hitno obraćanje ljekaru', 'Отицање, плавичаста пребојеност и умјерена бол првих 1-2 недјеље су уобичајена реакција; бол која се појачава, гнојни исцједак, крварење, повишена температура или немогућност мокрења захтијевају хитно обраћање љекару', 'Отёк, синюшность и умеренная болезненность в первые 1-2 недели — обычная реакция; нарастающая боль, гнойное отделяемое, кровотечение, температура или невозможность помочиться требуют срочного обращения к врачу', 'Schwellung, bläuliche Verfärbung und moderate Schmerzen in den ersten 1-2 Wochen sind eine normale Reaktion; zunehmende Schmerzen, eitriges Sekret, Blutung, Fieber oder Unfähigkeit Wasser zu lassen erfordern dringend ärztliche Hilfe', 'İlk 1-2 haftada şişlik, morarma ve orta düzeyde ağrı normal tepkidir; artan ağrı, iltihaplı akıntı, kanama, ateş veya idrar yapamama acilen hekime başvurmayı gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'penile-prosthesis-implantation'), 'Surgical implantation of a penile prosthesis — a device placed inside the penis to restore the ability to achieve an erection', 'Hirurška ugradnja penilne proteze — uređaja koji se implantira unutra radi vraćanja mogućnosti erekcije', 'Хируршка уградња пенилне протезе — уређаја који се имплантира унутра ради враћања могућности ерекције', 'Хирургическая имплантация протеза полового члена — устройства, вживляемого внутрь для восстановления возможности эрекции', 'Chirurgische Implantation einer Penisprothese — eines Geräts, das im Inneren eingesetzt wird, um die Erektionsfähigkeit wiederherzustellen', 'Penil protez implantasyonu — ereksiyon yeteneğini geri kazandırmak için içeriye yerleştirilen cihazın cerrahi olarak takılması', 'Under spinal or general anesthesia the urologist places the prosthesis inside the corpora cavernosa through a small incision (with hydraulic models, also a reservoir and a pump); 1-2 hours, usually 1-2 days in hospital, with training in use at follow-up visits', 'U spinalnoj ili opštoj anesteziji urolog kroz mali rez postavlja protezu unutar kavernoznih tijela (kod hidrauličnih modela i rezervoar i pumpu); 1-2 sata, obično 1-2 dana u bolnici, a obuka za upotrebu se radi na kontrolama', 'У спиналној или општој анестезији уролог кроз мали рез поставља протезу унутар кавернозних тијела (код хидрауличних модела и резервоар и пумпу); 1-2 сата, обично 1-2 дана у болници, а обука за употребу се ради на контролама', 'Под спинальной или общей анестезией уролог через небольшой разрез устанавливает протез внутрь кавернозных тел (при гидравлических моделях — также резервуар и насос); 1-2 часа, обычно 1-2 дня в стационаре, обучение пользованию — на контрольных визитах', 'Unter Spinal- oder Vollnarkose setzt der Urologe die Prothese über einen kleinen Schnitt in die Schwellkörper ein (bei hydraulischen Modellen zusätzlich Reservoir und Pumpe); 1-2 Stunden, meist 1-2 Tage im Krankenhaus, die Einweisung in die Anwendung erfolgt bei den Kontrollterminen', 'Spinal veya genel anestezi altında ürolog küçük bir kesiden protezi korpus kavernozumların içine yerleştirir (hidrolik modellerde ayrıca rezervuar ve pompa); 1-2 saat, genellikle 1-2 gün hastanede, kullanım eğitimi kontrol seanslarında verilir', 'Persistent erectile dysfunction in which medication and other methods are ineffective — the indication is established by a urologist after a work-up', 'Trajna erektilna disfunkcija kod koje lijekovi i druge metode nisu efikasni — indikaciju postavlja urolog nakon pregleda', 'Трајна еректилна дисфункција код које лијекови и друге методе нису ефикасни — индикацију поставља уролог након прегледа', 'Стойкая эректильная дисфункция, при которой лекарственные и другие методы неэффективны — показания устанавливает уролог после обследования', 'Anhaltende erektile Dysfunktion, bei der Medikamente und andere Verfahren nicht wirken — die Indikation stellt der Urologe nach einer Untersuchung', 'İlaç ve diğer yöntemlerin etkisiz kaldığı kalıcı ereksiyon bozukluğu — endikasyonu ürolog tetkiklerden sonra belirler', 'A full urological work-up, laboratory tests and an anesthesiologist consultation, control of diabetes and other chronic conditions, treatment of any infection; plan 4-6 weeks without sexual activity', 'Kompletan urološki pregled, analize i konsultacija sa anesteziologom, regulisanje dijabetesa i drugih hroničnih bolesti, liječenje infekcija; planirati 4-6 nedjelja bez seksualnih odnosa', 'Комплетан уролошки преглед, анализе и консултација са анестезиологом, регулисање дијабетеса и других хроничних болести, лијечење инфекција; планирати 4-6 недјеља без сексуалних односа', 'Полное урологическое обследование, анализы и консультация анестезиолога, компенсация сахарного диабета и других хронических заболеваний, санация инфекций; спланировать 4-6 недель без половых контактов', 'Vollständige urologische Untersuchung, Labortests und Anästhesiegespräch, Einstellung von Diabetes und anderen chronischen Erkrankungen, Behandlung von Infektionen; 4-6 Wochen ohne Geschlechtsverkehr einplanen', 'Kapsamlı ürolojik değerlendirme, tetkikler ve anestezi uzmanı görüşmesi, diyabet ve diğer kronik hastalıkların düzenlenmesi, enfeksiyonların tedavisi; 4-6 hafta cinsel ilişkiden uzak kalmayı planlamak', 'Swelling, bruising, and soreness in the first weeks are expected; fever, redness or discharge from the wound, increasing pain, or problems passing urine require immediate medical attention', 'Oticanje, modrice i bol prvih nedjelja su očekivani; povišena temperatura, crvenilo i iscjedak iz rane, bol koja se pojačava ili problemi sa mokrenjem zahtijevaju hitno obraćanje ljekaru', 'Отицање, модрице и бол првих недјеља су очекивани; повишена температура, црвенило и исцједак из ране, бол која се појачава или проблеми са мокрењем захтијевају хитно обраћање љекару', 'Отёк, синяки и болезненность в первые недели ожидаемы; температура, покраснение и выделения из раны, нарастающая боль или проблемы с мочеиспусканием требуют немедленного обращения к врачу', 'Schwellung, Blutergüsse und Schmerzen in den ersten Wochen sind zu erwarten; Fieber, Rötung oder Sekret aus der Wunde, zunehmende Schmerzen oder Probleme beim Wasserlassen erfordern sofortige ärztliche Hilfe', 'İlk haftalarda şişlik, morluk ve ağrı beklenir; ateş, yarada kızarıklık veya akıntı, artan ağrı ya da idrar yapmada sorun derhal hekime başvurmayı gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'cataract-surgery-with-standard-iol'), 'Surgery to remove a clouded lens with implantation of a standard artificial intraocular lens (IOL)', 'Operacija uklanjanja zamućenog očnog sočiva sa ugradnjom standardnog vještačkog intraokularnog sočiva (IOL)', 'Операција уклањања замућеног очног сочива са уградњом стандардног вјештачког интраокуларног сочива (IOL)', 'Операция по удалению помутневшего хрусталика с имплантацией стандартной искусственной интраокулярной линзы (ИОЛ)', 'Operation zur Entfernung der eingetrübten Linse mit Implantation einer Standard-Kunstlinse (IOL)', 'Bulanıklaşmış göz merceğinin çıkarılıp standart yapay göz içi merceğin (İOL) yerleştirildiği ameliyat', 'Under local anesthesia (drops or an injection) the lens is broken up with ultrasound and removed through a micro-incision, then a foldable lens is inserted; 15-30 minutes, usually without hospitalization, with vision recovering over a few days', 'U lokalnoj anesteziji (kapi ili injekcija) sočivo se kroz mikrorez razgrađuje ultrazvukom i uklanja, a zatim se ubacuje sklopivo sočivo; 15-30 minuta, obično bez hospitalizacije, vid se popravlja tokom nekoliko dana', 'У локалној анестезији (капи или ињекција) сочиво се кроз микрорез разграђује ултразвуком и уклања, а затим се убацује склопиво сочиво; 15-30 минута, обично без хоспитализације, вид се поправља током неколико дана', 'Под местной анестезией (капли или инъекция) через микроразрез хрусталик разрушают ультразвуком и удаляют, затем вводят складную линзу; 15-30 минут, обычно без госпитализации, зрение восстанавливается в течение нескольких дней', 'Unter Lokalanästhesie (Tropfen oder Injektion) wird die Linse über einen Mikroschnitt mit Ultraschall zerkleinert und entfernt, danach wird eine faltbare Linse eingesetzt; 15-30 Minuten, meist ohne Krankenhausaufenthalt, das Sehen erholt sich über einige Tage', 'Lokal anestezi (damla veya enjeksiyon) altında mercek mikro kesiden ultrasonla parçalanıp alınır, ardından katlanabilir mercek yerleştirilir; 15-30 dakika, genellikle yatış gerekmez, görme birkaç gün içinde düzelir', 'A cataract that reduces vision and interferes with daily life — the timing of surgery is decided by the ophthalmologist', 'Katarakta koja smanjuje vid i otežava svakodnevni život — odluku o vremenu operacije donosi oftalmolog', 'Катаракта која смањује вид и отежава свакодневни живот — одлуку о времену операције доноси офталмолог', 'Катаракта, которая снижает зрение и мешает в быту — решение о сроке операции принимает офтальмолог', 'Ein Katarakt, der das Sehen verschlechtert und den Alltag beeinträchtigt — den Zeitpunkt der Operation legt der Augenarzt fest', 'Görmeyi azaltan ve günlük yaşamı zorlaştıran katarakt — ameliyat zamanına göz hekimi karar verir', 'An eye examination with calculation of the lens power, laboratory tests if the clinic requires them, and use of the prescribed drops; someone should accompany you on the day of surgery and you must not drive', 'Pregled oka sa izračunom dioptrije sočiva, analize po zahtjevu klinike, primjena propisanih kapi; na dan operacije potreban je pratilac i ne smije se voziti', 'Преглед ока са израчуном диоптрије сочива, анализе по захтјеву клинике, примјена прописаних капи; на дан операције потребан је пратилац и не смије се возити', 'Обследование глаза с расчётом оптической силы линзы, анализы по требованию клиники, применение назначенных капель; в день операции нужен сопровождающий, за руль садиться нельзя', 'Augenuntersuchung mit Berechnung der Linsenstärke, Labortests nach Vorgabe der Klinik und Anwendung der verordneten Tropfen; am Operationstag ist eine Begleitperson nötig, Autofahren ist nicht erlaubt', 'Mercek numarasının hesaplandığı göz muayenesi, kliniğin istediği tetkikler ve reçete edilen damlaların kullanımı; ameliyat günü yanında biri olmalı ve araç kullanılmamalı', 'A gritty sensation, slight redness, and blurred vision in the first days are normal; sharp pain, increasing redness, flashes, a "curtain" in the field of vision, or worsening sight require immediate contact with an ophthalmologist', 'Osjećaj pijeska, blago crvenilo i zamućen vid prvih dana su uobičajeni; jaka bol, pojačano crvenilo, bljeskovi, „zavjesa“ u vidnom polju ili pogoršanje vida zahtijevaju hitno obraćanje oftalmologu', 'Осјећај пијеска, благо црвенило и замућен вид првих дана су уобичајени; јака бол, појачано црвенило, бљескови, „завјеса“ у видном пољу или погоршање вида захтијевају хитно обраћање офталмологу', 'Ощущение песка, лёгкое покраснение и нечёткость зрения в первые дни — обычное явление; резкая боль, нарастающее покраснение, вспышки, «занавес» в поле зрения или ухудшение зрения требуют немедленного обращения к офтальмологу', 'Sandkorngefühl, leichte Rötung und unscharfes Sehen in den ersten Tagen sind normal; starke Schmerzen, zunehmende Rötung, Lichtblitze, ein "Vorhang" im Gesichtsfeld oder eine Sehverschlechterung erfordern sofort augenärztliche Hilfe', 'İlk günlerde batma hissi, hafif kızarıklık ve bulanık görme normaldir; şiddetli ağrı, artan kızarıklık, ışık çakmaları, görme alanında "perde" veya görmenin bozulması derhal göz hekimine başvurmayı gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'secondary-iol-implantation'), 'Implantation of an artificial lens as a second-stage procedure — when the eye has been left without a lens, or a previously implanted lens must be replaced or fixed differently', 'Ugradnja vještačkog sočiva u drugoj fazi — kada je oko ostalo bez sočiva ili prethodno ugrađeno sočivo treba zamijeniti ili drugačije fiksirati', 'Уградња вјештачког сочива у другој фази — када је око остало без сочива или претходно уграђено сочиво треба замијенити или другачије фиксирати', 'Имплантация искусственной линзы вторым этапом — когда глаз остался без хрусталика или ранее установленную линзу нужно заменить либо зафиксировать иначе', 'Implantation einer Kunstlinse als zweiter Schritt — wenn das Auge ohne Linse geblieben ist oder eine früher eingesetzte Linse ersetzt oder anders befestigt werden muss', 'Yapay merceğin ikinci aşamada yerleştirilmesi — gözün merceksiz kalması ya da daha önce takılan merceğin değiştirilmesi veya farklı şekilde sabitlenmesi gerektiğinde', 'Under local anesthesia the surgeon inserts the lens and fixes it according to the state of the eye tissues (in the capsule, to the iris, or to the sclera); 30-60 minutes, with the extent and method decided during surgery', 'U lokalnoj anesteziji hirurg ubacuje sočivo i fiksira ga zavisno od stanja tkiva oka (u kapsulu, za dužicu ili za beonjaču); 30-60 minuta, obim i metod se određuju tokom operacije', 'У локалној анестезији хирург убацује сочиво и фиксира га зависно од стања ткива ока (у капсулу, за дужицу или за беоњачу); 30-60 минута, обим и метод се одређују током операције', 'Под местной анестезией хирург вводит линзу и фиксирует её в зависимости от состояния тканей глаза (в капсуле, к радужке или к склере); 30-60 минут, объём и метод определяются на операции', 'Unter Lokalanästhesie setzt der Chirurg die Linse ein und befestigt sie je nach Zustand des Augengewebes (in der Kapsel, an der Iris oder an der Sklera); 30-60 Minuten, Umfang und Methode werden während der Operation festgelegt', 'Lokal anestezi altında cerrah merceği yerleştirir ve göz dokularının durumuna göre sabitler (kapsül içine, iris veya skleraya); 30-60 dakika, kapsam ve yöntem ameliyat sırasında belirlenir', 'Absence of a lens after surgery or injury, dislocation or unsuitability of a previously implanted lens — the indication is established by an ophthalmologist', 'Odsustvo sočiva nakon operacije ili povrede, pomjereno ili neodgovarajuće prethodno ugrađeno sočivo — indikaciju postavlja oftalmolog', 'Одсуство сочива након операције или повреде, помјерено или неодговарајуће претходно уграђено сочиво — индикацију поставља офталмолог', 'Отсутствие хрусталика после операции или травмы, смещение или неподходящая ранее имплантированная линза — показания устанавливает офтальмолог', 'Fehlen der Linse nach Operation oder Verletzung, Verlagerung oder Unverträglichkeit einer früher implantierten Linse — die Indikation stellt der Augenarzt', 'Ameliyat veya travma sonrası merceğin bulunmaması, daha önce takılan merceğin yer değiştirmesi ya da uygun olmaması — endikasyonu göz hekimi belirler', 'A detailed eye examination including the back of the eye, and lens calculation; discuss current medications with the doctor; someone should accompany you on the day of surgery', 'Detaljan pregled oka, uključujući i zadnji segment, izračun sočiva; sa ljekarom uskladiti lijekove koje uzimate; na dan operacije potreban je pratilac', 'Детаљан преглед ока, укључујући и задњи сегмент, израчун сочива; са љекаром ускладити лијекове које узимате; на дан операције потребан је пратилац', 'Детальное обследование глаза, включая осмотр заднего отрезка, расчёт линзы; согласовать с врачом принимаемые препараты; в день операции нужен сопровождающий', 'Ausführliche Augenuntersuchung einschließlich des hinteren Augenabschnitts und Linsenberechnung; eingenommene Medikamente mit dem Arzt abstimmen; am Operationstag ist eine Begleitperson nötig', 'Arka segmenti de kapsayan ayrıntılı göz muayenesi ve mercek hesabı; kullanılan ilaçların hekimle görüşülmesi; ameliyat günü yanında biri olmalı', 'Moderate redness and blurred vision in the first days are expected; pain, light sensitivity, a sharp drop in vision, or new floaters and flashes require immediate ophthalmic examination', 'Umjereno crvenilo i zamućen vid prvih dana su očekivani; bol, preosjetljivost na svjetlo, naglo slabljenje vida ili pojava plutajućih mrlja i bljeskova zahtijevaju hitan pregled oftalmologa', 'Умјерено црвенило и замућен вид првих дана су очекивани; бол, преосјетљивост на свјетло, нагло слабљење вида или појава плутајућих мрља и бљескова захтијевају хитан преглед офталмолога', 'Умеренное покраснение и нечёткость зрения в первые дни ожидаемы; боль, светобоязнь, резкое снижение зрения или появление плавающих пятен и вспышек требуют немедленного осмотра офтальмолога', 'Moderate Rötung und unscharfes Sehen in den ersten Tagen sind zu erwarten; Schmerzen, Lichtempfindlichkeit, ein plötzlicher Sehabfall oder neue Flecken und Lichtblitze erfordern eine sofortige augenärztliche Untersuchung', 'İlk günlerde orta düzeyde kızarıklık ve bulanık görme beklenir; ağrı, ışığa duyarlılık, görmenin aniden azalması ya da yeni uçuşan lekeler ve çakmalar acil göz muayenesi gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'ivf-anesthesia'), 'Anesthesia for IVF procedures — most often short intravenous sedation or general anesthesia during egg retrieval', 'Anestezija kod procedura vantjelesne oplodnje — najčešće kratka intravenska sedacija ili opšta anestezija tokom punkcije jajnika', 'Анестезија код процедура вантјелесне оплодње — најчешће кратка интравенска седација или општа анестезија током пункције јајника', 'Анестезия при процедурах ЭКО — чаще всего короткая внутривенная седация или общая анестезия на время пункции яичников', 'Anästhesie bei IVF-Eingriffen — meist eine kurze intravenöse Sedierung oder Vollnarkose während der Eizellentnahme', 'Tüp bebek işlemlerinde anestezi — çoğunlukla yumurta toplama sırasında kısa süreli damar yolundan sedasyon veya genel anestezi', 'The anesthesiologist examines the patient, administers the medication intravenously, and monitors her during the procedure; the retrieval itself takes 15-30 minutes, followed by 1-2 hours of observation before discharge', 'Anesteziolog pregleda pacijentkinju, daje lijekove intravenski i kontroliše stanje tokom procedure; sama punkcija traje 15-30 minuta, nakon čega je potrebno 1-2 sata posmatranja do otpuštanja', 'Анестезиолог прегледа пацијенткињу, даје лијекове интравенски и контролише стање током процедуре; сама пункција траје 15-30 минута, након чега је потребно 1-2 сата посматрања до отпуштања', 'Анестезиолог осматривает пациентку, вводит препараты внутривенно и контролирует состояние во время процедуры; сама пункция занимает 15-30 минут, после неё требуется 1-2 часа наблюдения до выписки', 'Der Anästhesist untersucht die Patientin, verabreicht die Medikamente intravenös und überwacht sie während des Eingriffs; die Entnahme selbst dauert 15-30 Minuten, danach sind 1-2 Stunden Überwachung bis zur Entlassung nötig', 'Anestezi uzmanı hastayı değerlendirir, ilaçları damardan verir ve işlem boyunca izler; toplama işlemi 15-30 dakika sürer, ardından taburculuğa kadar 1-2 saat gözlem gerekir', 'Follicle puncture in an IVF cycle and other short procedures of the programme that require anesthesia — the method is chosen by the anesthesiologist', 'Punkcija folikula u ciklusu vantjelesne oplodnje i druge kratke intervencije programa kod kojih je potrebna anestezija — metod izabira anesteziolog', 'Пункција фоликула у циклусу вантјелесне оплодње и друге кратке интервенције програма код којих је потребна анестезија — метод изабира анестезиолог', 'Пункция фолликулов в цикле ЭКО и другие короткие вмешательства программы, когда нужна анестезия — метод выбирает анестезиолог', 'Follikelpunktion im IVF-Zyklus und andere kurze Eingriffe des Programms, die eine Anästhesie erfordern — das Verfahren wählt der Anästhesist', 'Tüp bebek döngüsünde folikül toplama ve programın anestezi gerektiren diğer kısa işlemleri — yöntemi anestezi uzmanı seçer', 'No food for 6-8 hours and no drink for 2-4 hours before the procedure (the clinic gives exact times), remove contact lenses and jewelry, and come with someone accompanying you; driving is not allowed that day', 'Ne jesti 6-8 sati i ne piti 2-4 sata prije procedure (tačne rokove daje klinika), skinuti kontaktna sočiva i nakit, doći sa pratiocem; tog dana se ne smije voziti', 'Не јести 6-8 сати и не пити 2-4 сата прије процедуре (тачне рокове даје клиника), скинути контактна сочива и накит, доћи са пратиоцем; тог дана се не смије возити', 'Не есть 6-8 часов и не пить 2-4 часа до процедуры (точные сроки даёт клиника), снять контактные линзы и украшения, прийти с сопровождающим; в этот день нельзя садиться за руль', '6-8 Stunden nichts essen und 2-4 Stunden nichts trinken vor dem Eingriff (genaue Zeiten gibt die Klinik vor), Kontaktlinsen und Schmuck ablegen und mit einer Begleitperson kommen; an diesem Tag darf nicht Auto gefahren werden', 'İşlemden önce 6-8 saat yememek ve 2-4 saat içmemek (kesin süreleri klinik verir), kontakt lens ve takıları çıkarmak, yanında biriyle gelmek; o gün araç kullanılmamalı', 'Drowsiness, mild nausea, and weakness in the first hours after anesthesia are normal; marked abdominal pain, dizziness, fever, or heavy bleeding after the procedure require immediate contact with the clinic', 'Pospanost, blaga mučnina i slabost prvih sati nakon anestezije su uobičajeni; izražena bol u stomaku, vrtoglavica, povišena temperatura ili obilno krvarenje nakon procedure zahtijevaju hitan kontakt sa klinikom', 'Поспаност, блага мучнина и слабост првих сати након анестезије су уобичајени; изражена бол у стомаку, вртоглавица, повишена температура или обилно крварење након процедуре захтијевају хитан контакт са клиником', 'Сонливость, лёгкая тошнота и слабость в первые часы после анестезии — обычное явление; выраженная боль в животе, головокружение, температура или обильное кровотечение после процедуры требуют немедленной связи с клиникой', 'Schläfrigkeit, leichte Übelkeit und Schwäche in den ersten Stunden nach der Anästhesie sind normal; starke Bauchschmerzen, Schwindel, Fieber oder eine starke Blutung nach dem Eingriff erfordern die sofortige Kontaktaufnahme mit der Klinik', 'Anesteziden sonraki ilk saatlerde uyku hâli, hafif bulantı ve halsizlik normaldir; belirgin karın ağrısı, baş dönmesi, ateş veya işlem sonrası yoğun kanama kliniğe derhal başvurmayı gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'professor-cardiologist-examination'), 'A consultation with a cardiologist holding the academic title of professor — an extended appointment that usually takes longer and costs more than a standard one', 'Konsultacija kardiologa sa akademskim zvanjem profesora — proširen pregled koji obično traje duže i skuplji je od uobičajenog', 'Консултација кардиолога са академским звањем професора — проширен преглед који обично траје дуже и скупљи је од уобичајеног', 'Консультация кардиолога с академическим званием профессора — расширенный приём, который обычно занимает больше времени и стоит дороже обычного', 'Eine Konsultation bei einem Kardiologen mit dem akademischen Titel Professor — ein erweiterter Termin, der meist länger dauert und mehr kostet als eine reguläre Untersuchung', 'Profesör unvanlı bir kardiyoloji uzmanıyla görüşme — genellikle standart muayeneden daha uzun süren ve daha yüksek ücretli kapsamlı bir randevu', 'History taking, examination, auscultation, blood pressure measurement, and review of previous ECGs, heart ultrasound, and laboratory results; the doctor then formulates a conclusion, a work-up plan, or changes to treatment; 30-60 minutes', 'Uzimanje anamneze, pregled, auskultacija, mjerenje pritiska, analiza ranije urađenih EKG-a, ultrazvuka srca i laboratorijskih nalaza; nakon toga ljekar formuliše zaključak, plan pregleda ili korekciju terapije; 30-60 minuta', 'Узимање анамнезе, преглед, аускултација, мјерење притиска, анализа раније урађених ЕКГ-а, ултразвука срца и лабораторијских налаза; након тога љекар формулише закључак, план прегледа или корекцију терапије; 30-60 минута', 'Сбор анамнеза, осмотр, аускультация, измерение давления, разбор ранее выполненных ЭКГ, УЗИ сердца и анализов; по итогам врач формулирует заключение, план обследования или коррекцию лечения; 30-60 минут', 'Anamnese, Untersuchung, Auskultation, Blutdruckmessung und Durchsicht früherer EKGs, Herzultraschall- und Laborbefunde; danach formuliert der Arzt eine Beurteilung, einen Untersuchungsplan oder eine Therapieanpassung; 30-60 Minuten', 'Öykü alma, muayene, dinleme, tansiyon ölçümü ve daha önce yapılmış EKG, kalp ultrasonu ve laboratuvar sonuçlarının değerlendirilmesi; ardından hekim bir sonuç, tetkik planı veya tedavi değişikliği belirler; 30-60 dakika', 'Complex or unclear cardiac cases, a second opinion on prescribed treatment, preparation for surgery, management of several coexisting conditions', 'Složeni ili nejasni kardiološki slučajevi, drugo mišljenje o propisanoj terapiji, priprema za operaciju, vođenje više pridruženih bolesti', 'Сложени или нејасни кардиолошки случајеви, друго мишљење о прописаној терапији, припрема за операцију, вођење више придружених болести', 'Сложные или неясные кардиологические случаи, второе мнение по назначенному лечению, подготовка к операции, ведение нескольких сопутствующих заболеваний', 'Komplexe oder unklare kardiologische Fälle, Zweitmeinung zur verordneten Therapie, Vorbereitung auf eine Operation, Betreuung mehrerer Begleiterkrankungen', 'Karmaşık veya belirsiz kardiyolojik durumlar, verilen tedavi için ikinci görüş, ameliyat hazırlığı, birden fazla eşlik eden hastalığın yönetimi', 'Bring all previous investigations (ECG, echocardiography, Holter, laboratory tests) and a full list of current medications with doses; do not stop any medication on your own before the appointment', 'Donijeti sve prethodne nalaze (EKG, ehokardiografiju, holter, analize) i potpun spisak lijekova sa dozama; ne prekidati lijekove samostalno prije pregleda', 'Донијети све претходне налазе (ЕКГ, ехокардиографију, холтер, анализе) и потпун списак лијекова са дозама; не прекидати лијекове самостално прије прегледа', 'Взять с собой все предыдущие обследования (ЭКГ, эхокардиография, холтер, анализы) и полный список принимаемых препаратов с дозами; не отменять лекарства самостоятельно перед приёмом', 'Alle vorherigen Befunde mitbringen (EKG, Echokardiographie, Langzeit-EKG, Labor) sowie eine vollständige Medikamentenliste mit Dosierungen; Medikamente vor dem Termin nicht eigenmächtig absetzen', 'Önceki tüm tetkikleri (EKG, ekokardiyografi, holter, laboratuvar) ve dozlarıyla birlikte tam ilaç listesini getirmek; randevu öncesi ilaçları kendi başına kesmemek', 'Based on the appointment, the doctor may order additional tests or change treatment; chest pain, severe shortness of breath, or an irregular heartbeat call for emergency care rather than a scheduled consultation', 'Na osnovu pregleda ljekar može zatražiti dodatna ispitivanja ili promijeniti terapiju; kod bola u grudima, izraženog nedostatka vazduha ili nepravilnog rada srca potrebna je hitna medicinska pomoć, a ne planska konsultacija', 'На основу прегледа љекар може затражити додатна испитивања или промијенити терапију; код бола у грудима, израженог недостатка ваздуха или неправилног рада срца потребна је хитна медицинска помоћ, а не планска консултација', 'По результатам приёма врач может назначить дополнительные обследования или изменить лечение; при боли в груди, выраженной одышке или перебоях в работе сердца нужна не плановая консультация, а экстренная медицинская помощь', 'Auf Grundlage des Termins kann der Arzt zusätzliche Untersuchungen veranlassen oder die Therapie ändern; bei Brustschmerzen, starker Atemnot oder Herzrhythmusstörungen ist keine geplante Konsultation, sondern Notfallhilfe erforderlich', 'Muayene sonucuna göre hekim ek tetkikler isteyebilir veya tedaviyi değiştirebilir; göğüs ağrısı, belirgin nefes darlığı veya kalp ritminde düzensizlik planlı görüşme değil acil tıbbi yardım gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'plaster-brace-reduction'), 'Reduction with application of a plaster brace — immobilization of the trunk with a plaster cast after the bones have been placed in the correct position', 'Repozicija sa postavljanjem gipsanog korzeta — imobilizacija trupa gipsanim zavojem nakon dovođenja kostiju u pravilan položaj', 'Репозиција са постављањем гипсаног корзета — имобилизација трупа гипсаним завојем након довођења костију у правилан положај', 'Вправление (репозиция) с наложением гипсового корсета — фиксация туловища гипсовой повязкой после придания костям правильного положения', 'Reposition mit Anlage eines Gipskorsetts — Ruhigstellung des Rumpfes mit einem Gipsverband, nachdem die Knochen in die richtige Stellung gebracht wurden', 'Redüksiyon ve alçı korse uygulaması — kemikler doğru konuma getirildikten sonra gövdenin alçı ile tespit edilmesi', 'Under pain relief the doctor performs the reduction, then applies the plaster brace and takes a check X-ray; the procedure takes 30-60 minutes, and the trauma surgeon determines how long the brace is worn', 'Ljekar u analgeziji izvodi repoziciju, zatim postavlja gipsani korzet i pravi kontrolni snimak; procedura traje 30-60 minuta, a period nošenja korzeta određuje traumatolog', 'Љекар у аналгезији изводи репозицију, затим поставља гипсани корзет и прави контролни снимак; процедура траје 30-60 минута, а период ношења корзета одређује трауматолог', 'Врач под обезболиванием выполняет репозицию, затем накладывает гипсовый корсет и делает контрольный снимок; процедура занимает 30-60 минут, срок ношения корсета определяет травматолог', 'Der Arzt führt die Reposition unter Schmerzbehandlung durch, legt anschließend das Gipskorsett an und macht eine Kontrollaufnahme; die Behandlung dauert 30-60 Minuten, die Tragedauer legt der Unfallchirurg fest', 'Hekim ağrı kontrolü altında redüksiyonu yapar, ardından alçı korseyi uygular ve kontrol röntgeni çeker; işlem 30-60 dakika sürer, korsenin kullanım süresini travmatoloji uzmanı belirler', 'Fractures and deformities that require rigid immobilization of the trunk without surgery — the decision is made by the trauma surgeon based on imaging', 'Prelomi i deformiteti kod kojih je potrebna čvrsta imobilizacija trupa bez operacije — odluku donosi traumatolog na osnovu snimaka', 'Преломи и деформитети код којих је потребна чврста имобилизација трупа без операције — одлуку доноси трауматолог на основу снимака', 'Переломы и деформации, при которых нужна жёсткая фиксация туловища без операции — решение принимает травматолог по снимкам', 'Frakturen und Fehlstellungen, die eine starre Ruhigstellung des Rumpfes ohne Operation erfordern — die Entscheidung trifft der Unfallchirurg anhand der Bilder', 'Ameliyat olmadan gövdenin sert şekilde tespit edilmesini gerektiren kırık ve şekil bozuklukları — kararı görüntülere göre travmatoloji uzmanı verir', 'An X-ray (sometimes CT) beforehand, and reporting skin conditions and any allergy to painkillers; after the brace is applied, help with daily tasks and loose clothing will be needed', 'Rendgen (ponekad CT) prije procedure, obavijestiti o bolestima kože i alergiji na analgetike; nakon postavljanja korzeta biće potrebna pomoć u kući i široka odjeća', 'Рендген (понекад ЦТ) прије процедуре, обавијестити о болестима коже и алергији на аналгетике; након постављања корзета биће потребна помоћ у кући и широка одјећа', 'Рентген (иногда КТ) до процедуры, сообщить о заболеваниях кожи и аллергии на обезболивающие; после наложения корсета понадобится помощь в быту и свободная одежда', 'Röntgen (gelegentlich CT) vorab sowie Mitteilung von Hauterkrankungen und Allergien gegen Schmerzmittel; nach Anlage des Korsetts sind Hilfe im Alltag und weite Kleidung nötig', 'İşlem öncesi röntgen (bazen BT), cilt hastalıklarının ve ağrı kesici alerjisinin bildirilmesi; korse takıldıktan sonra günlük işlerde yardım ve bol giysi gerekir', 'A feeling of tightness in the first days is normal; numbness, tingling, increasing pain under the cast, a change in skin color, difficulty breathing, or a bad odor from under the brace require immediate medical attention', 'Osjećaj stezanja prvih dana je uobičajen; utrnulost, peckanje, bol koja se pojačava pod gipsom, promjena boje kože, otežano disanje ili neprijatan miris ispod korzeta zahtijevaju hitno obraćanje ljekaru', 'Осјећај стезања првих дана је уобичајен; утрнулост, пецкање, бол која се појачава под гипсом, промјена боје коже, отежано дисање или непријатан мирис испод корзета захтијевају хитно обраћање љекару', 'Ощущение стеснения в первые дни — обычное явление; онемение, покалывание, нарастающая боль под гипсом, изменение цвета кожи, затруднение дыхания или неприятный запах из-под корсета требуют немедленного обращения к врачу', 'Ein Engegefühl in den ersten Tagen ist normal; Taubheit, Kribbeln, zunehmende Schmerzen unter dem Gips, Veränderung der Hautfarbe, Atembeschwerden oder unangenehmer Geruch unter dem Korsett erfordern sofortige ärztliche Hilfe', 'İlk günlerde sıkışıklık hissi normaldir; uyuşma, karıncalanma, alçı altında artan ağrı, ciltte renk değişikliği, solunum güçlüğü veya korse altından kötü koku derhal hekime başvurmayı gerektirir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'fixation-transducer-for-icp-monitoring-in-various-etiologies'), 'Placement of a transducer for continuous measurement of intracranial pressure — an intensive care procedure, not an elective investigation', 'Postavljanje senzora za neprekidno mjerenje intrakranijalnog pritiska — procedura intenzivne njege, a ne planski pregled', 'Постављање сензора за непрекидно мјерење интракранијалног притиска — процедура интензивне његе, а не плански преглед', 'Установка датчика для непрерывного измерения внутричерепного давления — процедура интенсивной терапии, а не плановое обследование', 'Einlegen einer Sonde zur kontinuierlichen Messung des Hirndrucks — eine intensivmedizinische Maßnahme und keine planbare Untersuchung', 'Kafa içi basıncın sürekli ölçümü için sensör yerleştirilmesi — planlı bir tetkik değil, yoğun bakım işlemidir', 'In an operating theatre or intensive care unit, under anesthesia, a neurosurgeon places the transducer through a small opening in the skull and connects it to a monitor; the readings are followed by medical staff around the clock', 'U operacionoj sali ili jedinici intenzivne njege, u anesteziji, neurohirurg kroz mali otvor na lobanji postavlja senzor koji se povezuje sa monitorom; vrijednosti prati medicinsko osoblje neprekidno', 'У операционој сали или јединици интензивне његе, у анестезији, неурохирург кроз мали отвор на лобањи поставља сензор који се повезује са монитором; вриједности прати медицинско особље непрекидно', 'В условиях операционной или реанимации, под анестезией, нейрохирург через небольшое отверстие в черепе устанавливает датчик, который подключается к монитору; показания отслеживает медицинский персонал круглосуточно', 'Im Operationssaal oder auf der Intensivstation setzt ein Neurochirurg die Sonde unter Anästhesie über eine kleine Öffnung im Schädel ein und verbindet sie mit einem Monitor; die Werte werden vom medizinischen Personal rund um die Uhr überwacht', 'Ameliyathane veya yoğun bakımda, anestezi altında beyin cerrahı kafatasındaki küçük bir açıklıktan sensörü yerleştirir ve monitöre bağlar; değerleri sağlık personeli kesintisiz izler', 'Severe head injury, hemorrhage, brain swelling, and other conditions requiring continuous monitoring of intracranial pressure — the decision is made by a neurosurgeon or intensivist', 'Teška povreda glave, krvarenja, edem mozga i druga stanja kada je potrebna stalna kontrola intrakranijalnog pritiska — odluku donosi neurohirurg ili anesteziolog-reanimator', 'Тешка повреда главе, крварења, едем мозга и друга стања када је потребна стална контрола интракранијалног притиска — одлуку доноси неурохирург или анестезиолог-реаниматор', 'Тяжёлая черепно-мозговая травма, кровоизлияния, отёк мозга и другие состояния, когда нужен постоянный контроль внутричерепного давления — решение принимает нейрохирург или реаниматолог', 'Schweres Schädel-Hirn-Trauma, Blutungen, Hirnschwellung und andere Zustände, die eine dauerhafte Überwachung des Hirndrucks erfordern — die Entscheidung trifft der Neurochirurg oder Intensivmediziner', 'Ağır kafa travması, kanamalar, beyin ödemi ve kafa içi basıncın sürekli izlenmesini gerektiren diğer durumlar — kararı beyin cerrahı veya yoğun bakım hekimi verir', 'Preparation is carried out by the medical staff in hospital; consent is given by the patient or their legal representative, and no preparation by the patient is needed', 'Priprema se sprovodi u bolnici od strane medicinskog osoblja; saglasnost daje pacijent ili njegov zakonski zastupnik, a samostalna priprema nije potrebna', 'Припрема се спроводи у болници од стране медицинског особља; сагласност даје пацијент или његов законски заступник, а самостална припрема није потребна', 'Подготовка выполняется медицинским персоналом в стационаре; согласие даёт пациент или его законный представитель, самостоятельная подготовка не требуется', 'Die Vorbereitung übernimmt das medizinische Personal im Krankenhaus; die Einwilligung erteilt der Patient oder sein gesetzlicher Vertreter, eine eigene Vorbereitung ist nicht erforderlich', 'Hazırlık hastanede sağlık personeli tarafından yapılır; onamı hasta veya yasal temsilcisi verir, hastanın kendi hazırlığı gerekmez', 'Pressure values and any changes are interpreted by the intensive care physician together with all other data; the numbers cannot be interpreted outside the clinical context', 'Vrijednosti pritiska i sve promjene procjenjuje ljekar u intenzivnoj njezi zajedno sa ostalim podacima; brojevi se ne mogu tumačiti izvan kliničkog konteksta', 'Вриједности притиска и све промјене процјењује љекар у интензивној њези заједно са осталим подацима; бројеви се не могу тумачити изван клиничког контекста', 'Показатели давления и все изменения оценивает врач в реанимации в связке с остальными данными; интерпретация цифр вне клинического контекста невозможна', 'Die Druckwerte und alle Veränderungen beurteilt der Intensivmediziner im Zusammenhang mit allen weiteren Daten; eine Deutung der Zahlen außerhalb des klinischen Kontexts ist nicht möglich', 'Basınç değerlerini ve tüm değişiklikleri yoğun bakım hekimi diğer verilerle birlikte değerlendirir; sayılar klinik bağlam dışında yorumlanamaz')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

INSERT INTO medical_service_reference_info (medical_service_id, what_en, what_sr, what_sr_cyrl, what_ru, what_de, what_tr, how_en, how_sr, how_sr_cyrl, how_ru, how_de, how_tr, indications_en, indications_sr, indications_sr_cyrl, indications_ru, indications_de, indications_tr, prep_en, prep_sr, prep_sr_cyrl, prep_ru, prep_de, prep_tr, abnormal_en, abnormal_sr, abnormal_sr_cyrl, abnormal_ru, abnormal_de, abnormal_tr)
VALUES ((SELECT id FROM medical_services WHERE slug = 'therapeutic-massage-partial'), 'Therapeutic massage of a single body area — the back, the neck and shoulder region or a limb', 'Terapijska masaža jedne regije tijela — leđa, vratno-ramenog pojasa ili ekstremiteta', 'Терапијска масажа једне регије тијела — леђа, вратно-раменог појаса или екстремитета', 'Лечебный массаж одной зоны тела — спины, шейно-воротниковой зоны или конечности', 'Therapeutische Massage eines einzelnen Körperbereichs — Rücken, Nacken-Schulter-Bereich oder einer Extremität', 'Vücudun tek bir bölgesine — sırt, boyun-omuz bölgesi veya bir uzva — uygulanan tedavi amaçlı masaj', 'A doctor or physiotherapist works the muscles and soft tissue of the chosen area by hand; a session usually takes 15–20 minutes', 'Ljekar ili fizioterapeut rukama obrađuje mišiće i meka tkiva izabrane regije; seansa obično traje 15–20 minuta', 'Љекар или физиотерапеут рукама обрађује мишиће и мека ткива изабране регије; сеанса обично траје 15–20 минута', 'Врач или физиотерапевт руками прорабатывает мышцы и мягкие ткани выбранной области; сеанс обычно занимает 15–20 минут', 'Arzt oder Physiotherapeut bearbeitet Muskeln und Weichgewebe des gewählten Bereichs manuell; eine Sitzung dauert in der Regel 15–20 Minuten', 'Hekim veya fizyoterapist seçilen bölgenin kas ve yumuşak dokularını elle çalışır; seans genellikle 15–20 dakika sürer', 'Muscle tension and pain in a specific area, recovery after injury, the effects of sedentary work, as part of a physiotherapy course', 'Mišićna napetost i bol u određenoj regiji, oporavak nakon povreda, posljedice sjedećeg načina rada, kao dio fizioterapijskog programa', 'Мишићна напетост и бол у одређеној регији, опоравак након повреда, посљедице сједећег начина рада, као дио физиотерапијског програма', 'Мышечное напряжение и боль в конкретной зоне, восстановление после травм, последствия сидячей работы, как часть курса физиотерапии', 'Muskelverspannung und Schmerzen in einem bestimmten Bereich, Erholung nach Verletzungen, Folgen sitzender Tätigkeit, als Teil eines physiotherapeutischen Programms', 'Belirli bir bölgede kas gerginliği ve ağrı, yaralanma sonrası iyileşme, hareketsiz çalışmanın etkileri, fizik tedavi programının parçası olarak', 'No special preparation is needed; massage is not performed immediately after a meal', 'Posebna priprema nije potrebna; masaža se ne radi neposredno nakon obroka', 'Посебна припрема није потребна; масажа се не ради непосредно након оброка', 'Специальной подготовки не требуется; массаж не делают сразу после еды', 'Keine besondere Vorbereitung erforderlich; die Massage wird nicht unmittelbar nach dem Essen durchgeführt', 'Özel bir hazırlık gerekmez; masaj yemekten hemen sonra yapılmaz', 'This is a treatment, not a diagnostic procedure — the result is judged by how the symptoms change. If pain increases or numbness appears, tell the doctor', 'Ovo je terapijska, a ne dijagnostička procedura — rezultat se procjenjuje po promjeni simptoma. Ako se bol pojačava ili se javi utrnulost, treba obavijestiti ljekara', 'Ово је терапијска, а не дијагностичка процедура — резултат се процјењује по промјени симптома. Ако се бол појачава или се јави утрнулост, треба обавијестити љекара', 'Это лечебная, а не диагностическая процедура — результат оценивают по динамике симптомов. Если боль усиливается или появляется онемение, нужно сообщить врачу', 'Dies ist eine Behandlung, keine Diagnostik — der Erfolg wird am Verlauf der Beschwerden beurteilt. Nehmen Schmerzen zu oder tritt Taubheitsgefühl auf, sollte der Arzt informiert werden', 'Bu tanısal değil tedavi edici bir işlemdir — sonuç belirtilerin seyrine göre değerlendirilir. Ağrı artarsa veya uyuşma olursa hekime bildirilmelidir')
ON DUPLICATE KEY UPDATE what_en=VALUES(what_en), what_sr=VALUES(what_sr), what_sr_cyrl=VALUES(what_sr_cyrl), what_ru=VALUES(what_ru), what_de=VALUES(what_de), what_tr=VALUES(what_tr), how_en=VALUES(how_en), how_sr=VALUES(how_sr), how_sr_cyrl=VALUES(how_sr_cyrl), how_ru=VALUES(how_ru), how_de=VALUES(how_de), how_tr=VALUES(how_tr), indications_en=VALUES(indications_en), indications_sr=VALUES(indications_sr), indications_sr_cyrl=VALUES(indications_sr_cyrl), indications_ru=VALUES(indications_ru), indications_de=VALUES(indications_de), indications_tr=VALUES(indications_tr), prep_en=VALUES(prep_en), prep_sr=VALUES(prep_sr), prep_sr_cyrl=VALUES(prep_sr_cyrl), prep_ru=VALUES(prep_ru), prep_de=VALUES(prep_de), prep_tr=VALUES(prep_tr), abnormal_en=VALUES(abnormal_en), abnormal_sr=VALUES(abnormal_sr), abnormal_sr_cyrl=VALUES(abnormal_sr_cyrl), abnormal_ru=VALUES(abnormal_ru), abnormal_de=VALUES(abnormal_de), abnormal_tr=VALUES(abnormal_tr);

